LIST_TOKEN = re.compile(r'\s*(\(|\)|[-!]?(?:[A-Za-z_][\w.]*(?:!=|>=|<=|[:~=<>]))?'
                        r'(?:"[^"]*"?|[^\s()"]+)|"[^"]*"?)')
LIST_TERM = re.compile(r'^([-!]?)([A-Za-z_][\w]*)(!=|>=|<=|[:~=<>])(.*)\Z', re.S)


def memory_search(listname, create, cols, rows, text):
    """Rows that live nowhere a query can reach - the outgoing mail, a
    backup being read - searched with the very words every list takes
    (1.0.96): put into a table in memory, and the list's query run there.
    Returns the indexes of the rows that match."""
    lq = ListQuery(listname, text)
    import sqlite3
    conn = sqlite3.connect(':memory:')
    try:
        conn.execute(create)
        conn.executemany('INSERT INTO t (%s) VALUES (%s)' % (', '.join(['i'] + list(cols)),
                                                          ', '.join('?' * (len(cols) + 1))),
                         [[i] + [r.get(c) for c in cols] for i, r in enumerate(rows)])
        where, args = [], []
        if lq.sql:
            where.append(lq.sql)
            args += list(lq.args)
        if lq.words:
            w = lq._word(lq.words)
            where.append(w[0])
            args += list(w[1])
        sql = 'SELECT i FROM t' + (' WHERE ' + ' AND '.join('(%s)' % x for x in where)
                                   if where else '')
        return [r[0] for r in conn.execute(sql, args)]
    finally:
        conn.close()


class ListQueryError(ValueError):
    pass


def log_node():
    """The node a log line is written on (1.0.45) - whose it is, in a
    cluster."""
    try:
        return node_name()[:190]
    except Exception:                                   # noqa: BLE001
        return ''


# A phone number found however it is written (1.0.93): +420 603 364 754,
# 603364754, 00420-603-364-754 - the digits of the token's number compared
# with the digits typed, its country code or not.
DEST_DIGITS_SQL = "REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(dest, ''), " \
    "' ', ''), '-', ''), '+', ''), '/', ''), '.', ''), '(', ''), ')', '')"


def phone_digits(text):
    """The digits of something typed that looks like a phone number - and
    `*` kept as a wildcard - or '' for anything else."""
    t = str(text or '').strip()
    if not re.fullmatch(r'[\d\s+()./*-]+', t):
        return ''
    d = re.sub(r'[^\d*]', '', t)
    if d.startswith('00'):
        d = d[2:]
    return d if len(d.replace('*', '')) >= 3 else ''


def like_pattern(text):
    """`*` a wildcard, everything else itself; `!` is the escape."""
    out = ''
    for c in str(text):
        if c == '*':
            out += '%'
        elif c in '%_!':
            out += '!' + c
        else:
            out += c
    return out


class ListQuery(object):
    """`sql`/`args` is the piece of the WHERE the fields make (empty where
    there are none); `words` is what goes to the list's own word search."""

    def __init__(self, listname, text):
        self.list = listname
        self.fields = LIST_FIELDS.get(listname, {})
        self.text = str(text or '').strip()
        self.sql, self.args, self.words = '', [], self.text
        if len(self.text) > 2000:
            raise ListQueryError('that search is too long - 2000 characters at most')
        self.tokens = [m.group(1) for m in LIST_TOKEN.finditer(self.text) if m.group(1)]
        if not any(self._field(t) for t in self.tokens):
            return
        if len(self.tokens) > 300:
            raise ListQueryError('that search has too many parts')
        # NOT on NOT on NOT, or bracket in bracket, a few hundred deep, made
        # SQLite give up parsing (1.0.33): twenty is more than anybody writes.
        if sum(1 for t in self.tokens if t in ('NOT', '!', '(')) > 40:
            raise ListQueryError('that search has too many NOTs and brackets in it')
        self.at, self.top_words = 0, []
        node = self._or(True)
        if self.at < len(self.tokens):
            raise ListQueryError('a closing bracket with nothing open before it')
        words = [w.strip('"') for w in self.top_words if w.strip('"')]
        self.words = words[0] if words else ''
        node = self._join('AND', [node] + [self._word(w) for w in words[1:]])
        if node:
            self.sql, self.args = node

    def _field(self, token):
        m = LIST_TERM.match(token or '')
        return m if m and m.group(2).lower() in self.fields else None

    def _peek(self):
        return self.tokens[self.at] if self.at < len(self.tokens) else None

    @staticmethod
    def _join(op, parts):
        parts = [p for p in parts if p]
        if not parts:
            return None
        if len(parts) == 1:
            return parts[0]
        return ('(' + (' %s ' % op).join(p[0] for p in parts) + ')',
                [a for p in parts for a in p[1]])

    def _or(self, top=False):
        parts, alone = [self._and(top)], True
        while self._peek() in ('OR', '|', '||'):
            alone = False
            self.at += 1
            if self._peek() in (None, ')'):
                raise ListQueryError('OR with nothing after it')
            parts.append(self._and(False))
        if not alone and top and self.top_words:
            raise ListQueryError('a word on its own beside OR - write it as a field, or put '
                                 'the OR in brackets')
        return self._join('OR', parts)

    def _and(self, top):
        parts = [self._not(top)]
        while self._peek() not in (None, ')', 'OR', '|', '||'):
            if self._peek() in ('AND', '&', '&&'):
                self.at += 1
                continue
            parts.append(self._not(top))
        return self._join('AND', parts)

    def _not(self, top):
        t = self._peek()
        if t in ('NOT', '!'):
            self.at += 1
            inner = self._not(False)
            return ('NOT COALESCE((%s), 1=0)' % inner[0], inner[1]) if inner else None
        if t == '(':
            self.at += 1
            inner = self._or(False)
            if self._peek() != ')':
                raise ListQueryError('a bracket opened and never closed')
            self.at += 1
            return inner
        if t == ')':
            raise ListQueryError('a closing bracket with nothing open before it')
        if t is None:
            # The end, where a word was still to come (1.0.103): "x !" or
            # "x (" read past the end and failed with a TypeError.
            raise ListQueryError('NOT, ! or a bracket with nothing after it')
        self.at += 1
        return self._leaf(t, top)

    def _word(self, word):
        cols = LIST_WORD_COLUMNS.get(self.list, ())
        like = '%' + like_pattern(word.lower()) + '%'
        sql = ["LOWER(COALESCE(%s, '')) LIKE ? ESCAPE '!'" % c for c in cols]
        args = [like] * len(cols)
        digits = phone_digits(word) if 'dest' in cols else ''
        if digits:
            sql.append("%s LIKE ? ESCAPE '!'" % DEST_DIGITS_SQL)
            args.append('%' + like_pattern(digits) + '%')
        return ('(' + ' OR '.join(sql) + ')', args)

    def _leaf(self, token, top):
        m = self._field(token)
        if not m:
            lead = token[:1] if token[:1] in '-!' and len(token) > 1 else ''
            word = token[len(lead):].strip('"')
            if not word:
                return None
            if top and not lead:
                self.top_words.append(token)
                return None
            w = self._word(word)
            return ('NOT (%s)' % w[0], w[1]) if lead else w
        lead, name, op, value = m.groups()
        column, kind = self.fields[name.lower()]
        self._name = name.lower()
        quoted = value.startswith('"')
        value = value.strip('"')
        if value == '':
            return None                      # still being typed
        neg = bool(lead) != (op == '!=')
        if kind == 'none':
            clause = ('1=0', [])
        else:
            items = [value] if quoted else [v for v in value.split(',') if v.strip()]
            clause = self._join('OR', [self._one(column, kind, op, v.strip()) for v in items])
        if neg:
            return ('NOT COALESCE((%s), 1=0)' % clause[0], clause[1])
        return clause

    def _one(self, col, kind, op, item):
        low = item.lower()
        cmp = (op in (':', '=')) and re.match(r'^(>=|<=|>|<)\s*(.+)\Z', low)
        if cmp:
            op, low = cmp.group(1), cmp.group(2)
        if kind == 'num':
            rng = re.match(r'^(-?[\d.]+)\s*-\s*(-?[\d.]+)\Z', low)
            try:
                if rng:
                    return ('(%s BETWEEN ? AND ?)' % col, [float(rng.group(1)),
                                                           float(rng.group(2))])
                n = float(low)
            except ValueError:
                raise ListQueryError('%s is a number - %r is not one' % (getattr(self, '_name', col), item))
            sign = {'>': '>', '<': '<', '>=': '>=', '<=': '<='}.get(op, '=')
            return ('(%s %s ?)' % (col, sign), [n])
        if op in ('>', '<', '>=', '<='):
            raise ListQueryError('only a number can be more or less than something')
        if kind == 'ok':
            v = {'accept': 1, 'accepted': 1, 'right': 1, 'yes': 1, 'ok': 1, 'reject': 0,
                 'rejected': 0, 'wrong': 0, 'no': 0, 'refused': 0}.get(low)
            if v is None:
                return ('1=0', [])
            return ('ok = ?', [v])
        if kind == 'tkind':
            v = {'app': 'totp', 'totp': 'totp', 'phone': 'totp', 'mail': 'mail',
                 'email': 'mail', 'e-mail': 'mail', 'sms': 'sms', 'text': 'sms'}.get(low)
            if v is None:
                raise ListQueryError('kind is app, mail or sms - not %r' % item)
            return ("(CASE WHEN %s IN ('mail', 'sms') THEN %s ELSE 'totp' END) = ?" % (col, col),
                    [v])
        if kind == 'tlang':
            # The language in effect: the token's own, else the setting's.
            if low not in ('cs', 'en'):
                raise ListQueryError('lang is cs or en - not %r' % item)
            return ("(CASE WHEN %s IN ('cs', 'en') THEN %s ELSE ? END) = ?" % (col, col),
                    [code_lang(), low])
        if kind == 'tfmt':
            v = {'html': 'html', 'text': 'text', 'plain': 'text', 'txt': 'text'}.get(low)
            if v is None:
                raise ListQueryError('mail is html or text - not %r' % item)
            return ("(kind = 'mail' AND (CASE WHEN %s IN ('html', 'text') THEN %s ELSE ? END) = ?)"
                    % (col, col), ['text' if CONFIG.get('code_mail_fmt') == 'text' else 'html', v])
        if kind == 'tdest':
            digits = phone_digits(low)
            if digits:
                # A number: its digits, the country code in front or not.
                pat = like_pattern(digits)
                return ("%s LIKE ? ESCAPE '!'" % DEST_DIGITS_SQL,
                        ['%' + pat + ('%' if op == '~' or '*' in digits else '')])
            kind = 'text'
        if kind == 'realm':
            pat = '%@' + like_pattern(low.lstrip('@'))
            return ("LOWER(%s) LIKE ? ESCAPE '!'" % col, [pat if op != '~' else pat + '%'])
        if kind == 'step':
            marks = dict(Storage.ENROL_STEPS)
            if low not in marks:
                return ('1=0', [])
            return ("%s LIKE ? ESCAPE '!'" % col, ['%' + like_pattern(marks[low]) + '%'])
        if kind == 'fromip':
            return ("LOWER(%s) LIKE ? ESCAPE '!'" % col,
                    ['% from ' + like_pattern(low.rstrip('*')) + '%'])
        if kind == 'node':
            return ("LOWER(%s) LIKE ? ESCAPE '!'" % col, ['% on ' + like_pattern(low) + '%'])
        if kind == 'ip' and '/' in low and op != '~':
            try:
                net = ipaddress.ip_network(low, strict=False)
            except ValueError:
                raise ListQueryError('%r is not an address or a range of them' % item)
            if net.version == 4 and net.prefixlen % 8 == 0:
                keep = '.'.join(str(net.network_address).split('.')[:net.prefixlen // 8])
                return ("LOWER(%s) LIKE ? ESCAPE '!'" % col,
                        [like_pattern(keep) + ('.%' if keep else '%')])
            raise ListQueryError('a range is /8, /16 or /24 here')
        c = "LOWER(COALESCE(%s, ''))" % col
        if op == '~':
            return ("%s LIKE ? ESCAPE '!'" % c, ['%' + like_pattern(low) + '%'])
        if kind == 'ip' and '*' not in low:
            # An address as it was written down may carry its port.
            return ("(%s = ? OR %s LIKE ? ESCAPE '!')" % (c, c), [low, like_pattern(low) + ':%'])
        if '*' in low:
            return ("%s LIKE ? ESCAPE '!'" % c, [like_pattern(low)])
        return ('%s = ?' % c, [low])

def old_methods_of(store, ident):
    """The kinds of token a realm offers as it is saved (a save that did
    not say keeps them, 1.0.76)."""
    if not ident:
        return None
    try:
        return store.db.value('SELECT methods FROM realms WHERE id = ?', (int(ident),))
    except Exception:                                   # noqa: BLE001
        return None


def list_position(v):
    """A place in a list: a whole number, not past what the database holds
    (1.0.103: 1e20 broke the save with a 500)."""
    try:
        n = int(float(v or 0))
    except (TypeError, ValueError, OverflowError):
        raise ValueError('the position is a number')
    return max(-1000000, min(1000000, n))


ACCOUNT_NAME_RE = re.compile(r'[A-Za-z0-9][A-Za-z0-9._@\\-]{0,120}\Z')


class Storage(object):
    """Everything this daemon keeps, over whichever database it is."""

    @classmethod
    def view(cls, db):
        """The same database through another connection, nothing made
        (1.0.101)."""
        st = cls.__new__(cls)
        st.db = db
        st.lock = threading.RLock()
        st._clients = None
        st._realms = None
        st._dirs = None
        return st

    def __init__(self, db):
        self.db = db
        self.db.make_tables()
        if CONFIG.get('ha_mode') == 'replicated' and db.engine == 'postgres':
            # A table new in this version numbered on this node's side of odd
            # and even before anything is written to it (1.0.101).
            try:
                ha_sequences_check(db, int(CONFIG.get('ha_slot') or 1))
            except Exception as e:                      # noqa: BLE001
                log('the numbering of the tables could not be checked: %s' % e, 'warn')
        self.lock = threading.RLock()
        self._clients = None
        self._realms = None
        self._dirs = None

    # ---- meta, settings, events ------------------------------------------
    def get_meta(self, k, default=None):
        got = self.db.value('SELECT v FROM meta WHERE k = ?', (k,))
        return default if got is None else got

    def set_meta(self, k, v):
        with self.lock:
            self.db.upsert('meta', 'k', {'k': k, 'v': str(v)})

    def settings_saved(self):
        out = {}
        for r in self.db.rows('SELECT k, v FROM settings'):
            try:
                out[r['k']] = json.loads(r['v'])
            except (TypeError, ValueError):
                continue
        return out

    def settings_written(self):
        return {r['k']: {'at': r['at'], 'by': r['by_who']}
                for r in self.db.rows('SELECT k, at, by_who FROM settings')}

    def save_setting(self, k, v, by=''):
        with self.lock:
            self.db.upsert('settings', 'k', {'k': k, 'v': json.dumps(v), 'at': time.time(),
                                             'by_who': str(by or '')[:190]})

    def drop_setting(self, k):
        self.db.run('DELETE FROM settings WHERE k = ?', (k,))

    def add_event(self, kind, words, level='info', who=''):
        if HA_REBUILDING.is_set():
            log('(not written while the node is rebuilt) %s: %s' % (kind, words))
            return None
        try:
            self.db.insert('events', {'ts': time.time(), 'kind': str(kind)[:60],
                                      'node': log_node(),
                                      'level': level, 'who': str(who or '')[:190],
                                      'words': str(words)[:4000]})
        except Exception as e:
            log('the event could not be written down: %s (%s)' % (words, e), 'warn')
        log('%s: %s%s' % (kind, words, (' (%s)' % who) if who else ''),
            'warn' if level in ('warn', 'bad') else 'info')
        hook = getattr(self, 'on_event', None)
        if hook:
            try:
                hook(kind, words, level, who)
            except Exception:
                pass

    def events(self, limit=100, offset=0, q='', kind='', extra=None):
        where, args = [], []
        if extra and extra[0]:
            where.append(extra[0])
            args += list(extra[1])
        if q:
            where.append("(LOWER(words) LIKE ? ESCAPE '!' OR LOWER(who) LIKE ? ESCAPE '!' OR LOWER(kind) LIKE ? ESCAPE '!')")
            like = '%' + like_pattern(str(q).lower()) + '%'
            args += [like, like, like]
        if kind:
            where.append('kind = ?')
            args.append(kind)
        sql = ' WHERE ' + ' AND '.join(where) if where else ''
        total = self.db.value('SELECT COUNT(*) AS n FROM events' + sql, args, 0)
        rows = self.db.rows('SELECT * FROM events' + sql + ' ORDER BY ts DESC, id DESC '
                            'LIMIT %d OFFSET %d' % (int(limit), int(offset)), args)
        return rows, int(total or 0)

    # ---- the enrolment pages: who came, what they did (1.0.16) ------------
    # The events of kind 'enrolment' tell the whole story of a person making
    # their own token; here they are read back as steps, so the pages can
    # draw them as a card of their own and count them.
    ENROL_STEPS = (('signed_in', ' signed in to the enrolment pages'),
                   ('enrolled', ' enrolled a token for themselves'),
                   ('confirmed', ' confirmed their token'),
                   ('replacing', ' is replacing their token'),
                   ('refused', ' could not sign in to the enrolment pages'),
                   ('not_allowed', ' may not enrol a token'),
                   ('stopped', ' stopped replacing their token'))

    @classmethod
    def enrol_step(cls, words):
        for step, mark in cls.ENROL_STEPS:
            if mark in words:
                return step
        return 'other'

    def enrolment(self, limit=100, offset=0, q='', step='', since_s=0, extra=None):
        where, args = ["kind = 'enrolment'"], []
        if extra and extra[0]:
            where.append(extra[0])
            args += list(extra[1])
        if since_s:
            where.append('ts > ?')
            args.append(time.time() - float(since_s))
        if q:
            where.append("(LOWER(words) LIKE ? ESCAPE '!' OR LOWER(who) LIKE ? ESCAPE '!')")
            like = '%' + like_pattern(str(q).lower()) + '%'
            args += [like, like]
        marks = dict(self.ENROL_STEPS)
        if step in marks:
            where.append('words LIKE ?')
            args.append('%' + marks[step] + '%')
        sql = ' WHERE ' + ' AND '.join(where)
        total = self.db.value('SELECT COUNT(*) AS n FROM events' + sql, args, 0)
        rows = self.db.rows('SELECT * FROM events' + sql + ' ORDER BY ts DESC, id DESC '
                            'LIMIT %d OFFSET %d' % (int(limit), int(offset)), args)
        out = []
        for r in rows:
            words = str(r.get('words') or '')
            m = re.search(r' from (\S+?)(?::|$)', words)
            out.append({'id': r['id'], 'ts': r['ts'], 'who': r.get('who') or '',
                        'step': self.enrol_step(words), 'src': m.group(1) if m else '',
                        'words': words, 'level': r.get('level') or 'info',
                        'node': r.get('node') or ''})
        return out, int(total or 0)

    def enrolment_counts(self, since_s=0, since=0, until=0):
        """How many of each step in the window - the tiles over the list, in
        one pass over the window (1.0.57), not one per step."""
        parts, args = [], []
        for _step, mark in self.ENROL_STEPS:
            parts.append('SUM(CASE WHEN words LIKE ? THEN 1 ELSE 0 END) AS c%d' % len(parts))
            args.append('%' + mark + '%')
        sql = "SELECT %s FROM events WHERE kind = 'enrolment'" % ', '.join(parts)
        if since_s:
            sql += ' AND ts > ?'
            args.append(time.time() - float(since_s))
        if since:
            sql += ' AND ts >= ?'
            args.append(float(since))
        if until:
            sql += ' AND ts < ?'
            args.append(float(until))
        row = (self.db.rows(sql, args) or [{}])[0]
        return {step: int(row.get('c%d' % i) or 0) for i, (step, _m) in enumerate(self.ENROL_STEPS)}

    def list_values(self, listname, field, typed='', since=0, most=15):
        """What one field of one list holds, busiest first, for the search
        box over it to offer as somebody types (1.0.19, as isemon)."""
        spec = LIST_FIELDS.get(listname, {}).get(field)
        if not spec:
            return []
        column, kind = spec
        typed = str(typed or '').strip().lower()
        if kind == 'step':
            return [{'val': k, 'n': 0} for k, _ in self.ENROL_STEPS if typed in k]
        if kind in ('tkind', 'tlang', 'tfmt'):
            # Fixed choices (1.0.85), not whatever the column happens to hold.
            opts = {'tkind': ('app', 'mail', 'sms'), 'tlang': ('cs', 'en'),
                    'tfmt': ('html', 'text')}[kind]
            return [{'val': v, 'n': 0} for v in opts if v.startswith(typed)]
        if kind == 'ok':
            return [{'val': v, 'n': 0} for v in ('accept', 'reject') if v.startswith(typed)]
        if kind == 'none' or not column:
            return []
        if kind == 'text' and column == 'words':
            return []           # never offered - not grouped over every event first (1.0.57)
        table = {'tokens': 'tokens', 'radius': 'radius_log', 'otp': 'otp_log',
                 'events': 'events', 'enrolment': 'events'}[listname]
        where, args = [], []
        # A window always (1.0.57): with none, every keystroke grouped the
        # whole log - seconds on a big one, with RADIUS waiting behind it.
        if not since and table != 'tokens':
            since = time.time() - 30 * 86400
        if since and table != 'tokens':
            where.append('ts >= ?')
            args.append(since)
        if listname == 'enrolment':
            where.append("kind = 'enrolment'")
        # A number is compared as a number (1.0.33): PostgreSQL refuses
        # COALESCE(a number, '') - the suggestions for "recovery codes" broke.
        if kind == 'num':
            where.append('%s IS NOT NULL' % column)
        else:
            where.append("COALESCE(%s, '') <> ''" % column)
        sql = ' WHERE ' + ' AND '.join(where)
        rows = self.db.rows('SELECT %s AS val, COUNT(*) AS n FROM %s%s GROUP BY %s '
                            'ORDER BY n DESC LIMIT 2000' % (column, table, sql, column), args)
        got = collections.Counter()
        for r in rows:
            v = str(r['val'])
            if kind == 'realm':
                v = v.rsplit('@', 1)[1] if '@' in v else ''
            elif kind == 'ip':
                v = re.sub(r':\d+$', '', v) if v.count(':') == 1 else v
            elif kind == 'fromip':
                m = re.search(r' from (\S+?)(?::|$)', v)
                v = m.group(1) if m else ''
            elif kind == 'node':
                m = re.search(r' on (\S+)', v)
                v = m.group(1).rstrip(',') if m else ''
            elif kind == 'text' and column == 'words':
                continue
            if v:
                got[v] += int(r['n'] or 0)
        out = [{'val': v, 'n': n} for v, n in got.items()
               if not typed or typed.strip('*') in v.lower()]
        out.sort(key=lambda x: (not x['val'].lower().startswith(typed.strip('*')), -x['n'],
                                x['val'].lower()))
        return out[:most]

    _KINDS = (0.0, [])

    def event_kinds(self):
        # Kept a minute (1.0.57): every page of Events read the whole table
        # for its few kinds.
        at, kinds = Storage._KINDS
        if time.time() - at < 60 and kinds:
            return kinds
        kinds = [r['kind'] for r in self.db.rows('SELECT DISTINCT kind FROM events ORDER BY kind')]
        Storage._KINDS = (time.time(), kinds)
        return kinds

    # ---- accounts of the administration pages ----------------------------
    def accounts(self):
        rows = self.db.rows('SELECT * FROM accounts ORDER BY name')
        for r in rows:
            r.pop('pw', None)
            # How somebody laid out their tables is theirs and can be big:
            # only whether there is any, for the Accounts list.
            r['cols_tables'] = len(self._cols_of(r.pop('cols', None)))
            r.pop('cols_at', None)
        return rows

    def account(self, name):
        return self.db.row('SELECT * FROM accounts WHERE LOWER(name) = ?',
                           (str(name or '').strip().lower(),))

    def add_account(self, name, role, password=None, source='local', note='', must_change=0,
                    display='', dn='', groups=''):
        name = str(name or '').strip()
        if not ACCOUNT_NAME_RE.match(name):
            raise ValueError('a name has letters, digits, dots, dashes, @ and nothing else')
        if role not in ROLES_ALL:
            raise ValueError('the role is one of %s' % ', '.join(ROLES_ALL))
        if self.account(name):
            raise ValueError('there is an account called %s already' % name)
        if source == 'local':
            bad = password_problem(password)
            if bad:
                raise ValueError(bad)
        return self.db.insert('accounts', {
            'name': name, 'role': role, 'pw': password_hash(password) if password else '',
            'source': source, 'disabled': 0, 'must_change': int(bool(must_change)),
            'note': str(note or '')[:400], 'created': time.time(), 'last_in': None,
            'last_from': '', 'prefs': '{}', 'display': display, 'dn': dn,
            'group_list': groups})

    def set_account(self, name, **fields):
        one = self.account(name)
        if not one:
            raise ValueError('there is no account called %s' % name)
        if 'password' in fields:
            bad = password_problem(fields['password'])
            if bad:
                raise ValueError(bad)
            fields['pw'] = password_hash(fields.pop('password'))
        if 'role' in fields and fields['role'] not in ROLES_ALL:
            raise ValueError('the role is one of %s' % ', '.join(ROLES_ALL))
        self.db.update('accounts', one['id'], fields)

    def drop_account(self, name):
        one = self.account(name)
        if not one:
            raise ValueError('there is no account called %s' % name)
        self.db.run('DELETE FROM accounts WHERE id = ?', (one['id'],))
        self.db.run('DELETE FROM sessions WHERE kind = ? AND LOWER(name) = ?',
                    ('admin', one['name'].lower()))

    # ---- how somebody laid out the tables (as on isemon, 1.10.146 on) -------
    COLS_MOST_TABLES = 300
    COLS_MOST_COLUMNS = 60
    COLS_MOST_BYTES = 60000

    @staticmethod
    def _cols_of(text):
        if not text:
            return {}
        try:
            got = json.loads(text)
        except (TypeError, ValueError):
            return {}
        return got if isinstance(got, dict) else {}

    @classmethod
    def clean_cols(cls, cols):
        """A layout as the page sent it, reduced to what a layout can hold:
        `{table: {"w": {column: pixels}, "o": [order], "h": [hidden],
        "v": [optional shown], "s": [empty columns], "t": when}}` and nothing
        else. Anything not understood is dropped rather than kept."""
        if cols == [] or cols is None:
            cols = {}                       # PHP passes an empty object on as []
        if not isinstance(cols, dict):
            raise ValueError('a layout of the columns is an object of tables')
        out = {}

        def names(v, most):
            return [str(c)[:80] for c in v[:most] if isinstance(c, (str, int))] \
                if isinstance(v, list) else []

        for key, one in list(cols.items())[:cls.COLS_MOST_TABLES]:
            key = str(key)[:160]
            if not key or not isinstance(one, dict):
                continue
            kept = {}
            widths = one.get('w')
            if isinstance(widths, dict):
                w = {}
                for col, px in list(widths.items())[:cls.COLS_MOST_COLUMNS]:
                    try:
                        px = int(round(float(px)))
                    except (TypeError, ValueError, OverflowError):
                        continue
                    w[str(col)[:80]] = max(24, min(3000, px))
                if w:
                    kept['w'] = w
            for k in ('o', 'h', 'v'):
                got = names(one.get(k), cls.COLS_MOST_COLUMNS)
                if got:
                    kept[k] = got
            sp = [c for c in names(one.get('s'), 20) if re.match(r'^~\d{1,4}\Z', c)]
            if sp:
                kept['s'] = sp
            if kept:
                try:
                    kept['t'] = int(float(one.get('t') or 0))
                except (TypeError, ValueError, OverflowError):
                    kept['t'] = 0
                out[key] = kept
        if len(json.dumps(out, separators=(',', ':'))) > cls.COLS_MOST_BYTES:
            raise ValueError('that layout of the columns is too big to keep (more than %d '
                             'characters)' % cls.COLS_MOST_BYTES)
        return out

    def user_cols(self, name):
        """How this person has laid out the tables, or {} for as they come."""
        try:
            one = self.account(name)
        except Exception:                               # noqa: BLE001
            return {}
        return self._cols_of(one.get('cols')) if one else {}

    def put_user_cols(self, name, cols):
        """Keep this person's layout; an empty one puts every table back."""
        one = self.account(name)
        if not one:
            raise ValueError('there is no account called %s' % name)
        cols = self.clean_cols(cols or {})
        self.db.update('accounts', one['id'], {
            'cols': json.dumps(cols, separators=(',', ':')) if cols else None,
            'cols_at': time.time()})
        return cols

    @staticmethod
    def clean_prefs(prefs):
        if prefs == [] or prefs is None:
            prefs = {}
        if not isinstance(prefs, dict):
            raise ValueError('the choices are an object')
        out = {}
        if 'lang' in prefs:
            if str(prefs['lang']) not in ('cs', 'en'):
                raise ValueError('no such language here: %s' % prefs['lang'])
            out['lang'] = str(prefs['lang'])
        return out

    def user_prefs(self, name):
        one = self.account(name)
        return self._cols_of(one.get('prefs')) if one else {}

    def put_user_prefs(self, name, prefs):
        one = self.account(name)
        if not one:
            raise ValueError('there is no account called %s' % name)
        kept = dict(self._cols_of(one.get('prefs')))
        kept.update(self.clean_prefs(prefs))
        self.db.update('accounts', one['id'], {'prefs': json.dumps(kept)})
        return kept

    def fulladmins_left(self, but=''):
        return sum(1 for a in self.accounts() if a['role'] == 'fulladmin' and not a['disabled']
                   and a['name'].lower() != str(but).lower())

    # ---- sessions ----------------------------------------------------------
    def session_new(self, kind, name, role, ip, hours, data=None):
        token = secrets.token_urlsafe(32)
        t = time.time()
        self.db.insert('sessions', {
            'token_hash': hashlib.sha256(token.encode()).hexdigest(), 'kind': kind,
            'name': name, 'role': role, 'created': t, 'last': t,
            'expires': t + float(hours) * 3600, 'ip': str(ip or '')[:60],
            'data': json.dumps(data or {})})
        return token

    def session_get(self, token, kind, idle_s, touch=True):
        if not token:
            return None
        row = self.db.row('SELECT * FROM sessions WHERE token_hash = ? AND kind = ?',
                          (hashlib.sha256(str(token).encode()).hexdigest(), kind))
        if not row:
            return None
        t = time.time()
        if row['expires'] < t or t - float(row['last'] or 0) > idle_s:
            self.db.run('DELETE FROM sessions WHERE id = ?', (row['id'],))
            return None
        if touch and t - float(row['last'] or 0) > 20:
            self.db.run('UPDATE sessions SET last = ? WHERE id = ?', (t, row['id']))
        try:
            row['data'] = json.loads(row.get('data') or '{}')
        except ValueError:
            row['data'] = {}
        return row

    def session_take(self, ident, field):
        """`field` taken out of a session's data, by one request only
        (1.0.101): written back only if nobody changed the data meanwhile.
        True if this request took it."""
        for _round in range(8):
            raw = self.db.value('SELECT data FROM sessions WHERE id = ?', (ident,))
            if raw is None:
                return False
            try:
                data = json.loads(raw or '{}')
            except ValueError:
                return False
            if field not in data:
                return False
            data.pop(field, None)
            if self.db.run('UPDATE sessions SET data = ? WHERE id = ? AND data = ?',
                           (json.dumps(data), ident, raw)):
                return True
        return False

    def session_merge(self, ident, changes, expect=None):
        """Only the keys given changed in a session's data, over what the
        database holds now (1.0.101): the whole of a copy read at the start of
        a request, written back at its end, put back what another request
        had taken meanwhile - a code already used became usable again.
        None as a value takes the key out. The data as it is now."""
        data = {}
        for _round in range(8):
            raw = self.db.value('SELECT data FROM sessions WHERE id = ?', (ident,))
            if raw is None:
                return None
            try:
                data = json.loads(raw or '{}')
            except ValueError:
                data = {}
            # `expect`: written only while these keys still hold what the
            # caller read - else nothing, and False.
            for k, v in (expect or {}).items():
                if data.get(k) != v:
                    return False
            for k, v in changes.items():
                if v is None:
                    data.pop(k, None)
                else:
                    data[k] = v
            if self.db.run('UPDATE sessions SET data = ? WHERE id = ? AND data = ?',
                           (json.dumps(data), ident, raw)):
                return data
        return data

    def session_count_try(self, ident, field, code, most):
        """A wrong try counted on the one-time code kept under `field` - the
        one whose hash is `code` - as the database holds it now (1.0.101);
        taken away at the last try. Whether it is gone now."""
        for _round in range(16):
            raw = self.db.value('SELECT data FROM sessions WHERE id = ?', (ident,))
            if raw is None:
                return True
            try:
                data = json.loads(raw or '{}')
            except ValueError:
                return True
            cur = data.get(field)
            if not isinstance(cur, dict) or cur.get('code') != code:
                return True             # taken, or another code asked for since
            cur['tries'] = int(cur.get('tries') or 0) + 1
            gone = cur['tries'] >= most
            if gone:
                data.pop(field, None)
            else:
                data[field] = cur
            if self.db.run('UPDATE sessions SET data = ? WHERE id = ? AND data = ?',
                           (json.dumps(data), ident, raw)):
                return gone
        return False

    def session_set_data(self, ident, data):
        self.db.run('UPDATE sessions SET data = ? WHERE id = ?', (json.dumps(data), ident))

    def session_end(self, token):
        self.db.run('DELETE FROM sessions WHERE token_hash = ?',
                    (hashlib.sha256(str(token or '').encode()).hexdigest(),))

    def sessions(self, kind=None):
        sql, args = 'SELECT id, kind, name, role, created, last, expires, ip FROM sessions', []
        if kind:
            sql += ' WHERE kind = ?'
            args.append(kind)
        return self.db.rows(sql + ' ORDER BY last DESC', args)

    def session_drop(self, ident):
        self.db.run('DELETE FROM sessions WHERE id = ?', (int(ident),))

    def sessions_tidy(self, idle_admin_s=None, idle_portal_s=None):
        """Sign-ins that have run out go; so do the ones that sat untouched
        longer than they may (1.0.15: they stayed on the list of who is
        signed in, though a request from them would have been refused)."""
        t = time.time()
        self.db.run('DELETE FROM sessions WHERE expires < ?', (t,))
        for kind, idle in (('admin', idle_admin_s), ('portal', idle_portal_s)):
            if idle:
                self.db.run('DELETE FROM sessions WHERE kind = ? AND last < ?', (kind, t - float(idle)))

    # ---- RADIUS clients ----------------------------------------------------
    def _client_rows(self):
        """The clients as read, secrets opened - one list, never None, even
        when a save empties the cache between two lines (1.0.33)."""
        rows = self._clients
        if rows is None:
            rows = self.db.rows('SELECT * FROM clients ORDER BY position, name')
            for r in rows:
                r['_secret'] = unseal_secret(r.get('secret') or '')
                try:
                    r['_net'] = address_net(r['address'])
                except ValueError:
                    r['_net'] = None
            self._clients = rows
        return rows

    def clients_seen(self):
        """When each client was last heard from, by any node (1.0.98)."""
        seen = {}
        try:
            for r in self.db.rows("SELECT k, v FROM meta WHERE k LIKE 'clientseen:%'"):
                try:
                    ident = int(r['k'].rsplit(':', 1)[1])
                    seen[ident] = max(seen.get(ident, 0), float(r['v']))
                except (ValueError, IndexError):
                    continue
        except Exception:                               # noqa: BLE001
            pass
        return seen

    def clients(self, with_secret=False, last=True):
        out = []
        seen = self.clients_seen()
        for r in self._client_rows():
            one = {k: v for k, v in r.items() if not k.startswith('_') and k != 'secret'}
            if seen.get(r.get('id')):
                one['last_seen'] = max(float(one.get('last_seen') or 0), seen[r['id']])
            one['secret_set'] = bool(r['_secret'])
            one['secret_lost'] = r['_secret'] is None
            one['secret'] = r['_secret'] if with_secret else secret_shown(r['_secret'], last)
            out.append(one)
        return out

    def client_name_of(self, tok):
        """The RADIUS client a token was last let in through (1.0.58)."""
        # Only what was kept (1.0.61): the address beside it is the person's
        # (Calling-Station-Id), not the NAS's, and looked up as a client's it
        # named a wrong one.
        return str(tok.get('last_client') or '')

    def client_for(self, ip):
        """The client a packet from this address belongs to: the narrowest
        range holding it, and of two the same width the one named first."""
        rows = self._client_rows()
        try:
            addr = ipaddress.ip_address(ip)
        except ValueError:
            return None
        best = None
        for r in rows:
            net = r['_net']
            if not net or not r.get('enabled') or addr.version != net.version or addr not in net:
                continue
            if best is None or net.prefixlen > best['_net'].prefixlen:
                best = r
        return best

    def client_save(self, data, by=''):
        """A client made or changed. Returns its id."""
        name = str(data.get('name') or '').strip()
        if not re.match(r'^[A-Za-z0-9][A-Za-z0-9._ -]{0,63}\Z', name):
            raise ValueError('a client needs a name: letters, digits, dots, dashes and spaces')
        try:
            net = address_net(data.get('address'))
        except ValueError:
            raise ValueError('%r is not an address or a range of them'
                             % str(data.get('address') or '')[:60])
        secret = data.get('secret')
        # Each field of its own kind (1.0.103): a secret sent as a list was
        # kept as the text "['a']".
        for k in ('secret', 'note', 'realm', 'nas_type', 'address', 'name'):
            if data.get(k) is not None and not isinstance(data.get(k), str):
                raise ValueError('%s is a piece of text' % k)
        ident = data.get('id')
        try:
            old = self.db.row('SELECT * FROM clients WHERE id = ?', (int(ident),)) if ident else None
        except (TypeError, ValueError):
            raise ValueError('the id of a client is a number')
        clash = self.db.row('SELECT id FROM clients WHERE LOWER(name) = ?', (name.lower(),))
        if clash and (not old or clash['id'] != old['id']):
            raise ValueError('there is a client called %s already' % name)
        row = {'name': name, 'address': str(net) if net.num_addresses > 1 else
               str(net.network_address),
               'realm': str(data.get('realm') or '').strip().lstrip('@')[:190],
               'require_ma': int(bool(int(data.get('require_ma') or 0))),
               'enabled': int(bool(int(data.get('enabled', 1) if data.get('enabled')
                                       is not None else 1))),
               'note': str(data.get('note') or '')[:400],
               'nas_type': str(data.get('nas_type') or '')[:60],
               'position': list_position(data.get('position'))}
        # The realms it may use (1.0.33): none named, any.
        if 'realms' in data or not old:
            raw = data.get('realms') or ''
            # Split on commas only (1.0.36): a realm's name may have spaces.
            want = [str(x).strip() for x in (raw if isinstance(raw, (list, tuple))
                                             else re.split(r'[,;\n]+', str(raw)))
                    if str(x).strip()]
            known = {r['name'].lower(): r['name'] for r in self.realms()}
            bad = [x for x in want if x.lower() not in known]
            if bad:
                raise ValueError('there is no realm called %s' % ', '.join(bad))
            row['realms'] = ', '.join(known[x.lower()] for x in want)
        if secret is not None and not is_masked(secret):
            secret = str(secret)
            if not secret.strip():
                raise ValueError('a client needs a shared secret')
            if len(secret) > 128:
                raise ValueError('a shared secret of more than 128 characters is more than '
                                 'RADIUS hides properly')
            row['secret'] = seal_secret(secret)
        elif not old:
            raise ValueError('a client needs a shared secret')
        with self.lock:
            if old:
                self.db.update('clients', old['id'], row)
                ident = old['id']
            else:
                row['created'] = time.time()
                ident = self.db.insert('clients', row)
            self._clients = None
        return ident

    def client_drop(self, ident):
        self.db.run('DELETE FROM clients WHERE id = ?', (int(ident),))
        try:
            for r in self.db.rows("SELECT k FROM meta WHERE k LIKE 'clientseen:%'"):
                if r['k'].rsplit(':', 1)[-1] == str(int(ident)):
                    self.db.run('DELETE FROM meta WHERE k = ?', (r['k'],))
            # Which of its addresses signed their requests, on every node
            # (1.0.101): maseen:<node>:<client>:<address>.
            for r in self.db.rows("SELECT k FROM meta WHERE k LIKE 'maseen:%'"):
                parts = r['k'].split(':', 3)
                if len(parts) == 4 and parts[2] == str(int(ident)):
                    self.db.run('DELETE FROM meta WHERE k = ?', (r['k'],))
        except Exception:                               # noqa: BLE001
            pass
        self._clients = None

    _SEEN_AT = {}

    def client_seen(self, ident):
        """When a client was last heard from - written at most once a minute
        a client (1.0.33), not on every packet."""
        t = time.time()
        if t - self._SEEN_AT.get(ident, 0) < 60:
            return
        self._SEEN_AT[ident] = t
        # Not into the client's own row (1.0.98): logical replication sends a
        # row whole, and this write once a minute on one node could put back
        # a shared secret changed on the other at that moment. A key of this
        # node's own, which nobody else writes.
        self.set_meta('clientseen:%s:%s' % (node_name(), ident), repr(t))

    # ---- realms --------------------------------------------------------------
    def realms(self):
        if self._realms is None:
            rows = self.db.rows('SELECT * FROM realms ORDER BY position, name')
            for r in rows:
                try:
                    r['groups'] = json.loads(r.get('group_list') or '[]')
                except ValueError:
                    r['groups'] = []
                r.pop('group_list', None)
                r['methods'] = realm_methods(r)          # a list (1.0.76)
                # A column added later is NULL in the rows from before it
                # (1.0.94): get('nested', 1) gave None - nested groups off
                # for every realm older than the switch.
                for k, dflt in (('nested', 1), ('check_disabled', 1)):
                    if r.get(k) is None:
                        r[k] = dflt
            self._realms = rows
        return [dict(r) for r in self._realms]

    def realm_for(self, user):
        """The realm a name belongs to: by what follows its @, else the realm
        for names with none, else the one that takes everything (`*`)."""
        suffix = user.rsplit('@', 1)[1].lower() if '@' in user else ''
        realms = [r for r in self.realms() if r.get('enabled')]
        for r in realms:
            if str(r.get('suffix') or '').lower() == suffix and r.get('suffix') != '*':
                return r
        for r in realms:
            if r.get('suffix') == '*':
                return r
        return None

    def realm_save(self, data, by=''):
        if data.get('groups') is not None and not isinstance(data.get('groups'), list):
            # "abc" was read letter by letter: groups a, b and c (1.0.103).
            raise ValueError('groups is a list')
        for k in ('name', 'suffix', 'directory', 'note', 'reply', 'lookup', 'auth_mode'):
            if data.get(k) is not None and not isinstance(data.get(k), str):
                raise ValueError('%s is a piece of text' % k)
        name = str(data.get('name') or '').strip()
        if not re.match(r'^[A-Za-z0-9][A-Za-z0-9._ -]{0,63}\Z', name):
            raise ValueError('a realm needs a name: letters, digits, dots, dashes and spaces')
        suffix = str(data.get('suffix') or '').strip().lstrip('@').lower()
        if suffix and suffix != '*' and not re.match(r'^[a-z0-9][a-z0-9.-]*\Z', suffix):
            raise ValueError('the realm is what comes after the @ - example.cz - or * for '
                             'every name, or nothing for names written without one')
        lookup = str(data.get('lookup') or 'upn')
        if lookup not in ('upn', 'sam', 'none'):
            raise ValueError('lookup is upn, sam or none')
        mode = str(data.get('auth_mode') or 'otp')
        if mode not in ('otp', 'password_otp', 'password', 'challenge'):
            raise ValueError('auth_mode is otp, password_otp, password or challenge')
        # The kinds of token people may choose here (1.0.76): the app, a code
        # by mail, a code by SMS. A code is only ever sent after the
        # directory password, so mail and SMS need a directory.
        raw = data.get('methods')
        if raw is None and old_methods_of(self, data.get('id')) is not None:
            raw = old_methods_of(self, data.get('id'))
        methods = realm_methods({'methods': raw})
        token_name = str(data.get('token_name') or 'whole')
        if token_name not in ('whole', 'bare'):
            raise ValueError('token_name is whole or bare')
        directory = str(data.get('directory') or '').strip()
        if directory and not self.directory(directory):
            raise ValueError('there is no directory called %s' % directory)
        if token_name == 'bare':
            # Names without their realm are one person's only within one
            # directory (1.0.101): novak@a in one and novak@b in another
            # shared the token "novak", and the second could enrol it, or
            # sign in to the first realm with it.
            for r in self.realms():
                if r.get('token_name') == 'bare' and str(r.get('name')).lower() != \
                        str(data.get('name') or '').strip().lower() and \
                        str(r.get('directory') or '').lower() != directory.lower():
                    raise ValueError('the realm %s already keeps its tokens under the name '
                                     'alone, with the directory %s: names alone are one '
                                     'person\'s only within one directory - keep this '
                                     'realm\'s under the whole name'
                                     % (r['name'], r.get('directory') or '(none)'))
        if lookup != 'none' and not directory:
            lookup = 'none'
        if mode in ('password', 'password_otp', 'challenge') and lookup == 'none':
            raise ValueError('a password can only be checked against a directory: choose one, '
                             'and how names are looked up in it')
        if any(m in methods for m in ('mail', 'sms')) and lookup == 'none':
            raise ValueError('a code by mail or SMS is sent only after the directory password '
                             'is right: the realm needs a directory')
        groups = []
        for one in data.get('groups') or []:
            if isinstance(one, str):
                one = {'group': one, 'reply': ''}
            g = str(one.get('group') or '').strip()
            if not g:
                continue
            try:
                reply_lines(one.get('reply') or '')
            except RadiusError as e:
                raise ValueError('the answer for the group %s: %s' % (g, e))
            groups.append({'group': g, 'reply': str(one.get('reply') or '').strip()})
        try:
            reply_lines(data.get('reply') or '')
        except RadiusError as e:
            raise ValueError('the answer for everybody in the realm: %s' % e)
        ident = data.get('id')
        old = self.db.row('SELECT * FROM realms WHERE id = ?', (int(ident),)) if ident else None
        for other in self.realms():
            if old and other['id'] == old['id']:
                continue
            if other['name'].lower() == name.lower():
                raise ValueError('there is a realm called %s already' % name)
            if str(other.get('suffix') or '').lower() == suffix:
                raise ValueError('the realm %s takes %s already' % (
                    other['name'], ('@' + suffix) if suffix not in ('', '*') else
                    ('every name' if suffix == '*' else 'names written without a realm')))
        row = {'name': name, 'suffix': suffix, 'directory': directory, 'lookup': lookup,
               'auth_mode': mode, 'group_list': json.dumps(groups),
               'check_disabled': int(bool(int(data.get('check_disabled', 1)))),
               'nested': int(bool(int(data.get('nested', 1)))),
               'reply': str(data.get('reply') or '').strip(),
               'enabled': int(bool(int(data.get('enabled', 1)))),
               'position': list_position(data.get('position')),
               'note': str(data.get('note') or '')[:400], 'token_name': token_name,
               'methods': ','.join(methods)}
        with self.lock:
            if old:
                self.db.update('realms', old['id'], row)
                ident = old['id']
                if old.get('name') and row.get('name') and old['name'] != row['name']:
                    # The clients that may use it, told its new name (1.0.36).
                    self._client_realms_rename(old['name'], row['name'])
            else:
                row['created'] = time.time()
                ident = self.db.insert('realms', row)
            self._realms = None
        return ident

    def realm_drop(self, ident):
        one = self.db.row('SELECT name FROM realms WHERE id = ?', (int(ident),))
        self.db.run('DELETE FROM realms WHERE id = ?', (int(ident),))
        self._realms = None
        if one:
            # ...and out of the clients' lists: a name left there made every
            # later save of the client fail (1.0.36).
            self._client_realms_rename(one['name'], None)

    def _client_realms_rename(self, was, now):
        for c in self.db.rows("SELECT id, realms FROM clients WHERE COALESCE(realms, '') <> ''"):
            names = [x.strip() for x in re.split(r'[,;\n]+', c['realms'] or '') if x.strip()]
            if not any(x.lower() == str(was).lower() for x in names):
                continue
            names = [(now if x.lower() == str(was).lower() else x) for x in names]
            names = [x for x in names if x]
            self.db.update('clients', c['id'], {'realms': ', '.join(names)})
        self._clients = None

    # ---- directories -------------------------------------------------------
    def directories(self, with_secret=False, last=True):
        if self._dirs is None:
            rows = self.db.rows('SELECT * FROM directories ORDER BY name')
            for r in rows:
                r['_pw'] = unseal_secret(r.get('bind_pw') or '')
            self._dirs = rows
        out = []
        for r in self._dirs:
            one = {k: v for k, v in r.items() if not k.startswith('_') and k != 'bind_pw'}
            one['bind_pw_set'] = bool(r['_pw'])
            one['bind_pw_lost'] = r['_pw'] is None
            one['bind_pw'] = r['_pw'] if with_secret else secret_shown(r['_pw'], last)
            one['ca_says'] = describe_certificate(r.get('ca') or '') if r.get('ca') else None
            one['ca_list'] = describe_certificates(r.get('ca') or '') if r.get('ca') else []
            out.append(one)
        return out

    def directory(self, name, with_secret=False):
        for one in self.directories(with_secret):
            if one['name'].lower() == str(name or '').strip().lower():
                return one
        return None

    def directory_set_ca(self, ident, pem, mode='set', fingerprint=''):
        """The certificate authorities of one directory, and nothing else of
        it: several chains may be kept - one per domain the directory's
        controllers come from - each added and taken out by itself."""
        pem = str(pem or '').strip()
        row = self.db.row('SELECT ca FROM directories WHERE id = ?', (int(ident),))
        have = split_certificates((row or {}).get('ca') or '')
        if mode in ('add', 'set') and pem:
            new = split_certificates(pem)
            if not new or not all(describe_certificate(b) for b in new):
                raise ValueError('that is not a certificate this can read: a PEM certificate '
                                 'starts -----BEGIN CERTIFICATE-----')
            if mode == 'add':
                seen = {c['fingerprint'] for c in describe_certificates('\n'.join(have))}
                have += [b for b, c in zip(new, describe_certificates('\n'.join(new)))
                         if c['fingerprint'] not in seen]
            else:
                have = new
        elif mode == 'drop':
            keep = [b for b, c in zip(have, describe_certificates('\n'.join(have)))
                    if c['fingerprint'] != fingerprint]
            if len(keep) == len(have):
                raise ValueError('that certificate is not among the ones kept')
            have = keep
        else:
            have = []
        pem = '\n'.join(have)
        with self.lock:
            self.db.run('UPDATE directories SET ca = ? WHERE id = ?', (pem, int(ident)))
            self._dirs = None

    def directory_save(self, data, by=''):
        for k in ('name', 'hosts', 'base', 'bind_dn', 'bind_pw', 'note', 'ca', 'user_attr', 'tls'):
            if data.get(k) is not None and not isinstance(data.get(k), str):
                raise ValueError('%s is a piece of text' % k)
        name = str(data.get('name') or '').strip()
        if not re.match(r'^[A-Za-z0-9][A-Za-z0-9._ -]{0,63}\Z', name):
            raise ValueError('a directory needs a name: letters, digits, dots, dashes and spaces')
        hosts = [h.strip() for h in re.split(r'[,;\s]+', str(data.get('hosts') or ''))
                 if h.strip()]
        clean = []
        for h in hosts:
            h = re.sub(r'^ldaps?://', '', h, flags=re.I).rstrip('/')
            if not re.match(r'^[A-Za-z0-9.\-:\[\]]+\Z', h):
                raise ValueError('%r is not a server name or address' % h)
            clean.append(h)
        if not clean:
            raise ValueError('a directory needs at least one server')
        tls = str(data.get('tls') or 'ldaps')
        if tls not in ('none', 'ldaps', 'starttls'):
            raise ValueError('tls is none, ldaps or starttls')
        try:
            port = int(data.get('port') or (636 if tls == 'ldaps' else 389))
        except (TypeError, ValueError):
            raise ValueError('the port is a number')
        if not 1 <= port <= 65535:
            raise ValueError('the port is 1 to 65535')
        base = str(data.get('base') or '').strip()
        if not re.match(r'(?i)^(dc|ou|o|cn)=', base):
            raise ValueError('the base is a distinguished name: DC=example,DC=local')
        ca = str(data.get('ca') or '').strip()
        if ca and '-----BEGIN CERTIFICATE-----' not in ca:
            raise ValueError('the certificate authority is a PEM certificate, starting '
                             '-----BEGIN CERTIFICATE-----')
        ident = data.get('id')
        old = self.db.row('SELECT * FROM directories WHERE id = ?',
                          (int(ident),)) if ident else None
        clash = self.db.row('SELECT id FROM directories WHERE LOWER(name) = ?', (name.lower(),))
        if clash and (not old or clash['id'] != old['id']):
            raise ValueError('there is a directory called %s already' % name)
        row = {'name': name, 'hosts': ', '.join(clean), 'port': port, 'tls': tls,
               'verify': int(bool(int(data.get('verify', 1)))), 'base': base,
               'weak': int(bool(int(data.get('weak') or 0))),
               'bind_dn': str(data.get('bind_dn') or '').strip(),
               'user_attr': str(data.get('user_attr') or 'sAMAccountName').strip(),
               'nested': int(bool(int(data.get('nested', 1)))),
               'timeout_s': max(2, min(60, int(data.get('timeout_s') or 10))),
               'enabled': int(bool(int(data.get('enabled', 1)))),
               'note': str(data.get('note') or '')[:400]}
        if 'ca' in data:
            row['ca'] = ca
        pw = data.get('bind_pw')
        if pw is not None and not is_masked(pw):
            row['bind_pw'] = seal_secret(pw) if str(pw) else ''
        with self.lock:
            if old:
                if old['name'] != name:
                    self.db.run('UPDATE realms SET directory = ? WHERE directory = ?',
                                (name, old['name']))
                    self._realms = None
                self.db.update('directories', old['id'], row)
                ident = old['id']
            else:
                row['created'] = time.time()
                ident = self.db.insert('directories', row)
            self._dirs = None
        return ident

    def directory_drop(self, ident):
        one = self.db.row('SELECT name FROM directories WHERE id = ?', (int(ident),))
        if one:
            used = [r['name'] for r in self.realms()
                    if str(r.get('directory') or '').lower() == one['name'].lower()]
            if used:
                raise ValueError('the realm(s) %s look people up in it; change them first'
                                 % ', '.join(used))
        self.db.run('DELETE FROM directories WHERE id = ?', (int(ident),))
        self._dirs = None

    # ---- tokens --------------------------------------------------------------
    TOKEN_SORTS = {'name': 'name', 'created': 'created', 'last_used': 'last_used',
                   'state': 'state', 'failures': 'failures', 'scratch_left': 'scratch_left'}

    def token(self, name):
        return self.db.row('SELECT * FROM tokens WHERE name = ?', (norm_name(name),))

    def tokens(self, q='', state='', limit=100, offset=0, sort='name', desc=False, extra=None,
               kind=''):
        where, args = [], []
        if kind in ('totp', 'mail', 'sms'):
            # How the codes come (1.0.85): an app token has no kind written.
            where.append("(CASE WHEN kind IN ('mail', 'sms') THEN kind ELSE 'totp' END) = ?")
            args.append(kind)
        if extra and extra[0]:
            where.append(extra[0])
            args += list(extra[1])
        if q:
            where.append("(LOWER(name) LIKE ? ESCAPE '!' OR LOWER(note) LIKE ? ESCAPE '!' OR LOWER(display) LIKE ? ESCAPE '!' OR LOWER(COALESCE(dest, '')) LIKE ? ESCAPE '!')")
            like = '%' + like_pattern(str(q).lower()) + '%'
            args += [like, like, like, like]
            digits = phone_digits(q)
            if digits:
                # 603 364 754 finds +420603364754 (1.0.93).
                where[-1] = where[-1][:-1] + " OR %s LIKE ? ESCAPE '!')" % DEST_DIGITS_SQL
                args.append('%' + like_pattern(digits) + '%')
        if state:
            where.append('state = ?')
            args.append(state)
        sql = ' WHERE ' + ' AND '.join(where) if where else ''
        total = self.db.value('SELECT COUNT(*) AS n FROM tokens' + sql, args, 0)
        col = self.TOKEN_SORTS.get(sort, 'name')
        rows = self.db.rows('SELECT * FROM tokens%s ORDER BY %s %s, name LIMIT %d OFFSET %d'
                            % (sql, col, 'DESC' if desc else 'ASC', int(limit), int(offset)),
                            args)
        return [self.token_shown(r) for r in rows], int(total or 0)

    @staticmethod
    def token_shown(r):
        """A token as the pages may see it: never its key, never its codes."""
        if not r:
            return None
        out = {k: r.get(k) for k in ('id', 'name', 'digits', 'period', 'algorithm',
                                     'window_steps', 'state', 'scratch_left', 'created',
                                     'created_by', 'activated', 'last_used', 'last_from',
                                     'last_how', 'failures', 'note', 'issuer', 'label',
                                     'pending_at', 'pending_by', 'display', 'last_client')}
        out['kind'] = token_kind(r)
        out['dest'] = r.get('dest') or ''
        out['lang'] = r.get('lang') or ''               # 1.0.82
        out['mail_fmt'] = r.get('mail_fmt') or ''
        out['key_lost'] = unseal_secret(r.get('secret') or '', token_bind(r.get('name'))) is None
        out['pending'] = bool(r.get('pending_secret'))
        out['scratch_kept'] = bool(r.get('scratch_sealed'))
        # Until when wrong codes keep it shut (1.0.101): a lock that grows
        # with each round is shown, not guessed at from the count.
        lu = float(r.get('locked_until') or 0)
        out['locked_until'] = lu if lu > time.time() else None
        return out

    def token_counts(self):
        out = {'all': 0, 'active': 0, 'pending': 0, 'disabled': 0}
        for r in self.db.rows('SELECT state, COUNT(*) AS n FROM tokens GROUP BY state'):
            out[r['state'] or 'active'] = int(r['n'])
            out['all'] += int(r['n'])
        out['used_30d'] = int(self.db.value('SELECT COUNT(*) AS n FROM tokens WHERE '
                                            'last_used > ?', (time.time() - 30 * 86400,), 0))
        out['never_used'] = int(self.db.value('SELECT COUNT(*) AS n FROM tokens WHERE '
                                              'last_used IS NULL', (), 0))
        for r in self.db.rows("SELECT CASE WHEN kind IN ('mail', 'sms') THEN kind ELSE 'totp' END "
                              "AS k, COUNT(*) AS n FROM tokens GROUP BY 1"):
            out['kind_' + r['k']] = int(r['n'])        # 1.0.85
        return out

    def token_write(self, name, fields):
        """A token made, or the fields given changed on the one there is."""
        name = norm_name(name)
        with self.lock:
            old = self.token(name)
            if old:
                self.db.update('tokens', old['id'], fields)
                return old['id']
            row = {'name': name, 'state': 'active', 'last_step': 0, 'failures': 0,
                   'fail_times': '[]', 'scratch': '[]', 'scratch_left': 0,
                   'created': time.time(), 'window_steps': -1}
            row.update(fields)
            return self.db.insert('tokens', row)

    def token_update(self, ident, fields):
        """Fields changed on the token that was read, by its id, and never a
        token made: a check whose token was deleted meanwhile wrote a new,
        empty one back under the name (1.0.36)."""
        return self.db.update('tokens', ident, fields)

    def token_drop(self, name):
        return self.db.run('DELETE FROM tokens WHERE name = ?', (norm_name(name),))

    # ---- the logs ------------------------------------------------------------
    def radius_add(self, row):
        if HA_REBUILDING.is_set():
            return None
        row.setdefault('node', log_node())
        return self.db.insert('radius_log', row)

    def radius_rows(self, hours=24, q='', result='', client='', limit=100, offset=0,
                    since=None, sort='ts', desc=True, user='', where_only=False, extra=None):
        where, args = ['ts >= ?'], [since if since is not None else
                                    time.time() - float(hours) * 3600]
        if extra and extra[0]:
            where.append(extra[0])
            args += list(extra[1])
        if q:
            like = '%' + like_pattern(str(q).lower()) + '%'
            where.append("(LOWER(username) LIKE ? ESCAPE '!' OR LOWER(calling) LIKE ? ESCAPE '!' OR LOWER(reason) "
                         "LIKE ? ESCAPE '!' OR LOWER(client) LIKE ? ESCAPE '!' OR LOWER(device) LIKE ? ESCAPE '!' OR "
                         "LOWER(otp) LIKE ? ESCAPE '!')")
            args += [like] * 6
        if result:
            if result == 'access':
                where.append("packet = 'Access-Request'")
            else:
                where.append('result = ?')
                args.append(result)
        if client:
            where.append('client = ?')
            args.append(client)
        if user:
            where.append('username = ?')
            args.append(user)
        sql = ' WHERE ' + ' AND '.join(where)
        if where_only:
            return sql, args
        total = self.db.value('SELECT COUNT(*) AS n FROM radius_log' + sql, args, 0)
        col = {'ts': 'ts', 'username': 'username', 'result': 'result', 'client': 'client',
               'calling': 'calling', 'took_ms': 'took_ms', 'reason': 'reason',
               'node': 'node'}.get(sort, 'ts')
        rows = self.db.rows('SELECT id, ts, client, nas_ip, src, packet, username, realm, '
                            'calling, called, result, reason, otp, rid, took_ms, device, tunnel, '
                            'node '
                            'FROM radius_log%s ORDER BY %s %s, id DESC LIMIT %d OFFSET %d'
                            % (sql, col, 'DESC' if desc else 'ASC', int(limit), int(offset)),
                            args)
        return rows, int(total or 0)

    def radius_row(self, ident):
        r = self.db.row('SELECT * FROM radius_log WHERE id = ?', (int(ident),))
        if r:
            for k in ('attrs', 'reply', 'steps'):
                try:
                    r[k] = json.loads(r.get(k) or '[]')
                except ValueError:
                    r[k] = []
        return r

    def otp_add(self, row):
        row.setdefault('node', log_node())
        return self.db.insert('otp_log', row)

    def log_forget(self, table, ids=None, where_sql='', args=()):
        """Lines of a log taken away - by id, or every line a filter matches."""
        if table not in ('radius_log', 'otp_log', 'events'):
            raise ValueError('not a log')
        if ids is not None:
            ids = [int(i) for i in ids][:5000]
            if not ids:
                return 0
            return self.db.run('DELETE FROM %s WHERE id IN (%s)'
                               % (table, ', '.join('?' for _ in ids)), ids)
        return self.db.run('DELETE FROM %s%s' % (table, where_sql), list(args))

    def otp_where(self, hours=24, q='', ok=None, name='', not_how='', extra=None):
        where, args = ['ts >= ?'], [time.time() - float(hours) * 3600]
        if extra and extra[0]:
            where.append(extra[0])
            args += list(extra[1])
        if not_how:
            where.append('(how IS NULL OR how <> ?)')
            args.append(not_how)
        if q:
            like = '%' + like_pattern(str(q).lower()) + '%'
            where.append("(LOWER(name) LIKE ? ESCAPE '!' OR LOWER(said) LIKE ? ESCAPE '!' OR LOWER(src) LIKE ? ESCAPE '!')")
            args += [like] * 3
        if ok is not None:
            where.append('ok = ?')
            args.append(1 if ok else 0)
        if name:
            where.append('name = ?')
            args.append(name)
        return ' WHERE ' + ' AND '.join(where), args

    def otp_rows(self, hours=24, q='', ok=None, limit=100, offset=0, name='', not_how='',
                 extra=None):
        if not_how or extra:
            sql, args = self.otp_where(hours, q, ok, name, not_how, extra)
            total = self.db.value('SELECT COUNT(*) AS n FROM otp_log' + sql, args, 0)
            rows = self.db.rows('SELECT * FROM otp_log%s ORDER BY ts DESC, id DESC LIMIT %d '
                                'OFFSET %d' % (sql, int(limit), int(offset)), args)
            return rows, int(total or 0)
        where, args = ['ts >= ?'], [time.time() - float(hours) * 3600]
        if q:
            like = '%' + like_pattern(str(q).lower()) + '%'
            where.append("(LOWER(name) LIKE ? ESCAPE '!' OR LOWER(said) LIKE ? ESCAPE '!' OR LOWER(src) LIKE ? ESCAPE '!')")
            args += [like] * 3
        if ok is not None:
            where.append('ok = ?')
            args.append(1 if ok else 0)
        if name:
            where.append('name = ?')
            args.append(name)
        sql = ' WHERE ' + ' AND '.join(where)
        total = self.db.value('SELECT COUNT(*) AS n FROM otp_log' + sql, args, 0)
        rows = self.db.rows('SELECT * FROM otp_log%s ORDER BY ts DESC, id DESC LIMIT %d OFFSET %d'
                            % (sql, int(limit), int(offset)), args)
        return rows, int(total or 0)

    _OVERVIEW = {}

    def overview(self, hours=24, since=None, until=None):
        """overview_now, kept 20 s per window (1.0.57): every open tab asked
        for it again whenever a request came in."""
        key = (int(hours), int(float(since) // 60) if since else None,
               int(float(until) // 60) if until else None)
        got = Storage._OVERVIEW.get(key)
        if got and time.time() - got[0] < 20:
            return got[1]
        out = self.overview_now(hours, since, until)
        if len(Storage._OVERVIEW) > 50:
            Storage._OVERVIEW.clear()
        Storage._OVERVIEW[key] = (time.time(), out)
        return out

    def overview_now(self, hours=24, since=None, until=None):
        """What the front page counts: per hour, what was let in and what was
        refused, and the names, reasons and clients behind the refusals.
        `since`/`until` (1.0.53): a window of its own, from the time picker."""
        now = time.time()
        until = float(until) if until else now
        since = float(since) if since else until - float(hours) * 3600
        hours = max(1.0, (until - since) / 3600)
        step = 3600 if hours <= 72 else (6 * 3600 if hours <= 24 * 31 else 86400)
        # Bars on the local clock (1.0.57): a day ran from 01:00 or 02:00
        # in Prague, aligned to UTC.
        off = time.localtime(since).tm_gmtoff or 0
        start = int((since + off) // step) * step - off
        # Counted by the database, hour by hour (1.0.33): every request of
        # the window was read into Python - over a second for a month.
        slot = ('CAST((ts - ?) / ? AS INTEGER)' if self.db.engine == 'sqlite'
                else 'FLOOR((ts - ?) / ?)')
        # Counted by the hour, and the hours put into bars of the local clock
        # (1.0.59): a day bar is local midnight to midnight across a change
        # of summer time too, where a fixed 24 h step drifted by an hour.
        rows = self.db.rows("SELECT %s AS b, result, COUNT(*) AS n FROM radius_log "
                            "WHERE ts >= ? AND ts < ? AND packet = 'Access-Request' "
                            "AND result IN ('accept', 'reject', 'drop') GROUP BY 1, 2"
                            % slot, (start, 3600, since, until))

        def bar_of(ts):
            if step == 3600:
                return int(ts)
            lt = time.localtime(ts)
            hour = 0 if step == 86400 else (lt.tm_hour // 6) * 6
            return int(time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday, hour, 0, 0, 0, 0, -1)))
        buckets = collections.OrderedDict()
        t = start
        while t < min(until, now):
            b = bar_of(t)
            if b not in buckets:
                buckets[b] = {'t': b, 'accept': 0, 'reject': 0}
            t += 3600
        acc = rej = 0
        for r in rows:
            b = bar_of(start + int(r['b'] or 0) * 3600)
            if b not in buckets:
                buckets[b] = {'t': b, 'accept': 0, 'reject': 0}
            n = int(r['n'] or 0)
            if r['result'] == 'accept':
                buckets[b]['accept'] += n
                acc += n
            else:
                buckets[b]['reject'] += n
                rej += n

        def top(col, where, n=10):
            return self.db.rows(
                "SELECT %s AS said, COUNT(*) AS n, MAX(ts) AS last FROM radius_log WHERE ts >= ? "
                "AND ts < ? AND packet = 'Access-Request' AND %s GROUP BY %s ORDER BY n DESC "
                "LIMIT %d" % (col, where, col, n), (since, until))
        return {
            'hours': hours, 'step': step, 'since': since, 'until': until, 'series': list(buckets.values()),
            'accepted': acc, 'refused': rej,
            'people': int(self.db.value(
                "SELECT COUNT(DISTINCT username) AS n FROM radius_log WHERE ts >= ? AND "
                "ts < ? AND result = 'accept'", (since, until), 0) or 0),
            'top_refused_names': top('username', "result = 'reject'"),
            'top_reasons': top('reason', "result = 'reject'"),
            'top_clients': top('client', '1 = 1'),
            'top_places': top('calling', "calling <> ''"),
            'otp_bad': int(self.db.value('SELECT COUNT(*) AS n FROM otp_log WHERE ts >= ? AND '
                                         'ts < ? AND ok = 0', (since, until), 0) or 0),
            'otp_good': int(self.db.value('SELECT COUNT(*) AS n FROM otp_log WHERE ts >= ? AND '
                                          'ts < ? AND ok = 1', (since, until), 0) or 0),
        }

    def tidy(self):
        """What has been kept long enough, deleted."""
        said = {}
        for table, key in (('radius_log', 'retain_radius_days'), ('otp_log', 'retain_otp_days'),
                           ('events', 'retain_events_days')):
            days = int(CONFIG.get(key) or 0)
            if days > 0:
                said[table] = self.delete_older(table, time.time() - days * 86400)
        self.sessions_tidy(int(CONFIG.get('session_idle_min') or 120) * 60,
                           int(CONFIG.get('portal_session_min') or 15) * 60)
        return said

    def delete_older(self, table, cut):
        """Rows older than `cut`, deleted in batches (1.0.33), with a breath
        between them (1.0.57) so RADIUS requests waiting on the database get
        their turn."""
        gone = 0
        for _ in range(100000):
            if self.db.engine == 'mariadb':
                n = self.db.run('DELETE FROM %s WHERE ts < ? LIMIT 5000' % table, (cut,))
            else:
                n = self.db.run('DELETE FROM %s WHERE id IN (SELECT id FROM %s WHERE '
                                'ts < ? LIMIT 5000)' % (table, table), (cut,))
            gone += int(n or 0)
            if not n or n < 5000:
                break
            time.sleep(0.02)
        return gone

    def counts(self):
        return {t: int(self.db.value('SELECT COUNT(*) AS n FROM %s' % t, (), 0) or 0)
                for t in TABLES if t not in ('meta',)}


# ---------------------------------------------------------------------------
# A directory, as the realms and the sign-ins use it
# ---------------------------------------------------------------------------
# Several servers, asked in the order given: one that cannot be reached is
# passed over for the next, one that answers is believed. Two questions are
# asked of it all day - who is this, and which groups are they in - and
# their answers are kept for a minute, because a VPN asks twice in a row for
# the same person more often than not.

AD_UAC_DISABLED = 0x2
AD_NEVER = (0, 0x7FFFFFFFFFFFFFFF)
USER_ATTRS = ('distinguishedName', 'sAMAccountName', 'userPrincipalName', 'displayName',
              'mail', 'userAccountControl', 'accountExpires', 'memberOf', 'lockoutTime',
              'pwdLastSet', 'department', 'title', 'mobile', 'telephoneNumber',
              'objectClass', 'msDS-User-Account-Control-Computed')
# msDS-User-Account-Control-Computed (1.0.101): what AD works out now -
# locked out (0x10) and the password expired (0x800000). lockoutTime alone
# stays set after the lockout is over.
AD_UACC_LOCKED = 0x10
AD_UACC_PW_EXPIRED = 0x800000


def ad_time(value):
    """A Windows time (hundreds of nanoseconds since 1601) as seconds since
    1970, or None for never."""
    try:
        n = int(value)
    except (TypeError, ValueError):
        return None
    if n in AD_NEVER or n <= 0:
        return None
    return n / 10000000.0 - 11644473600


class Directory(object):
    """One directory from the table, made usable."""

    CACHE_S = 60

    def __init__(self, row):
        self.row = row
        self.name = row['name']
        self.hosts = [h.strip() for h in str(row.get('hosts') or '').split(',') if h.strip()]
        self.port = int(row.get('port') or 636)
        self.tls = row.get('tls') or 'ldaps'
        # NULL (a row imported or moved without it) is verify, never off (1.0.57).
        self.verify = row.get('verify') is None or bool(int(row.get('verify') or 0))
        self.ca = row.get('ca') or ''
        self.weak = bool(int(row.get('weak') or 0))    # old, weak certificates (1.0.77)
        self.base = row.get('base') or ''
        self.bind_dn = row.get('bind_dn') or ''
        self.bind_pw = row.get('bind_pw') or ''
        self.timeout = float(row.get('timeout_s') or 10)
        self.cache = {}
        self.lock = threading.Lock()
        self.last_good = None

    def _hostport(self, host):
        host = str(host).strip()
        # [fd00::1]:636 and [fd00::1] as well (1.0.44); a bare IPv6 address
        # has no port of its own.
        m = re.match(r'^\[([^\]]+)\](?::(\d+))?\Z', host)
        if m:
            return m.group(1), int(m.group(2) or self.port)
        m = re.match(r'^([^:]+)(?::(\d+))?\Z', host)
        if m:
            return m.group(1), int(m.group(2) or self.port)
        return host, self.port

    # Servers that did not answer, and until when they are passed over
    # (1.0.101): every request asked each of them in turn and waited out its
    # timeout first - with two dead servers of 10 s, every sign-in of every
    # realm waited 20 s and the workers were all taken. Shared by every
    # directory object (a reload makes new ones).
    DEAD = {}
    DEAD_S = 30
    DEAD_LOCK = threading.Lock()

    def _order(self):
        """The servers in the order to ask them: the one that answered last
        first, those that did not answer lately last - and when none has,
        one try every few seconds, the rest refused at once."""
        order = [h for h in self.hosts if h]
        if self.last_good in order:
            order.remove(self.last_good)
            order.insert(0, self.last_good)
        t = time.time()
        with self.DEAD_LOCK:
            live = [h for h in order if self.DEAD.get(h.lower(), 0) <= t]
            if live:
                return live + [h for h in order if h not in live]
            probe = self.DEAD.get('probe:' + self.name.lower(), 0)
            if probe > t - 5:
                return []
            self.DEAD['probe:' + self.name.lower()] = t
        return order[:1]

    def _down(self, host):
        with self.DEAD_LOCK:
            if len(self.DEAD) > 1000:
                self.DEAD.clear()
            self.DEAD[str(host).lower()] = time.time() + self.DEAD_S

    def _up(self, host):
        with self.DEAD_LOCK:
            self.DEAD.pop(str(host).lower(), None)

    def link(self, bind=True):
        """A conversation with the first server that answers, signed in as the
        reading account. LdapUnreachable where none of them can be."""
        tried = []
        order = self._order()
        if not order:
            tried.append('every server failed within the last %d s' % self.DEAD_S)
        refused = None
        for host in order:
            h, p = self._hostport(host)
            one = Ldap(h, p, self.tls, self.ca, self.verify, self.timeout, self.weak)
            try:
                one.open()
                if bind and self.bind_dn:
                    try:
                        one.bind(self.bind_dn, self.bind_pw)
                    except LdapUnreachable:
                        raise
                    except LdapError as e:
                        if e.code in LDAP_TRY_ANOTHER or e.code is None:
                            # Busy, unavailable, an answer that does not read
                            # (1.0.59): that server's trouble - the next one.
                            raise
                        one.close()
                        # The reading account refused - an answer of the
                        # server itself - is the same on every server: no
                        # point going round them all.
                        refused = LdapUnreachable('the account this reads the directory with '
                                                  '(%s) was refused by %s: %s'
                                                  % (self.bind_dn, h, e), e.code, e.detail)
                        break
                self.last_good = host
                self._up(host)
                return one
            except (LdapError, OSError, ValueError) as e:
                # Unreachable, timed out, the line dropped, StartTLS hung
                # (1.0.57): the next server is asked - a server that takes
                # the connection and then says nothing no longer stops
                # every sign-in.
                one.close()
                self._down(host)
                tried.append('%s: %s' % (h, e))
                if host == self.last_good:
                    self.last_good = None
        if refused is not None:
            raise refused
        raise LdapUnreachable('no server of %s could be reached (%s)'
                              % (self.name, '; '.join(tried) or 'none is set'))

    def find_user(self, name, how='upn'):
        """The entry of one account, or None. `how` is upn (the whole
        name@realm against userPrincipalName), sam (the part before the @
        against sAMAccountName) or mail."""
        key = ('u', how, str(name).lower())
        with self.lock:
            got = self.cache.get(key)
            if got and time.time() - got[0] < self.CACHE_S:
                return got[1]
        said = str(name or '').strip()
        if how == 'sam':
            said = said.split('@', 1)[0].split('\\')[-1]
            want = ldap_equal(self.row.get('user_attr') or 'sAMAccountName', said)
        elif how == 'mail':
            want = ldap_equal('mail', said)
        else:
            want = ldap_equal('userPrincipalName', said)
        flt = ldap_and(ldap_equal('objectClass', 'user'), want)
        link = self.link()
        try:
            # Three, not two (1.0.101): a computer's account among them is
            # dropped below, and must not hide a second person of the name.
            rows = link.search(self.base, flt, USER_ATTRS, scope=2, limit=3)
        finally:
            link.close()
        entry = None
        # A computer's account is not a person's (1.0.101): objectClass=user
        # takes them in on AD, and anybody in the domain may make up to ten
        # with a password of their own choosing - which then outlive them.
        rows = [r for r in rows if not computer_account(r)]
        if rows:
            r = rows[0]
            a = {k.lower(): v for k, v in r['attrs'].items()}
            first = lambda k: (a.get(k.lower()) or [''])[0]
            uac = 0
            try:
                uac = int(first('userAccountControl') or 0)
            except ValueError:
                pass
            try:
                uacc = int(first('msDS-User-Account-Control-Computed') or 0)
            except ValueError:
                uacc = 0
            entry = {'dn': r['dn'], 'sam': first('sAMAccountName'),
                     'upn': first('userPrincipalName'), 'display': first('displayName'),
                     'mail': first('mail'), 'uac': uac,
                     'disabled': bool(uac & AD_UAC_DISABLED),
                     'expires': ad_time(first('accountExpires')),
                     'locked': bool(uacc & AD_UACC_LOCKED),
                     'pw_expired': bool(uacc & AD_UACC_PW_EXPIRED),
                     # An AD account (it has a sAMAccountName) whose state
                     # could not be read: not taken as "in use" (1.0.101).
                     'uac_unread': bool(first('sAMAccountName')) and not first('userAccountControl'),
                     # Ranged too (memberOf;range=0-1499, 1.0.59).
                     'member_of': [g for k, v in a.items()
                                   if k == 'memberof' or k.startswith('memberof;range=')
                                   for g in (v or [])],
                     'department': first('department'), 'title': first('title'),
                     # For a code by SMS (1.0.76): what the enrolment page offers.
                     'mobile': first('mobile') or first('telephoneNumber'),
                     'phone': first('telephoneNumber'),
                     'pw_set': ad_time(first('pwdLastSet')),
                     'many': len(rows) > 1}
        with self.lock:
            self.cache[key] = (time.time(), entry)
            if len(self.cache) > 5000:
                self.cache.clear()
        return entry

    def groups_of(self, entry, nested=True):
        """[(dn, cn)] of every group the account is in - with the groups
        inside groups where `nested`, which on Active Directory is one search
        with the in-chain matching rule rather than a walk of the tree."""
        if not entry:
            return []
        if not nested:
            return [(g, cn_of(g)) for g in entry.get('member_of') or []]
        key = ('g', entry['dn'].lower())
        with self.lock:
            got = self.cache.get(key)
            if got and time.time() - got[0] < self.CACHE_S:
                return got[1]
        link = self.link()
        link.PAGES_MOST = 20            # a sign-in's groups, not a census (1.0.59)
        try:
            rows = link.search(self.base, ldap_and(ldap_equal('objectClass', 'group'),
                                                   ldap_in_chain('member', entry['dn'])),
                               ('cn',), scope=2, limit=5000, paged=True)
        finally:
            link.close()
        out = [(r['dn'], (r['attrs'].get('cn') or [cn_of(r['dn'])])[0]) for r in rows]
        with self.lock:
            self.cache[key] = (time.time(), out)
        return out

    def group_dns(self, name):
        """The DN of the one group a name given without its place stands for
        (1.0.101), as a set of 0 or 1 lower-case DNs. Matched by its name
        alone, any group anywhere under the base called alike - one a
        helpdesk or an OU's admin could make - passed as the real one, the
        administrators' group too. So: the group whose sAMAccountName it is
        (one in a domain, never two); where nothing has one, the group
        whose cn it is - and if more than one is, none of them."""
        said = str(name or '').strip()
        key = ('gn', said.lower())
        with self.lock:
            got = self.cache.get(key)
            if got and time.time() - got[0] < self.CACHE_S:
                return got[1]
        # From the root of the domain, not the base the accounts are looked
        # for under: groups often live elsewhere (OU=Groups beside OU=Users).
        dcs = [p for p in re.split(r'(?<!\\),', str(self.base or '')) if
               p.strip().lower().startswith('dc=')]
        where = ','.join(p.strip() for p in dcs) or self.base
        link = self.link()
        link.PAGES_MOST = 5
        try:
            rows = link.search(where, ldap_and(
                ldap_equal('objectClass', 'group'),
                ldap_or(ldap_equal('sAMAccountName', said), ldap_equal('cn', said))),
                ('cn', 'sAMAccountName'), scope=2, limit=50, paged=True)
        finally:
            link.close()

        def first(r, a):
            for k, v in r['attrs'].items():
                if k.lower() == a and v:
                    return str(v[0])
            return ''
        by_sam = [r['dn'] for r in rows if first(r, 'samaccountname').lower() == said.lower()]
        by_cn = [r['dn'] for r in rows if (first(r, 'cn') or cn_of(r['dn'])).lower() == said.lower()]
        pick = by_sam if by_sam else by_cn
        out = {pick[0].lower()} if len(pick) == 1 else set()
        if len(pick) > 1:
            log_sparing('group-many-' + said.lower(), 'the group %s named without its place '
                        'answers to %d groups in %s (%s): none of them is taken - give it as '
                        'its full DN' % (said, len(pick), self.name, '; '.join(pick[:4])), 'warn')
        with self.lock:
            if len(self.cache) > 5000:
                self.cache.clear()
            self.cache[key] = (time.time(), out)
        return out

    def password_ok(self, entry, password):
        """True, or LdapError with the directory's reason in words."""
        if not str(password or ''):
            raise LdapError('a password is needed')
        if not str((entry or {}).get('dn') or '').strip():
            # A bind with no name and a password is an anonymous one on many
            # servers (1.0.101): never asked.
            raise LdapError('no account to check the password of')
        if any(ord(c) < 32 or ord(c) == 127 for c in str(password)):
            # Cut at a NUL somewhere on the way, a password is empty - and an
            # empty one binds anonymously (1.0.101).
            raise LdapError('the password holds a control character')
        tried = []
        order = self._order()
        if not order:
            tried.append('every server failed within the last %d s' % self.DEAD_S)
        for host in order:
            h, p = self._hostport(host)
            one = Ldap(h, p, self.tls, self.ca, self.verify, self.timeout, self.weak)
            try:
                one.open()
            except (LdapError, OSError) as e:
                self._down(host)
                tried.append(str(e))
                continue
            try:
                one.bind(entry['dn'], password)
                self._up(host)
                return True
            except LdapUnreachable as e:
                # The line dropped mid-bind: the next server is asked, the
                # password is not called wrong (1.0.44).
                self._down(host)
                tried.append(str(e))
                continue
            except LdapError as e:
                # Busy, unavailable, or an answer that does not read (1.0.59):
                # not the directory's word on the password - the next one.
                if e.code in LDAP_TRY_ANOTHER or (e.code is None and 'does not read' in str(e)):
                    tried.append(str(e))
                    continue
                raise
            finally:
                one.close()
        raise LdapUnreachable('no server of %s could be reached (%s)'
                              % (self.name, '; '.join(tried)))

    def find_users(self, like, limit=25):
        """People whose name, account, principal name or mail holds what is
        typed - for the boxes that offer a person as one types (1.0.19)."""
        like = str(like or '').strip()
        if len(like) < 2:
            return []
        attr = self.row.get('user_attr') or 'sAMAccountName'
        want = ldap_and(ldap_equal('objectClass', 'user'),
                        ldap_or(ldap_contains(attr, like), ldap_contains('userPrincipalName', like),
                                ldap_contains('displayName', like), ldap_contains('mail', like)))
        link = self.link()
        try:
            rows = link.search(self.base, want, ('sAMAccountName', 'userPrincipalName',
                                                 'displayName', 'mail', 'userAccountControl',
                                                 'mobile', 'telephoneNumber', attr), scope=2,
                                limit=limit + 10)
        finally:
            link.close()
        out = []
        for r in rows:
            a = {k.lower(): v for k, v in r['attrs'].items()}
            first = lambda k: (a.get(k.lower()) or [''])[0]
            if str(first('sAMAccountName')).endswith('$'):
                continue                         # a computer, not a person
            try:
                uac = int(first('userAccountControl') or 0)
            except ValueError:
                uac = 0
            out.append({'dn': r['dn'], 'sam': first(attr) or first('sAMAccountName'),
                        'upn': first('userPrincipalName'), 'display': first('displayName'),
                        'mail': first('mail'), 'disabled': bool(uac & AD_UAC_DISABLED),
                        'mobile': first('mobile') or first('telephoneNumber')})
        low = like.lower()
        out.sort(key=lambda u: (not (u['sam'] or '').lower().startswith(low),
                                not (u['display'] or '').lower().startswith(low),
                                (u['display'] or u['sam'] or '').lower()))
        return out[:limit]

    def find_groups(self, like='', limit=300):
        """Group names for a picker."""
        want = ldap_equal('objectClass', 'group')
        if like.strip():
            want = ldap_and(want, ldap_contains('cn', like.strip()))
        link = self.link()
        try:
            rows = link.search(self.base, want, ('cn', 'description'), scope=2,
                               limit=limit, paged=True)
        finally:
            link.close()
        out = [{'dn': r['dn'], 'cn': (r['attrs'].get('cn') or [cn_of(r['dn'])])[0],
                'description': (r['attrs'].get('description') or [''])[0]} for r in rows]
        return sorted(out, key=lambda g: g['cn'].lower())

    def check(self):
        """Every server, step by step, the way isemon's directory check reads."""
        out = []
        began = time.time()
        for host in self.hosts:
            h, p = self._hostport(host)
            steps = []
            one = Ldap(h, p, self.tls, self.ca, self.verify, self.timeout, self.weak)
            t = time.time()
            try:
                one.open()
                steps.append({'what': 'reached %s:%d%s' % (h, p, {
                    'ldaps': ' over TLS', 'starttls': ' and started TLS'}.get(self.tls, '')),
                    'ok': True, 'said': '%d ms' % int((time.time() - t) * 1000)})
            except (LdapError, OSError) as e:
                steps.append({'what': 'reach the server %s:%d' % (h, p), 'ok': False, 'said': str(e)})
                out.append({'host': h, 'port': p, 'steps': steps, 'ok': False})
                continue
            try:
                if self.bind_dn:
                    one.bind(self.bind_dn, self.bind_pw)
                    steps.append({'what': 'signed in as %s' % self.bind_dn, 'ok': True,
                                  'said': ''})
                rows = one.search(self.base, ldap_present('objectClass'), ('objectClass',),
                                  scope=0, limit=1)
                steps.append({'what': 'read the base %s' % self.base, 'ok': bool(rows),
                              'said': '' if rows else 'nothing is there - is the base right?'})
                n = len(one.search(self.base, ldap_equal('objectClass', 'group'), ('cn',),
                                   scope=2, limit=5000, paged=True))
                steps.append({'what': 'counted the groups', 'ok': True,
                              'said': '%d group(s) under the base' % n})
                out.append({'host': h, 'port': p, 'steps': steps, 'ok': bool(rows)})
            except LdapError as e:
                steps.append({'what': 'the next step', 'ok': False, 'said': str(e),
                              'detail': e.detail})
                out.append({'host': h, 'port': p, 'steps': steps, 'ok': False})
            finally:
                one.close()
        return {'name': self.name, 'servers': out, 'ok': bool(out) and all(s['ok'] for s in out),
                'took_ms': int((time.time() - began) * 1000), 'tls': self.tls,
                'verify': self.verify, 'weak': self.weak}


def lockout_minutes(n):
    """How long a token is locked after its n-th wrong code in a row, or 0.

    Locked at every `lockout_after` wrong codes - 10, 20, 30... - and each
    time twice as long as the time before, up to a day (1.0.101). The count
    is no longer set back to 0 when the lock is set (as 1.0.94 did): that
    gave a patient guesser 10 more codes every quarter of an hour, for ever
    - some 870 a day against a realm that asks for the code alone. It goes
    back to 0 only when a right code is given or an administrator unlocks
    the token; the owner's first typo after a lock does not lock it again.
    """
    after = int(CONFIG.get('lockout_after') or 0)
    if not after or n < after or n % after:
        return 0
    base = max(1, int(CONFIG.get('lockout_min') or 15))
    rounds = n // after - 1
    return int(min(base * (2 ** min(rounds, 16)), max(base, 24 * 60)))


def lockout_said(store, name, n, mins):
    """A lock written to the log and, so somebody sees it, to the events."""
    log('the token of %s is locked out for %d min after %d wrong codes in a row'
        % (name, mins, n), 'warn')
    try:
        store.add_event('tokens', 'the token of %s is locked out for %d min after %d wrong '
                        'codes in a row - somebody may be guessing its codes' % (name, mins, n),
                        'warn', who='otp')
    except Exception:                                   # noqa: BLE001
        pass


SCRATCH_GUARD_MOST = 20          # a day's refused tries before recovery codes rest (1.0.101)
SCRATCH_GUARD_S = 86400


def scratch_guard_times(store, name):
    try:
        got = [float(x) for x in json.loads(store.get_meta('scratchguard:' + norm_name(name))
                                            or '[]')]
    except (ValueError, TypeError):
        got = []
    return [x for x in got if time.time() - x < SCRATCH_GUARD_S]


def scratch_guard_note(store, name):
    """One request whose password and recovery code could not both be right
    (1.0.101) - see the RADIUS side. Written only over what was read."""
    k = 'scratchguard:' + norm_name(name)
    for _round in range(8):
        raw = store.get_meta(k)
        times = scratch_guard_times(store, name)[-(SCRATCH_GUARD_MOST * 2):] + [time.time()]
        new = json.dumps(times)
        if raw is None:
            try:
                store.db.run('INSERT INTO meta (k, v) VALUES (?, ?)', (k, new))
                break
            except Exception:                           # noqa: BLE001
                continue
        if store.db.run('UPDATE meta SET v = ? WHERE k = ? AND v = ?', (new, k, raw)):
            break
    if len(times) == SCRATCH_GUARD_MOST:
        store.add_event('tokens', 'the recovery codes of %s are not taken for a day: %d '
                        'requests in a day had a wrong password or a wrong recovery code - '
                        'somebody may be guessing them (Unlock it on the token gives them back)'
                        % (norm_name(name), SCRATCH_GUARD_MOST), 'warn', who='otp')


def scratch_guarded(store, name):
    return len(scratch_guard_times(store, name)) >= SCRATCH_GUARD_MOST


def entry_unusable(entry, locked=True):
    """Why the directory's account may not sign in now, or None (1.0.101):
    switched off, run out, locked out, its password expired - or, on AD,
    its state not readable at all, which is not taken as "in use"."""
    if not entry:
        return 'there is no such account'
    if entry.get('disabled'):
        return 'it is disabled in the directory'
    if entry.get('uac_unread'):
        return 'the directory does not say whether it is in use (userAccountControl cannot be read)'
    if entry.get('expires') and entry['expires'] < time.time():
        return 'it expired %s' % stamp(entry['expires'])
    if locked and entry.get('locked'):
        return 'it is locked out in the directory'
    if locked and entry.get('pw_expired'):
        return 'its password has expired in the directory'
    return None


def computer_account(r):
    """Whether a search result is a computer's account (1.0.101)."""
    a = {k.lower(): v for k, v in (r.get('attrs') or {}).items()}
    if any(str(x).lower() == 'computer' for x in a.get('objectclass') or []):
        return True
    return str((a.get('samaccountname') or [''])[0]).endswith('$')


def group_matches(wanted, have, ad=None):
    """Whether any group in `have` ([(dn, cn)]) is one of `wanted` (names or
    DNs). Returns the wanted entry that matched first, in `wanted`'s order.

    A name without its place is the one group `ad` says it is (1.0.101), by
    its DN - never any group of that cn wherever it is. Without `ad` to ask,
    a name alone matches nothing."""
    by_dn = {dn.lower() for dn, _ in have}
    by_cn = {str(cn).lower() for _, cn in have}
    for one in wanted:
        said = str(one.get('group') if isinstance(one, dict) else one).strip()
        if not said:
            continue
        if '=' in said and ',' in said:
            if said.lower() in by_dn:
                return one
        elif said.lower() in by_cn and ad is not None:
            try:
                dns = ad.group_dns(said)
            except LdapError as e:
                # Not known which group it is: no match, never a guess.
                log_sparing('group-dns', 'the group %s could not be looked up in %s: %s'
                            % (said, ad.name, e), 'warn')
                dns = set()
            if dns & by_dn:
                return one
    return None


# ---------------------------------------------------------------------------
# The tokens themselves
# ---------------------------------------------------------------------------
# The words a check of a code ends in are totpcgi's own, letter for letter:
# isemon reads them out of the token log and turns them into its own words
# (`OTP_SAYS`), and anything that already watches a token server knows them.
SAY_OK = 'Valid token used'
SAY_OK_DRIFT = 'Valid token within window size used'
SAY_SCRATCH = 'Scratch-token used'
SAY_BAD = 'Not a valid token'
SAY_REUSED = 'Token has already been used once'
SAY_RATE = 'Rate-limit reached, please try again later'
SAY_LOCKED = 'Locked out after too many wrong codes, please try again later'
SAY_NONE = 'No token is enrolled for this account'
SAY_OFF = 'This token is switched off'
SAY_PENDING = 'This token has not been confirmed yet'
SAY_LOST = 'The key of this token cannot be opened on this machine'


def seal_codes(codes, bind=None):
    """Recovery codes kept so that an administrator can show them again -
    each with when it was used, if it was: sealed with the key of the tokens,
    beside their hashes, which are what a code is checked against."""
    if not codes:
        return ''
    out = []
    for c in codes:
        out.append(dict(c) if isinstance(c, dict) else {'c': str(c), 'used': None})
    return seal_secret(json.dumps(out), bind)


def open_codes(value, bind=None):
    """The codes `seal_codes` kept, as [{c, used}] - also the plain JSON list
    an older version left in pending_scratch. None when none are kept."""
    if not value:
        return None
    text = unseal_secret(value, bind)
    if text is None and str(value).lstrip().startswith('['):
        text = value
    try:
        got = json.loads(text) if text else None
    except ValueError:
        return None
    if not isinstance(got, list):
        return None
    return [dict(x) if isinstance(x, dict) else {'c': str(x), 'used': None} for x in got]


class Tokens(object):
    """Making, checking and looking after tokens."""

    def __init__(self, store):
        self.store = store
        # A fixed row of locks, a name always to the same one: two checks of
        # one token wait for each other, and the row cannot grow however
        # many names are tried.
        self.locks = [threading.RLock() for _ in range(1024)]  # re-entered (1.0.59)
        self.on_check = None                       # (name, ok, said, how, src, rid)

    def lock_of(self, name):
        return self.locks[zlib.crc32(str(name).encode('utf-8')) % len(self.locks)]

    # ---- made ------------------------------------------------------------------
    def label_for(self, name):
        tpl = str(CONFIG.get('totp_label') or '{user}')
        return tpl.replace('{user}', name).replace('{name}', name.split('@', 1)[0])[:190]

    def fresh(self):
        """A new key and new recovery codes, not yet anybody's."""
        secret = b32_new(20)
        codes = scratch_new(int(CONFIG.get('scratch_count') or 0),
                            int(CONFIG.get('scratch_digits') or 8))
        return secret, codes

    def picture(self, name, secret, digits=None, period=None, algorithm=None, issuer=None):
        """What the person scans, in every shape a page wants it."""
        digits = int(digits or CONFIG.get('totp_digits') or 6)
        period = int(period or CONFIG.get('totp_period') or 30)
        algorithm = str(algorithm or CONFIG.get('totp_algorithm') or 'SHA1')
        issuer = issuer if issuer is not None else str(CONFIG.get('totp_issuer') or '')
        uri = otpauth_uri(secret, self.label_for(name), issuer, digits, period, algorithm)
        return {'uri': uri, 'qr': qr_data_uri(uri), 'secret': secret,
                'secret_spaced': ' '.join(secret[i:i + 4] for i in range(0, len(secret), 4)),
                'issuer': issuer, 'label': self.label_for(name), 'digits': digits,
                'period': period, 'algorithm': algorithm}

    def enroll(self, name, by, pending=False, secret=None, codes=None, display='', note=None):
        """A token for `name`, replacing any there was. `pending` makes it wait
        for a code before it is used. Returns the picture and the codes."""
        # One at a time per name, with confirm (1.0.59): a confirm landing on
        # a key written meanwhile made an unproven key active.
        with self.lock_of(norm_name(name)):
            return self._enroll(name, by, pending, secret, codes, display, note)

    def _enroll(self, name, by, pending=False, secret=None, codes=None, display='', note=None,
                extra=None):
        name = norm_name(name)
        if not name:
            raise ValueError('a token needs a name')
        # 180 at most (1.0.44): staged:NAME and mailed:NAME have to fit a key.
        # No control character either (1.0.103): a NUL is stored as U+FFFD,
        # and the key sealed to the name as sent never opened again.
        if not re.match(r'^[^\s,;=\x00-\x1f\x7f]{1,180}\Z', name):
            raise ValueError('a name has no spaces, commas, semicolons or = in it, and '
                             'is 180 characters at most')
        if secret is None:
            secret, codes = self.fresh()
        codes = list(codes or [])
        # The picture first (1.0.103): one that cannot be made (an issuer too
        # long for a QR code) refused before the token's key was replaced -
        # the old key gone and the new one never shown.
        out = self.picture(name, secret)
        fields = {
            'secret': seal_secret(secret, token_bind(name)),
            'digits': int(CONFIG.get('totp_digits') or 6),
            'period': int(CONFIG.get('totp_period') or 30),
            'algorithm': str(CONFIG.get('totp_algorithm') or 'SHA1'),
            'state': 'pending' if pending else 'active', 'last_step': 0,
            'scratch': json.dumps([scratch_hash(name, c) for c in codes]),
            'scratch_sealed': seal_codes(codes, token_bind(name)),
            'scratch_left': len(codes), 'created': time.time(), 'created_by': str(by)[:190],
            'activated': None if pending else time.time(), 'failures': 0,
            'fail_times': '[]', 'locked_until': None,
            'issuer': str(CONFIG.get('totp_issuer') or ''),
            'label': self.label_for(name), 'pending_secret': None, 'pending_scratch': None,
            'pending_at': None, 'pending_by': None, 'last_used': None, 'last_from': '',
            'last_how': '', 'kind': '', 'dest': ''}
        if display:
            fields['display'] = str(display)[:300]
        if note is not None:
            fields['note'] = str(note)[:400]
        if extra:
            fields.update(extra)
        self.store.token_write(name, fields)
        self._staged_forget(name)
        try:                            # a new token was never switched off (1.0.61)
            self.store.db.run('DELETE FROM meta WHERE k = ?', ('disabled_from:' + name,))
        except Exception:                               # noqa: BLE001
            pass
        out['scratch'] = codes
        out['name'] = name
        return out

    def enroll_sent(self, name, by, kind, dest, display='', note=None, lang=None,
                    mail_fmt=None):
        """A token that gets its codes sent (1.0.76): by mail or SMS to
        `dest`. No key anybody scans - one is kept all the same, never shown,
        so everything that reads a token's columns reads this one too - and
        recovery codes as any token has. In use at once: the address or the
        number was proven by the one who made it."""
        if kind not in ('mail', 'sms'):
            raise ValueError('a token that gets codes sent is mail or sms')
        dest = dest_checked(kind, dest)
        name = norm_name(name)
        with self.lock_of(name):
            out = self._enroll(name, by, pending=False, display=display, note=note,
                               extra=dict({'kind': kind, 'dest': dest,
                                           'digits': int(CONFIG.get('code_digits') or 6),
                                           'issuer': '', 'label': ''},
                                          **dict({'lang': lang} if lang in ('cs', 'en') else {},
                                                 **({'mail_fmt': mail_fmt}
                                                    if mail_fmt in ('html', 'text') else {}))))
        return {'name': name, 'kind': kind, 'dest': dest, 'scratch': out.get('scratch') or []}

    def dest_change(self, name, dest):
        """Where a mail or SMS token's codes go."""
        name = norm_name(name)
        with self.lock_of(name):
            tok = self.store.token(name)
            kind = token_kind(tok)
            if not tok or kind == 'totp':
                raise ValueError('%s has no token that gets codes sent' % name)
            dest = dest_checked(kind, dest)
            self.store.token_update(tok['id'], {'dest': dest})
        return dest

    def used_sent(self, name, how):
        """A sent code was right: written on the token as a code from the
        phone would be."""
        self.store.db.run("UPDATE tokens SET last_used = ?, failures = 0, fail_times = '[]', "
                          'last_how = ? WHERE name = ?', (time.time(), how, norm_name(name)))

    # ---- the shape of a key waiting beside an old one (1.0.32) ----------
    # A replacement is made with the settings of the day - digits, period,
    # hash - which need not be the old token's: an imported SHA-1 six-digit
    # token replaced while the settings say SHA-512 and eight digits. The
    # token's own columns describe the old key until the new one is
    # confirmed, so the new key's shape is kept beside it.
    def staged_shape(self, name):
        try:
            got = json.loads(self.store.get_meta('staged:' + norm_name(name), '') or '{}')
        except ValueError:
            got = {}
        return {'digits': int(got.get('digits') or CONFIG.get('totp_digits') or 6),
                'period': int(got.get('period') or CONFIG.get('totp_period') or 30),
                'algorithm': str(got.get('algorithm') or CONFIG.get('totp_algorithm') or 'SHA1'),
                'issuer': str(got.get('issuer') if got.get('issuer') is not None
                              else CONFIG.get('totp_issuer') or ''),
                'fails': int(got.get('fails') or 0),
                'fail_times': got.get('fail_times') if isinstance(got.get('fail_times'), list)
                else []}

    def _staged_forget(self, name):
        try:
            self.store.db.run('DELETE FROM meta WHERE k = ?', ('staged:' + norm_name(name),))
        except Exception:                               # noqa: BLE001
            pass

    def stage_replacement(self, name, by):
        """A new key for somebody who has a token already, kept beside the
        old one until a code from the new one proves it was scanned. The old
        one goes on working until then."""
        name = norm_name(name)
        with self.lock_of(name):
            return self._stage_replacement(name, by)

    def _stage_replacement(self, name, by):
        if not self.store.token(name):
            raise ValueError('%s has no token to replace' % name)
        secret, codes = self.fresh()
        shape = {'digits': int(CONFIG.get('totp_digits') or 6),
                 'period': int(CONFIG.get('totp_period') or 30),
                 'algorithm': str(CONFIG.get('totp_algorithm') or 'SHA1'),
                 'issuer': str(CONFIG.get('totp_issuer') or '')}
        out = self.picture(name, secret, shape['digits'], shape['period'], shape['algorithm'],
                           shape['issuer'] or None)        # first (1.0.103)
        self.store.set_meta('staged:' + name, json.dumps(shape))
        self.store.token_write(name, {
            'pending_secret': seal_secret(secret, token_bind(name)),
            'pending_scratch': seal_codes(codes, token_bind(name)), 'pending_at': time.time(),
            'pending_by': str(by)[:190]})
        out['scratch'] = codes
        out['name'] = name
        return out

    def confirm(self, name, code, how='portal', src=''):
        """A code from a token that is waiting - a new one, or a replacement
        staged beside an old one. (ok, words)."""
        name = norm_name(name)
        # One at a time per name, as a check is (1.0.33).
        with self.lock_of(name):
            return self._confirm(name, code, how, src)

    def _confirm(self, name, code, how='portal', src=''):
        tok = self.store.token(name)
        if not tok:
            return False, SAY_NONE
        staged = bool(tok.get('pending_secret'))
        # Only a token that waits is confirmed: a new one, or one with a
        # replacement staged. A token an administrator switched off is not
        # brought back by its owner's code (1.0.15), and an active one with
        # nothing staged has nothing to confirm.
        if tok.get('state') == 'disabled':
            return False, SAY_OFF
        if not staged and tok.get('state') != 'pending':
            return False, 'There is nothing to confirm: this token is in use already'
        sealed = tok['pending_secret'] if staged else tok['secret']
        secret = unseal_secret(sealed or '', token_bind(name))
        if not secret:
            return False, SAY_LOST
        # A staged key is checked with its own shape, not the old token's.
        shape = self.staged_shape(name) if staged else {
            'digits': tok['digits'] or 6, 'period': tok['period'] or 30,
            'algorithm': tok['algorithm'] or 'SHA1', 'issuer': tok.get('issuer') or ''}
        # Throttled like a sign-in (1.0.33): the same pause after wrong codes,
        # so the page cannot be used to guess a waiting key's codes quickly.
        t = time.time()
        try:
            # A waiting replacement counts its wrong codes beside its own
            # shape (1.0.61): in the token's own they paused the token still
            # in use as well.
            fails = [float(x) for x in (shape.get('fail_times') if staged
                                        else json.loads(tok.get('fail_times') or '[]')) or []]
        except (ValueError, TypeError):
            fails = []
        tries = int(CONFIG.get('rate_limit_tries') or 0)
        fails = [x for x in fails if t - x < int(CONFIG.get('rate_limit_s') or 30)]
        if float(tok.get('locked_until') or 0) > t:
            self._said(name, False, SAY_LOCKED + ' (confirming a new token)', how, src, '')
            return False, SAY_LOCKED
        if tries and len(fails) >= tries:
            self._said(name, False, SAY_RATE + ' (confirming a new token)', how, src, '')
            return False, SAY_RATE
        step = totp_match(secret, code, None, shape['digits'], shape['period'],
                          shape['algorithm'], self.window(tok))
        if step is None and staged:
            # A replacement's wrong codes do not lock the token still in use
            # (1.0.59) - the phone answering with the old account is the
            # usual wrong code here. They are counted against the waiting key:
            # past the lockout count it is thrown away, to be made again.
            shape['fail_times'] = fails + [t]
            shape['fails'] = int(shape.get('fails') or 0) + 1
            after = int(CONFIG.get('lockout_after') or 0)
            if after and shape['fails'] >= after:
                self.drop_staged(name)
                self._said(name, False, SAY_BAD + ' (confirming a new token - too many, '
                           'the new key is thrown away)', how, src, '')
                return False, (SAY_BAD + '. Too many wrong codes: the new key was thrown '
                               'away - the token in use goes on working; make a new one.')
            self.store.set_meta('staged:' + name, json.dumps(shape))
            self._said(name, False, SAY_BAD + ' (confirming a new token)', how, src, '')
            return False, SAY_BAD + '. ' + self.why_wrong(secret, code, shape)
        if step is None:
            # Counted toward the lockout as well (1.0.44), not only the short
            # pause: a waiting key could be guessed at day after day.
            n = self._failure_counted(tok['id'])
            # The same lock as a wrong code to sign in with (1.0.101).
            mins = lockout_minutes(n)
            self._fail_noted(tok['id'], t, int(CONFIG.get('rate_limit_s') or 30), mins)
            if mins:
                lockout_said(self.store, name, n, mins)
            self._said(name, False, SAY_BAD + ' (confirming a new token)', how, src, '')
            return False, SAY_BAD + '. ' + self.why_wrong(secret, code, shape)
        # last_step never goes down for the same key: its code of a step
        # already used stays used. A new key starts from its own step
        # (1.0.33): steps of another period are not comparable - a 30 s
        # token replaced by a 60 s one refused every code after.
        fields = {'state': 'active', 'activated': time.time(),
                  'last_step': int(step) if staged else max(int(step),
                                                             int(tok.get('last_step') or 0)),
                  'failures': 0, 'fail_times': '[]', 'locked_until': None}
        if staged:
            codes = [x['c'] for x in (open_codes(tok.get('pending_scratch'),
                                                 token_bind(name)) or [])]
            # A token that got codes sent becomes the app's (1.0.76).
            fields.update({'kind': '', 'dest': ''})
            fields.update({'secret': tok['pending_secret'], 'pending_secret': None,
                           'pending_scratch': None, 'pending_at': None, 'pending_by': None,
                           'scratch': json.dumps([scratch_hash(name, c) for c in codes]),
                           'scratch_sealed': seal_codes(codes, token_bind(name)),
                           'scratch_left': len(codes), 'created': time.time(),
                           'created_by': tok.get('pending_by') or how,
                           'digits': shape['digits'], 'period': shape['period'],
                           'algorithm': shape['algorithm'],
                           'label': self.label_for(name),
                           'issuer': shape['issuer'],
                           # The old key's use is not the new one's (1.0.36).
                           'last_used': None, 'last_from': '', 'last_how': ''})
        self.store.token_update(tok['id'], fields)
        if staged:
            self._staged_forget(name)
        self._said(name, True, 'Token confirmed', how, src, '')
        return True, 'Token confirmed'

    @staticmethod
    def why_wrong(secret, code, tok):
        """What a wrong code most likely means, for the person typing it."""
        period = int(tok.get('period') or 30)
        far = totp_match(secret, code, None, tok.get('digits') or 6, period,
                         tok.get('algorithm') or 'SHA1', 40)
        if far is not None:
            off = (far - totp_step(None, period)) * period
            return ('It is this token\'s code, but from %d s %s: the clock of the phone is '
                    'wrong - set it to the network\'s time.' % (abs(off), 'ago' if off < 0
                                                                 else 'ahead'))
        return ('It is not a code of this token. If the application shows several accounts '
                'of this name, an older one is answering - type the code of the newest, or '
                'take the old one out of the application.')

    def drop_staged(self, name):
        with self.lock_of(norm_name(name)):
            self._drop_staged(name)

    def _drop_staged(self, name):
        tok = self.store.token(name)
        if not tok:
            self._staged_forget(name)
            return
        self.store.token_update(tok['id'], {'pending_secret': None, 'pending_scratch': None,
                                      'pending_at': None, 'pending_by': None})
        self._staged_forget(name)

    def new_scratch(self, name, by=''):
        name = norm_name(name)
        if not self.store.token(name):
            raise ValueError('%s has no token' % name)
        codes = scratch_new(int(CONFIG.get('scratch_count') or 0) or 5,
                            int(CONFIG.get('scratch_digits') or 8))
        self.store.token_write(name, {'scratch': json.dumps([scratch_hash(name, c)
                                                             for c in codes]),
                                      'scratch_sealed': seal_codes(codes, token_bind(name)),
                                      'scratch_left': len(codes)})
        return codes

    @staticmethod
    def window(tok):
        w = tok.get('window_steps')
        if w is None or int(w) < 0:
            return int(CONFIG.get('totp_window') or 0)
        return int(w)

    # ---- checked ---------------------------------------------------------------
    def check(self, name, code, how='radius', src='127.0.0.1', rid='', dry=False, quiet=False):
        """Whether `code` is right for the token of `name`. (ok, words, facts)
        - the words totpcgi would have said. `quiet`: not written down - the
        probe that finds where a password ends and its code begins."""
        name = norm_name(name)
        code = str(code or '').strip()
        with self.lock_of(name):
            ok, said, facts = self._check(name, code, dry)
        # A dry check - the administrator's test - is written down like any
        # other, marked as such; the only thing it leaves alone is the code,
        # which stays usable.
        if not quiet:
            self._said(name, ok, said, how + '-dry' if dry else how, src, rid, facts.get('off'))
        return ok, said, facts

    def _failure_counted(self, tok_id):
        """One more wrong code on the token, and which one it is - each
        wrong code its own number (1.0.101). Counted up and read back, two
        at once both read 11 and neither was the 10th: the lock at every
        tenth was skipped."""
        for _round in range(16):
            n = int(self.store.db.value('SELECT COALESCE(failures, 0) FROM tokens WHERE id = ?',
                                        (tok_id,)) or 0)
            if self.store.db.run('UPDATE tokens SET failures = ? WHERE id = ? AND '
                                 'COALESCE(failures, 0) = ?', (n + 1, tok_id, n)):
                return n + 1
        self.store.db.run('UPDATE tokens SET failures = COALESCE(failures, 0) + 1 WHERE id = ?',
                          (tok_id,))
        return int(self.store.db.value('SELECT failures FROM tokens WHERE id = ?',
                                       (tok_id,)) or 0)

    def _fail_noted(self, tok_id, t, span, mins):
        """The time of a wrong code added to the token's recent ones, and the
        lock set - by a conditional update (1.0.101): two nodes each reading
        the list and writing it back with their own time added lost one of
        them, and a guesser sending to both nodes at once got twice the
        tries the pause allows."""
        for _round in range(8):
            was = self.store.db.value('SELECT fail_times FROM tokens WHERE id = ?', (tok_id,))
            try:
                fails = [float(x) for x in json.loads(was or '[]')]
            except (ValueError, TypeError):
                fails = []
            fails = [x for x in fails if t - x < span] + [t]
            sets, args = 'fail_times = ?', [json.dumps(fails[-50:])]
            if mins:
                sets += ', locked_until = ?'
                args.append(t + 60 * mins)
            if was is None:
                hit = self.store.db.run('UPDATE tokens SET %s WHERE id = ? AND fail_times IS NULL'
                                        % sets, tuple(args) + (tok_id,))
            else:
                hit = self.store.db.run('UPDATE tokens SET %s WHERE id = ? AND fail_times = ?'
                                        % sets, tuple(args) + (tok_id, was))
            if hit:
                break
        else:
            fields = {'fail_times': json.dumps([t])}
            if mins:
                fields['locked_until'] = t + 60 * mins
            self.store.token_update(tok_id, fields)

    def blocked(self, name):
        """What the token would say before any code is looked at - locked out,
        paused, switched off - or None. Asked before the directory password
        (1.0.57), so a locked token is not a free way to guess AD passwords."""
        tok = self.store.token(norm_name(name))
        if not tok:
            return None
        t = time.time()
        if tok.get('state') == 'disabled':
            return SAY_OFF
        if float(tok.get('locked_until') or 0) > t:
            return SAY_LOCKED
        tries = int(CONFIG.get('rate_limit_tries') or 0)
        span = int(CONFIG.get('rate_limit_s') or 30)
        try:
            fails = [float(x) for x in json.loads(tok.get('fail_times') or '[]')]
        except (ValueError, TypeError):
            fails = []
        if tries and len([x for x in fails if t - x < span]) >= tries:
            return SAY_RATE
        return None

    def _check(self, name, code, dry):
        tok = self.store.token(name)
        facts = {}
        if not tok:
            return False, SAY_NONE, facts
        if tok.get('state') == 'disabled':
            return False, SAY_OFF, facts
        if tok.get('state') == 'pending':
            return False, SAY_PENDING, facts
        t = time.time()
        try:
            fails = [float(x) for x in json.loads(tok.get('fail_times') or '[]')]
        except (ValueError, TypeError):
            fails = []
        tries = int(CONFIG.get('rate_limit_tries') or 0)
        span = int(CONFIG.get('rate_limit_s') or 30)
        fails = [x for x in fails if t - x < span]
        # A lockout after many wrong codes in a row, however slowly they
        # came (1.0.33): the short pause alone let a patient guesser try
        # thousands of codes a day.
        if float(tok.get('locked_until') or 0) > t:
            return False, SAY_LOCKED, facts
        if tries and len(fails) >= tries:
            return False, SAY_RATE, facts
        secret = unseal_secret(tok.get('secret') or '', token_bind(name))
        if not secret:
            return False, SAY_LOST, facts
        digits = int(tok.get('digits') or 6)
        # Digits 0-9 and nothing else: \d also takes Arabic-Indic and other
        # digits, which then broke the comparison and left the request
        # unanswered and unwritten (1.0.33).
        plain = re.fullmatch(r'[0-9]+', code, re.ASCII) is not None

        def failed(said):
            # A dry check - the administrator's test, or the probe that finds
            # where a password ends and its code begins - counts nothing
            # (1.0.33): it is not somebody trying to sign in, and it counted
            # one typo three times.
            if dry:
                return False, said, facts
            # Counted in the database itself (1.0.44): two nodes reading
            # n and both writing n+1 lost one wrong code each time.
            n = self._failure_counted(tok['id'])
            mins = lockout_minutes(n)
            self._fail_noted(tok['id'], t, span, mins)
            if mins:
                lockout_said(self.store, name, n, mins)
            return False, said, facts
        if not plain:
            return failed(SAY_BAD)

        def scratch_try():
            """A recovery code: used once. None when it is not one."""
            if scratch_guarded(self.store, name):
                return None             # resting after many guesses (1.0.101)
            try:
                kept = json.loads(tok.get('scratch') or '[]')
            except ValueError:
                kept = []
            key = sealing_key()
            hit, h = scratch_find(name, code, kept, key)
            if hit:
                was = tok.get('scratch') or '[]'
                if not dry:
                    kept.remove(hit)
                    shown = codes_open(tok)
                    if shown is not None:
                        for one in shown:
                            if not one.get('used') and hmac.compare_digest(
                                    scratch_hash(name, one['c'], key), h):
                                one['used'] = t
                        # The rest, which were kept in the old shape too if
                        # this one was, written in the new one.
                        # (Without a sealed copy the others stay as they
                        # are until each is used.)
                        if hit != h:
                            kept = [scratch_hash(name, one['c'], key) for one in shown
                                    if not one.get('used')]
                    # Only if the codes are still the ones read: a recovery
                    # code used on the other node at the same moment is not
                    # used twice. (1.0.13)
                    won = self.store.db.run(
                        'UPDATE tokens SET scratch = ?, scratch_sealed = ?, scratch_left = ?, '
                        "last_used = ?, last_how = 'scratch', failures = 0, fail_times = '[]' "
                        'WHERE id = ? AND scratch = ?',
                        (json.dumps(kept), seal_codes(shown, token_bind(name)) if shown is not None else
                         (tok.get('scratch_sealed') or ''), len(kept), t, tok['id'], was))
                    if not won:
                        return False, SAY_REUSED, facts
                    # And used once anywhere (1.0.101): the row above can be
                    # written back by the other node's older copy of it.
                    if not once_take(self.store, 'scratch', name, h):
                        return False, SAY_REUSED, facts
                elif hit != h:
                    # Dry, so the code stays; but an entry in the old shape is
                    # rewritten in the new one now that it is known.
                    kept[kept.index(hit)] = h
                    self.store.db.run('UPDATE tokens SET scratch = ? WHERE id = ? AND scratch = ?',
                                      (json.dumps(kept), tok['id'], was))
                facts['scratch_left'] = len(kept)
                return True, SAY_SCRATCH, facts
            return None
        if token_kind(tok) != 'totp':
            # A token that gets its codes sent (1.0.76): what is checked here
            # is only ever a recovery code - the sent code is the
            # challenge's, and the key it keeps is never on any phone.
            got = scratch_try()
            return got if got is not None else failed(SAY_BAD)
        if len(code) != digits:
            got = scratch_try()
            return got if got is not None else failed(SAY_BAD)
        step = totp_match(secret, code, t, digits, tok.get('period') or 30,
                          tok.get('algorithm') or 'SHA1', self.window(tok))
        if step is None:
            # A recovery code as long as a code from the phone (1.0.33): with
            # the two lengths set alike, recovery codes were never tried.
            got = scratch_try()
            return got if got is not None else failed(SAY_BAD)
        facts['off'] = step - totp_step(t, tok.get('period') or 30)
        if CONFIG.get('totp_disallow_reuse', 1) and step <= int(tok.get('last_step') or 0):
            # Refused, but not counted as a wrong code (1.0.57): it is the
            # right code a second time - a NAS that sent the request again,
            # or to the other node - and counting it locked people out.
            return False, SAY_REUSED, facts
        if not dry:
            if CONFIG.get('totp_disallow_reuse', 1):
                # Used up with one conditional UPDATE: of two nodes asked for
                # the same code at the same moment, only one changes the row.
                won = self.store.db.run(
                    'UPDATE tokens SET last_step = ?, last_used = ?, failures = 0, '
                    "fail_times = '[]', last_how = 'code' WHERE id = ? AND "
                    'COALESCE(last_step, 0) < ?', (step, t, tok['id'], step))
                if not won:
                    return False, SAY_REUSED, facts
                # The step used once anywhere (1.0.101): on two replicating
                # nodes the UPDATE above holds only on its own database.
                # Tied to this key - the key itself, through an HMAC: the same
                # on both nodes whatever its sealed form, new with every key.
                if not once_take(self.store, 'step', name, '%s:%s:%s' % (
                        tok['id'], hmac.new(sealing_key() or b'', str(secret).encode(),
                                            hashlib.sha256).hexdigest()[:16], step)):
                    return False, SAY_REUSED, facts
            else:
                self.store.token_update(tok['id'], {'last_step': step, 'last_used': t,
                                                    'failures': 0, 'fail_times': '[]',
                                                    'last_how': 'code'})
        return True, (SAY_OK if facts['off'] == 0 else SAY_OK_DRIFT), facts

    def mark_from(self, name, src, client=''):
        # One UPDATE (1.0.33): read and written again, it was two round trips
        # on every request let in. With the RADIUS client it came through
        # (1.0.58).
        self.store.db.run('UPDATE tokens SET last_from = ?, last_client = ? WHERE name = ?',
                          (str(src or '')[:120], str(client or '')[:120], norm_name(name)))

    def _said(self, name, ok, said, how, src, rid, off=None):
        try:
            self.store.otp_add({'ts': time.time(), 'name': name, 'ok': 1 if ok else 0,
                                'said': said, 'how': how, 'src': str(src or '')[:120],
                                'rid': str(rid or '')[:120],
                                'step_off': int(off) if off is not None else None})
        except Exception as e:
            log('the check of a code could not be written down: %s' % e, 'warn')
        if self.on_check:
            try:
                self.on_check(name, ok, said, how, src, rid)
            except Exception as e:
                log('the check of a code could not be sent on: %s' % e, 'warn')


# ---------------------------------------------------------------------------
# Sending the logs to isemon
# ---------------------------------------------------------------------------
# isemon reads a token server through two files rsyslog writes for it: what
# totpcgi said about every code (`totp.cgi`), and every RADIUS packet the
# FreeRADIUS in front of it wrote into its detail files, one to a line
# (`radius-detail`). This writes both, in exactly those shapes, as syslog to
# isemon's receiver - and into files here as well - so that isemon reads this
# server with the readers it already has and nothing changed on its side.

SYSLOG_FACILITY = {'auth': 4, 'authpriv': 10, 'local5': 21, 'daemon': 3, 'user': 1}


def syslog_targets(text, strict=False):
    """`host[:port][/udp|/tcp]`, comma separated, as (host, port, proto)."""
    out = []
    for one in re.split(r'[,;\s]+', str(text or '')):
        one = one.strip()
        if not one:
            continue
        m = re.match(r'^(\[[0-9a-fA-F:]+\]|[A-Za-z0-9.\-]+)(?::(\d+))?(?:/(udp|tcp))?\Z',
                     one, re.I)
        if not m:
            if strict:
                raise BadSetting('isemon_targets: %r is not host[:port][/udp|/tcp]' % one)
            continue
        port = int(m.group(2) or 514)
        if strict and not 0 < port < 65536:
            raise BadSetting('isemon_targets: %d is not a port' % port)
        out.append((m.group(1).strip('[]'), port, (m.group(3) or 'udp').lower()))
    return out


def syslog_stamp(ts=None):
    """`Oct 22 15:31:02` - RFC 3164, the shape the readers on the other side
    expect: no year, no zone, the day padded with a space."""
    t = datetime.fromtimestamp(float(ts if ts is not None else time.time()))
    return '%s %2d %s' % (t.strftime('%b'), t.day, t.strftime('%H:%M:%S'))


def detail_quote(value):
    """A value as FreeRADIUS writes it in a detail file: a string in quotes,
    with its quotes and backslashes escaped."""
    said = str(value)
    if re.match(r'^(0x[0-9a-fA-F]*|\d+|\d+\.\d+\.\d+\.\d+)\Z', said) or said in (
            'Access-Request', 'Access-Accept', 'Access-Reject', 'Access-Challenge',
            'Accounting-Request') or re.match(r'^[A-Z][A-Za-z0-9.-]*\Z', said) and \
            said in [w for d in RADIUS_VALUES.values() for w in d.values()]:
        return said
    return '"%s"' % said.replace('\\', '\\\\').replace('"', '\\"')


class Shipper(object):
    """A queue and a thread that empties it into isemon's receivers and the
    files here. Nothing that answers a VPN ever waits for any of it."""

    def __init__(self):
        self.q = queue.Queue(maxsize=20000)
        self.targets = []
        self.tcp = {}
        self.udp4 = None
        self.udp6 = None
        self.files = {}
        self.sent = collections.Counter()
        self.trouble = {}
        self.down = {}              # a TCP target that failed: (until, wait) - 1.0.59
        self.missed = collections.Counter()
        self.dropped = 0
        self.last_sent = 0.0
        self.stop_flag = False
        self.thread = threading.Thread(target=self.run, name='shipper', daemon=True)
        self.configure()
        self.thread.start()

    def configure(self):
        self.targets = syslog_targets(CONFIG.get('isemon_targets')) if CONFIG.get('isemon') \
            else []
        for key, sock in list(self.tcp.items()):
            if (key[0], key[1], 'tcp') not in self.targets:
                try:
                    sock.close()
                except OSError:
                    pass
                self.tcp.pop(key, None)

    def host(self):
        return str(CONFIG.get('isemon_hostname') or '').strip() or short_host()

    # ---- what is said ----------------------------------------------------------
    def put(self, tag, facility, words, ts=None, file_name=None):
        if not CONFIG.get('isemon') and not CONFIG.get('ship_files'):
            return
        most = int(CONFIG.get('isemon_max_bytes') or 1800)
        if len(words.encode('utf-8')) > most:
            words = words.encode('utf-8')[:most].decode('utf-8', 'ignore') + ' ...TRUNCATED'
        line = '%s %s %s[%d]: %s' % (syslog_stamp(ts), self.host(), tag, os.getpid(),
                                     words.replace('\n', ' ').replace('\r', ' '))
        pri = SYSLOG_FACILITY.get(facility, 1) * 8 + 5          # notice
        try:
            self.q.put_nowait((pri, line, file_name))
        except queue.Full:
            self.dropped += 1

    def token_line(self, name, ok, said, how, src, rid):
        """`totp.cgi[pid]: Success: user=..., mode=PAM_SM_AUTH, host=..., rid=...,
        message=...` - totpcgi's own line, with the request id isemon joins it
        to the RADIUS packet by."""
        if how not in ('radius', 'test'):
            mode = 'PROVISION' if how == 'portal' else how.upper()
        else:
            mode = 'PAM_SM_AUTH'
        clean = lambda s: re.sub(r'[\r\n]', ' ', str(s or ''))
        rid = re.sub(r'[^A-Za-z0-9.:_-]', '', str(rid or ''))[:64]
        words = '%s: user=%s, mode=%s, host=%s, %smessage=%s' % (
            'Success' if ok else 'Failure', re.sub(r'[,=\s]', '_', clean(name)), mode, '127.0.0.1',
            ('rid=%s, ' % rid) if rid else '', clean(said))
        self.put('totp.cgi', 'auth', words, file_name='totp.cgi.log')

    def detail_line(self, nas, kind, ts, pairs, ident=''):
        """`radius-detail[pid]: nas=... id=... file=auth-detail-YYYYMMDD ts=[ctime]
        Name = value, ...` - one detail record a line, the way the shipper
        isemon ships with writes it."""
        if not CONFIG.get('isemon_detail', 1):
            return
        fname = '%s-%s' % (kind, datetime.fromtimestamp(ts).strftime('%Y%m%d'))
        body = ', '.join('%s = %s' % (k, detail_quote(v)) for k, v in pairs)
        rid = ident or hashlib.sha1(('%s|%s|%s|%s' % (nas, fname, ts, body))
                                    .encode('utf-8', 'replace')).hexdigest()[:16]
        words = 'nas=%s id=%s file=%s ts=[%s] %s' % (nas, rid, fname, time.ctime(ts), body)
        self.put('radius-detail', 'local5', words, file_name='radius-detail.log')

    def event_line(self, kind, words, level, who):
        if CONFIG.get('isemon_events'):
            self.put('otp', 'daemon', '%s: %s%s' % (kind, words, (' (by %s)' % who) if who
                                                    else ''), file_name=None)

    # ---- sending ---------------------------------------------------------------
    def run(self):
        while not self.stop_flag:
            try:
                pri, line, file_name = self.q.get(timeout=1.0)
            except queue.Empty:
                continue
            if file_name and CONFIG.get('ship_files'):
                self._to_file(file_name, line)
            if CONFIG.get('isemon'):
                for target in list(self.targets):
                    self._to_target(target, '<%d>%s' % (pri, line))

    def _to_file(self, name, line):
        path = LOG_DIR / name
        f = self.files.get(name)
        try:
            if f is not None:
                try:
                    if os.fstat(f.fileno()).st_ino != os.stat(path).st_ino:
                        raise OSError('rotated')
                except OSError:
                    f.close()
                    f = None
            if f is None:
                LOG_DIR.mkdir(parents=True, exist_ok=True)
                f = open(path, 'a', encoding='utf-8')
                self.files[name] = f
            f.write(line + '\n')
            f.flush()
        except OSError as e:
            self.trouble['file:' + name] = str(e)

    def _to_target(self, target, data):
        host, port, proto = target
        key = '%s:%d/%s' % target
        raw = data.encode('utf-8', 'replace')
        try:
            if proto == 'udp':
                fam = socket.AF_INET6 if ':' in host else socket.AF_INET
                if fam == socket.AF_INET6:
                    if self.udp6 is None:
                        self.udp6 = socket.socket(socket.AF_INET6, socket.SOCK_DGRAM)
                    self.udp6.sendto(raw, (host, port))
                else:
                    if self.udp4 is None:
                        self.udp4 = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                    self.udp4.sendto(raw, (host, port))
            else:
                # A TCP target that cannot be reached is left alone for a
                # while (1.0.59): every line waited 5 s on it, the queue
                # filled, and the files here lost lines with it.
                until, wait = self.down.get(key, (0.0, 0.0))
                if time.time() < until:
                    self.missed[key] += 1
                    return
                sock = self.tcp.get((host, port))
                for attempt in (1, 2):
                    if sock is None:
                        sock = socket.create_connection((host, port), timeout=5)
                        sock.settimeout(5)
                        self.tcp[(host, port)] = sock
                    try:
                        sock.sendall(raw + b'\n')
                        break
                    except OSError:
                        try:
                            sock.close()
                        except OSError:
                            pass
                        sock = None
                        self.tcp.pop((host, port), None)
                        if attempt == 2:
                            raise
            self.sent[key] += 1
            self.last_sent = time.time()
            self.trouble.pop(key, None)
            self.down.pop(key, None)
        except OSError as e:
            if key not in self.trouble:
                log('isemon at %s cannot be sent to: %s' % (key, e), 'warn')
            if proto != 'udp':
                _u, wait = self.down.get(key, (0.0, 0.0))
                wait = min(300.0, max(15.0, wait * 2))
                self.down[key] = (time.time() + wait, wait)
                self.missed[key] += 1
                e = '%s - tried again in %d s, %d line(s) not sent to it' % (
                    e, int(wait), self.missed[key])
            self.trouble[key] = '%s (%s)' % (e, datetime.now().strftime('%H:%M:%S'))

    def state(self):
        return {'on': bool(CONFIG.get('isemon')), 'host': self.host(),
                'targets': ['%s:%d/%s' % t for t in self.targets],
                'sent': dict(self.sent), 'trouble': dict(self.trouble),
                'queued': self.q.qsize(), 'dropped': self.dropped,
                'last_sent': self.last_sent, 'files': bool(CONFIG.get('ship_files')),
                'file_dir': str(LOG_DIR)}

    def flush(self, wait=3.0):
        until = time.time() + wait
        while not self.q.empty() and time.time() < until:
            time.sleep(0.05)


def codes_open(tok):
    """A token's recovery codes as kept to be shown again, each one no longer
    in its list of hashes marked used (1.0.61). Two nodes using a code each
    at the same moment end with the same list of hashes, but each node's
    sealed copy may still hold the other's code as unused - and a rename,
    an export or the codes view would have brought it back."""
    shown = open_codes(tok.get('scratch_sealed'), token_bind(tok.get('name')))
    if shown is None:
        return None
    try:
        kept = [str(k) for k in json.loads(tok.get('scratch') or '[]')]
    except (ValueError, TypeError):
        return shown
    key = sealing_key()
    for one in shown:
        if isinstance(one, dict) and not one.get('used') and \
                not scratch_find(tok.get('name'), one.get('c'), kept, key)[0]:
            one['used'] = time.time()
    return shown
# ---------------------------------------------------------------------------
# Codes sent by mail or SMS, and the VPN's second window (1.0.76)
# ---------------------------------------------------------------------------
# A token is one of three kinds:
#   totp  - the authenticator app, as it always was (the kind column empty);
#   mail  - no app: after the directory password a code is mailed;
#   sms   - the same, by SMS through a gateway or a modem.
# A mail or SMS token holds no key anybody scans - only where the codes go
# (`dest`) and its recovery codes. It signs in through RADIUS
# Challenge/Response: the first Access-Request carries the directory
# password; it is checked (and the groups), a code is sent and an
# Access-Challenge goes back with a State; the VPN (Cisco Secure Client and
# others) shows a second window, and the code comes back in a second
# Access-Request with that State.
#
# A challenge is kept in the database (meta 'chal:' + hash of the State), so
# that the answer is taken by either node of a cluster. It holds a hash of
# the code, never the code.

