def token_lang(tok):
    """The language a token's codes and questions are in (1.0.82): its own,
    else the setting's."""
    lang = str((tok or {}).get('lang') or '')
    return lang if lang in CODE_TEXTS else code_lang()


def token_mail_fmt(tok):
    fmt = str((tok or {}).get('mail_fmt') or '')
    if fmt in ('html', 'text'):
        return fmt
    return 'text' if CONFIG.get('code_mail_fmt') == 'text' else 'html'


def code_lang():
    lang = str(CONFIG.get('code_lang') or CONFIG.get('mail_lang') or 'cs')
    return lang if lang in CODE_TEXTS else 'cs'


def code_words(key, lang=None, w=None, **kw):
    """One of the texts of codes, as Settings → Message texts has it
    (1.0.103), its {words} filled in."""
    if w is None:
        w = texts_for('code', lang if lang in CODE_TEXTS else code_lang())
    kw.setdefault('site', str(CONFIG.get('site_name') or socket.gethostname()))
    kw.setdefault('minutes', max(1, int(CONFIG.get('code_ttl_s') or 300) // 60))
    return w[key].format(**kw)


def token_kind(tok):
    k = str((tok or {}).get('kind') or '').strip().lower()
    return k if k in ('mail', 'sms') else 'totp'


def mail_checked(dest):
    dest = str(dest or '').strip()
    if not re.match(r'^[^@\s<>,;"]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,}\Z', dest):
        raise ValueError('that is not a mail address')
    return dest


def phone_checked(dest):
    """A number as +CCCNNN…: spaces, dashes and brackets taken out, the
    country code of the settings put before a number written without one."""
    raw = re.sub(r'[\s().\-/]', '', str(dest or ''))
    if raw.startswith('00'):
        raw = '+' + raw[2:]
    if not raw.startswith('+'):
        pre = str(CONFIG.get('sms_prefix') or '').strip()
        if not pre:
            raise ValueError('write the number with its country code: +420 603 123 456')
        raw = pre + raw.lstrip('0')
    if not re.match(r'^\+[1-9][0-9]{7,14}\Z', raw):
        raise ValueError('that is not a phone number - write it as +420 603 123 456')
    return raw


def dest_checked(kind, dest):
    if kind == 'mail':
        return mail_checked(dest)
    if kind == 'sms':
        return phone_checked(dest)
    return ''


def dest_masked(kind, dest):
    """What the VPN and the pages may say of where a code went."""
    dest = str(dest or '')
    if kind == 'mail' and '@' in dest:
        who, _, where = dest.partition('@')
        return '%s%s@%s' % (who[:1], '*' * max(2, min(len(who) - 1, 6)), where)
    if kind == 'sms' and len(dest) > 4:
        return '%s%s%s' % (dest[:4], '*' * (len(dest) - 7), dest[-3:])
    return dest


def code_new():
    digits = int(CONFIG.get('code_digits') or 6)
    return '%0*d' % (digits, secrets.randbelow(10 ** digits))


def code_hash(salt, code):
    key = sealing_key() or b''
    return hmac.new(key + b'|code', ('%s|%s' % (salt, code)).encode('utf-8'),
                    hashlib.sha256).hexdigest()


def code_channels():
    """Which ways of sending can be used at all - set up, not switched off."""
    out = []
    if (CONFIG.get('mail_mode') or 'off') != 'off' and CONFIG.get('mail_from'):
        out.append('mail')
    mode = CONFIG.get('sms_mode') or 'off'
    if (mode == 'http' and CONFIG.get('sms_url')) or \
            (mode == 'spool' and CONFIG.get('sms_spool_dir')) or \
            (mode == 'teltonika' and CONFIG.get('sms_tel_host')):
        out.append('sms')
    return out


def realm_methods(realm):
    """The kinds of token a realm offers, in the order given; the app when
    nothing is said (every realm made before 1.0.76)."""
    raw = (realm or {}).get('methods')
    if isinstance(raw, str):
        try:
            raw = json.loads(raw) if raw.strip().startswith('[') else re.split(r'[,\s]+', raw)
        except ValueError:
            raw = []
    got = [str(x).strip().lower() for x in (raw or []) if str(x).strip().lower() in CODE_KINDS]
    seen = []
    for k in got:
        if k not in seen:
            seen.append(k)
    return seen or ['totp']


# ---- how many were sent ------------------------------------------------------------
def code_send_allowed(store, name):
    """Whether one more code may be sent to `name` now; counted in the
    database so both nodes count together. Written only over what was read
    (1.0.94): requests at once each read "four sent" and all sent one."""
    k = 'codesent:' + norm_name(name)
    for _ in range(8):
        t = time.time()
        span = 60 * int(CONFIG.get('code_send_window_min') or 15)
        raw = store.get_meta(k)
        try:
            times = [float(x) for x in json.loads(raw or '[]')]
        except (ValueError, TypeError):
            times = []
        times = [x for x in times if t - x < span]
        if len(times) >= int(CONFIG.get('code_send_max') or 5):
            return False
        new = json.dumps(times + [t])
        if raw is None:
            try:
                store.db.run('INSERT INTO meta (k, v) VALUES (?, ?)', (k, new))
                return True
            except Exception:                           # noqa: BLE001
                continue                # written by another meanwhile: read again
        if store.db.run('UPDATE meta SET v = ? WHERE k = ? AND v = ?', (new, k, raw)):
            return True
    return False


def code_send_wait_min(store, name):
    """How many minutes until one more code may go to `name` (1.0.116) - not
    the whole window, which the page said even when a minute was left."""
    span = 60 * int(CONFIG.get('code_send_window_min') or 15)
    limit = int(CONFIG.get('code_send_max') or 5)
    try:
        times = sorted(float(x) for x in json.loads(store.get_meta('codesent:' + norm_name(name))
                                                    or '[]'))
    except (ValueError, TypeError):
        times = []
    t = time.time()
    times = [x for x in times if t - x < span]
    if len(times) < limit:
        return 1
    return max(1, int(-(-(times[len(times) - limit] + span - t) // 60)))


# ---- sending -------------------------------------------------------------------------
class SmsError(RuntimeError):
    pass


def sms_plain(text):
    """The text without accents (1.0.81): one letter outside the GSM
    alphabet makes the whole SMS the wide one, 70 characters a part."""
    if not CONFIG.get('sms_plain', 1):
        return text
    import unicodedata
    out = unicodedata.normalize('NFKD', str(text))
    out = ''.join(c for c in out if not unicodedata.combining(c))
    return out.replace('–', '-').replace('—', '-').replace('„', '"').replace('“', '"')


# ---- a Teltonika gateway (TRB140, RUT…), as zigmon speaks to it (1.0.81) -----------
TELTONIKA = {'token': None, 'until': 0.0, 'modem': None, 'last': 0.0}
TELTONIKA_LOCK = threading.Lock()


def _tel_url(path, params=None):
    host = str(CONFIG.get('sms_tel_host') or '').strip().rstrip('/')
    if not host:
        raise SmsError('no address of the Teltonika gateway is set - Settings → Codes by e-mail '
                       'and SMS')
    scheme = 'https' if CONFIG.get('sms_tel_https', 1) else 'http'
    if '://' in host:
        scheme, host = host.split('://', 1)
    url = '%s://%s%s' % (scheme, host, path)
    if params:
        url += '?' + urllib.parse.urlencode(params)
    return url


SMS_CA_META = 'sms_ca'          # the gateway's certificates trusted (1.0.89)


def sms_ca_pem(store=None):
    store = store or HA_STORE.get('store')
    if store is None:
        return ''
    try:
        return str(store.get_meta(SMS_CA_META) or '')
    except Exception:                                   # noqa: BLE001
        return ''


def sms_ca_set(store, pem, mode='add', fingerprint=''):
    """The certificates the Teltonika gateway is checked against - each added
    and taken out by itself, as the mail server's."""
    pem = str(pem or '').strip()
    have = split_certificates(sms_ca_pem(store))
    if mode == 'add' and pem:
        new = split_certificates(pem)
        if not new or not all(describe_certificate(b) for b in new):
            raise ValueError('that is not a certificate this can read: a PEM certificate '
                             'starts -----BEGIN CERTIFICATE-----')
        seen = {c['fingerprint'] for c in describe_certificates('\n'.join(have))}
        have += [b for b, c in zip(new, describe_certificates('\n'.join(new)))
                 if c['fingerprint'] not in seen]
    elif mode == 'drop':
        keep = [b for b, c in zip(have, describe_certificates('\n'.join(have)))
                if c['fingerprint'] != fingerprint]
        if len(keep) == len(have):
            raise ValueError('that certificate is not among the ones kept')
        have = keep
    else:
        have = []
    store.set_meta(SMS_CA_META, '\n'.join(have))
    return describe_certificates('\n'.join(have))


def _tel_is_name(host):
    host = host.split('://', 1)[-1].split('/')[0]
    if host.startswith('['):
        return False
    host = host.rsplit(':', 1)[0] if host.count(':') == 1 else host
    try:
        ipaddress.ip_address(host)
        return False
    except ValueError:
        return True


def _tel_ssl():
    if not CONFIG.get('sms_tel_verify'):
        # A TRB makes its own certificate; nothing can check it.
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        return ctx
    pem = sms_ca_pem()
    if not pem.strip():
        return ssl.create_default_context()
    # Only what was imported (1.0.89): the gateway's own certificate, or the
    # authority of your own that signed it. A gateway reached by its address
    # has no name to check against - its certificate is: the chain must end
    # in one of these.
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    try:
        ctx.load_verify_locations(cadata=pem)
    except (ssl.SSLError, ValueError) as e:
        raise SmsError('the certificates kept for the gateway cannot be read: %s' % e)
    # Any certificate imported is an anchor of its own (1.0.92): a TRB sends
    # only its own certificate, signed by a "ca" it never shows, and that
    # certificate alone - read from it - was refused as "unable to get local
    # issuer certificate". The strict checks of 3.13 are left out too: a
    # gateway's own certificate is not a web server's.
    ctx.verify_flags |= getattr(ssl, 'VERIFY_X509_PARTIAL_CHAIN', 0x80000)
    ctx.verify_flags &= ~getattr(ssl, 'VERIFY_X509_STRICT', 0x20)
    ctx.check_hostname = _tel_is_name(str(CONFIG.get('sms_tel_host') or ''))
    return ctx


def tel_peer_chain():
    """The certificates the gateway shows, read without checking them - for
    an administrator to look at and trust (1.0.89)."""
    host = str(CONFIG.get('sms_tel_host') or '').strip().rstrip('/')
    if not host:
        raise SmsError('no address of the Teltonika gateway is set')
    host = host.split('://', 1)[-1].split('/')[0]
    port = 443
    if host.startswith('['):
        name, _, rest = host[1:].partition(']')
        if rest.startswith(':'):
            port = int(rest[1:])
    elif host.count(':') == 1:
        name, port = host.split(':')
        port = int(port)
    else:
        name = host
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    try:
        with socket.create_connection((name, port), timeout=10) as raw:
            with ctx.wrap_socket(raw, server_hostname=name if _tel_is_name(name) else None) as tls:
                chain = []
                if hasattr(tls, 'get_unverified_chain'):
                    try:
                        chain = [c if isinstance(c, bytes) else c.public_bytes(1)
                                 for c in tls.get_unverified_chain() or []]
                    except Exception:                   # noqa: BLE001
                        chain = []
                if not chain:
                    chain = [tls.getpeercert(binary_form=True)]
    except (OSError, ssl.SSLError) as e:
        raise SmsError('%s:%d could not be reached over TLS: %s' % (name, port, e))
    pems = [ssl.DER_cert_to_PEM_cert(d).strip() for d in chain if d]
    return '\n'.join(pems)


def _tel_password():
    pw = CONFIG.get('sms_tel_password') or ''
    return (unseal_secret(pw) or '') if pw else ''


class _TelAnswer(object):
    """An answer already read - so that it could be written into the log."""

    def __init__(self, status, body):
        self.status, self._body = status, body

    def read(self, n=-1):
        got = self._body if n is None or n < 0 else self._body[:n]
        self._body = b'' if n is None or n < 0 else self._body[n:]
        return got

    def __enter__(self):
        return self

    def __exit__(self, *a):
        return False


def _tel_hidden(words):
    """A request or an answer as the debug log may hold it: no password,
    no token (1.0.113)."""
    words = re.sub(r'(?i)("(?:password|token)"\s*:\s*")[^"]*', r'\1***', words)
    words = re.sub(r'(?i)((?:password|token)=)[^&\s]*', r'\1***', words)
    return re.sub(r'(?i)(Bearer )\S+', r'\1***', words)


def _tel_open(req, timeout=20.0):
    loud = debugging('codes')
    began = time.time()
    if loud:
        body = req.data.decode('utf-8', 'replace') if isinstance(req.data, bytes) else ''
        log('sms: -> %s %s%s (waits %d s)' % (req.get_method(), _tel_hidden(req.full_url),
                                             (' ' + _tel_hidden(body)[:300]) if body else '',
                                             timeout), 'debug')
    try:
        r = urllib.request.urlopen(req, timeout=timeout, context=_tel_ssl()
                                   if req.full_url.startswith('https') else None)
        if not loud:
            return r
        with r:
            body = r.read(65536)
            status = getattr(r, 'status', 200)
        log('sms: <- HTTP %s in %.2f s: %s' % (status, time.time() - began, _tel_hidden(
            body.decode('utf-8', 'replace'))[:400]), 'debug')
        return _TelAnswer(status, body)
    except urllib.error.URLError as e:
        if loud:
            _tel_said_failed(e, began)
        # The certificate refused (1.0.89): nothing was sent, and the page
        # says what to do about it.
        if isinstance(getattr(e, 'reason', None), ssl.SSLCertVerificationError):
            raise SmsError('the gateway\'s certificate did not pass the check (%s): import its '
                           'certificate or the authority that signed it under Settings → Codes '
                           'by e-mail and SMS, or switch Check its certificate off'
                           % (getattr(e.reason, 'verify_message', '') or e.reason))
        raise
    except Exception as e:                              # noqa: BLE001
        if loud:
            _tel_said_failed(e, began)
        raise


def _tel_said_failed(e, began):
    extra = ''
    if isinstance(e, urllib.error.HTTPError):
        try:
            said = e.read(400)
            extra = ': ' + _tel_hidden(said.decode('utf-8', 'replace'))
            e.read = (lambda b: (lambda n=-1: b))(said)         # the caller reads it too
        except Exception:                               # noqa: BLE001
            pass
    log('sms: <- FAILED after %.2f s: %s %s%s' % (time.time() - began, type(e).__name__,
                                               getattr(e, 'reason', e), extra), 'debug')


def _tel_never_arrived(e):
    """Whether a failed request certainly never reached the gateway - a
    refused or reset connection. A read that timed out did reach it: the box
    took the message and has not answered, and sending it again is a second
    SMS on the person's phone (zigmon's lesson)."""
    if isinstance(e, socket.timeout):
        return False
    reason = getattr(e, 'reason', e)
    if isinstance(reason, socket.timeout):
        return False
    words = str(e).lower()
    if 'timed out' in words or 'timeout' in words:
        return False
    return isinstance(reason, (ConnectionRefusedError, ConnectionResetError,
                               ConnectionAbortedError, socket.gaierror)) or \
        any(w in words for w in ('refused', 'reset by peer', 'not known', 'no route',
                                 'broken pipe'))


def _tel_who():
    """What a login is for: another address, user or password is another
    login - a token kept from before a change is not used after it."""
    return hashlib.sha256(('%s|%s|%s|%s' % (CONFIG.get('sms_tel_host'), CONFIG.get('sms_tel_https'),
                                            CONFIG.get('sms_tel_user'), _tel_password()))
                          .encode('utf-8')).hexdigest()


def _tel_token(fresh=False):
    """A login on RutOS's own API: a token that lasts five minutes, renewed a
    minute before."""
    now = time.time()
    if TELTONIKA.get('who') != _tel_who():
        TELTONIKA.update(token=None, modem=None, who=_tel_who())
    if not fresh and TELTONIKA['token'] and now < TELTONIKA['until']:
        return TELTONIKA['token']
    body = json.dumps({'username': CONFIG.get('sms_tel_user') or 'admin',
                       'password': _tel_password()}).encode()
    tries = 0
    while True:
        tries += 1
        req = urllib.request.Request(_tel_url('/api/login'), data=body, method='POST',
                                     headers={'Content-Type': 'application/json'})
        try:
            with _tel_open(req, 15) as r:
                answer = json.loads(r.read() or b'{}')
            break
        except urllib.error.HTTPError as e:
            raise SmsError('the Teltonika would not let otp in (HTTP %d) - check its user and '
                           'password, and that the user may use the API' % e.code)
        except (urllib.error.URLError, OSError, ValueError) as e:
            # Signing in is asked again once (1.0.113): a box busy with the
            # modem leaves a login unanswered now and then, and asking again
            # sends nothing twice.
            if tries < 2 and not isinstance(e, ValueError):
                log('sms: the Teltonika did not answer the sign-in (%s) - asked again'
                    % getattr(e, 'reason', e), 'warn')
                time.sleep(1)
                continue
            raise SmsError('the Teltonika could not be reached%s: %s' % (
                ' (asked twice)' if tries > 1 else '', getattr(e, 'reason', e)))
    data = answer.get('data') or {}
    token = data.get('token') or answer.get('token') or ''
    if not token:
        raise SmsError('the Teltonika gave no token: %s' % json.dumps(answer)[:150])
    TELTONIKA['token'] = token
    TELTONIKA['until'] = now + max(30.0, float(data.get('expires') or 299) - 60)
    return token


def _tel_rest(path, method='GET', payload=None, timeout=20.0, again=True):
    data = json.dumps(payload).encode() if payload is not None else None
    req = urllib.request.Request(_tel_url('/api' + path), data=data, method=method,
                                 headers={'Content-Type': 'application/json',
                                          'Authorization': 'Bearer ' + _tel_token()})
    try:
        with _tel_open(req, timeout) as r:
            answer = json.loads(r.read() or b'{}')
    except urllib.error.HTTPError as e:
        said = ''
        try:
            said = e.read(300).decode('utf-8', 'replace')
        except Exception:                               # noqa: BLE001
            pass
        if e.code in (401, 403) and again:
            TELTONIKA['token'] = None                   # gone stale
            return _tel_rest(path, method, payload, timeout, again=False)
        raise SmsError('the Teltonika answered %s %s with HTTP %d %s' % (method, path, e.code,
                                                                         said))
    if answer.get('success') is False:
        raise SmsError('the Teltonika refused %s: %s' % (path, json.dumps(
            answer.get('errors') or answer)[:200]))
    return answer.get('data', answer)


def _tel_modem():
    if CONFIG.get('sms_tel_modem'):
        return str(CONFIG['sms_tel_modem']).strip()
    if TELTONIKA.get('who') != _tel_who():
        TELTONIKA.update(token=None, modem=None, who=_tel_who())
    if TELTONIKA['modem']:
        return TELTONIKA['modem']
    rows = _tel_rest('/modems/status') or []
    if isinstance(rows, dict):
        rows = [rows]
    first = next((r for r in rows if isinstance(r, dict) and r.get('id')), None)
    if not first:
        raise SmsError('the Teltonika named no modem')
    TELTONIKA['modem'] = str(first['id'])
    return TELTONIKA['modem']


def tel_send(to, text):
    """One SMS through a Teltonika, one at a time: the box sends one message
    after another, and a second asked for at once is taken and then left
    unanswered for a minute."""
    waited = time.time()
    with TELTONIKA_LOCK:
        gap = 2.0 - (time.time() - TELTONIKA['last'])
        if gap > 0:
            time.sleep(gap)
        loud = debugging('codes')
        if loud:
            log('sms: to %s, %d characters, through the Teltonika %s (%s), after %.1f s in the '
                'queue' % (to[:-3] + '***' if len(to) > 6 else to, len(text),
                           CONFIG.get('sms_tel_host'), CONFIG.get('sms_tel_api') or 'rest',
                           time.time() - waited), 'debug')
        began = time.time()
        try:
            said = _tel_send(to, text)
            if loud:
                log('sms: done in %.1f s - %s' % (time.time() - began, said), 'debug')
            return said
        except Exception as e:
            if loud:
                log('sms: FAILED after %.1f s - %s' % (time.time() - began, e), 'debug')
            raise
        finally:
            TELTONIKA['last'] = time.time()


def _tel_send(to, text):
    parts = 1 if len(text) <= (160 if all(ord(c) < 128 for c in text) else 70) else 2
    timeout = 20.0 * parts
    if (CONFIG.get('sms_tel_api') or 'rest') == 'cgi':
        number = '00' + to.lstrip('+')                  # Teltonika's CGI wants 00420…
        url = _tel_url('/cgi-bin/sms_send', {'username': CONFIG.get('sms_tel_user') or '',
                                             'password': _tel_password(), 'number': number,
                                             'text': text})
        tries = 0
        while True:
            tries += 1
            try:
                with _tel_open(urllib.request.Request(url), timeout) as r:
                    said = r.read(400).decode('utf-8', 'replace').strip()
                break
            except urllib.error.HTTPError as e:
                raise SmsError('the Teltonika answered HTTP %d: %s' % (
                    e.code, e.read(200).decode('utf-8', 'replace')))
            except (urllib.error.URLError, OSError) as e:
                if tries < 3 and _tel_never_arrived(e):
                    time.sleep(tries)
                    continue
                if not _tel_never_arrived(e):
                    return 'no answer from the Teltonika in %d s - the SMS has most likely gone' \
                        % timeout
                raise SmsError('the Teltonika could not be reached: %s' % getattr(e, 'reason', e))
        if 'error' in said.lower() and not said.lower().startswith('ok'):
            raise SmsError('the Teltonika said: %s' % said[:200])
        return 'the Teltonika said: %s' % (said[:120] or 'OK')
    tries = 0
    while True:
        tries += 1
        try:
            # How long each step took, said with the answer (1.0.109): a
            # test that took long tells whether it was the login, finding
            # the modem or the sending itself - RutOS answers the send only
            # once the modem has given the SMS to the network.
            t0 = time.time()
            _tel_token()
            t1 = time.time()
            modem = _tel_modem()
            t2 = time.time()
            out = _tel_rest('/messages/actions/send', 'POST',
                            {'data': {'number': to, 'message': text, 'modem': modem}},
                            timeout=timeout)
            t3 = time.time()
            steps = []
            if t1 - t0 > 0.05:
                steps.append('signing in %.1f s' % (t1 - t0))
            if t2 - t1 > 0.05:
                steps.append('finding the modem %.1f s' % (t2 - t1))
            steps.append('the modem sending it %.1f s' % (t3 - t2))
            return 'the Teltonika took it (%s; %s)' % (', '.join(steps), json.dumps(out)[:60])
        except SmsError:
            raise
        except (urllib.error.URLError, OSError) as e:
            if tries < 3 and _tel_never_arrived(e):
                TELTONIKA['token'] = None               # a new connection, a new login
                time.sleep(tries)
                continue
            if not _tel_never_arrived(e):
                return 'no answer from the Teltonika in %d s - the SMS has most likely gone' \
                    % timeout
            raise SmsError('the Teltonika could not be reached: %s' % getattr(e, 'reason', e))


def tel_check():
    """Whether the gateway is there and takes the password - nothing sent."""
    if (CONFIG.get('sms_tel_api') or 'rest') == 'cgi':
        url = _tel_url('/cgi-bin/sms_list', {'username': CONFIG.get('sms_tel_user') or '',
                                             'password': _tel_password()})
        try:
            with _tel_open(urllib.request.Request(url), 15) as r:
                said = r.read(300).decode('utf-8', 'replace')
        except (urllib.error.URLError, OSError) as e:
            raise SmsError('the Teltonika could not be reached: %s' % getattr(e, 'reason', e))
        if 'error' in said.lower() and 'no messages' not in said.lower():
            raise SmsError('the Teltonika said: %s' % said.strip()[:150])
        return 'the Teltonika answered and took the password'
    TELTONIKA['token'] = None
    _tel_token(fresh=True)
    TELTONIKA['modem'] = None
    return 'the Teltonika let otp in; its modem is %s' % _tel_modem()


# What a modem's status says, in the order shown (1.0.113). RutOS 7 names
# them so; a field it does not have is left out.
TEL_MODEM_FIELDS = (
    ('name', 'Modem'), ('model', 'Model'), ('operator', 'Operator'),
    ('ntype', 'Network'), ('conntype', 'Connection'), ('band', 'Band'),
    ('state', 'State'), ('operator_state', 'Registered'), ('netstate', 'Network state'),
    ('active_sim', 'SIM in use'), ('simstate', 'SIM'), ('pinstate', 'PIN'),
    ('signal_quality', 'Signal quality (%)'), ('rssi', 'RSSI (dBm)'), ('rsrp', 'RSRP (dBm)'),
    ('rsrq', 'RSRQ (dB)'), ('sinr', 'SINR (dB)'), ('temperature', 'Temperature (C)'),
    ('volte', 'VoLTE'), ('sms_center_address', 'SMS centre'), ('imei', 'IMEI'),
    ('version', 'Modem firmware'))


def tel_modem_words(row):
    out = [('id', str(row.get('id') or ''))]
    for k, words in TEL_MODEM_FIELDS:
        v = row.get(k)
        if v in (None, '', [], {}):
            continue
        if isinstance(v, (dict, list)):
            v = json.dumps(v)[:80]
        out.append((words, str(v)[:80]))
    if len(out) < 4:
        # Another firmware, other names: what it said, plainly.
        for k, v in list(row.items())[:12]:
            if k != 'id' and isinstance(v, (str, int, float)) and str(v) != '':
                out.append((str(k)[:30], str(v)[:80]))
    return out


def tel_test():
    """The gateway tried, step by step, without sending anything (1.0.113):
    reached, signed in, its modems and what each says about the network."""
    mode = (CONFIG.get('sms_tel_api') or 'rest')
    host = str(CONFIG.get('sms_tel_host') or '').strip()
    out = {'ok': False, 'steps': [], 'modems': [], 'api': mode, 'host': host,
           'https': bool(CONFIG.get('sms_tel_https')),
           'checked': bool(CONFIG.get('sms_tel_https') and CONFIG.get('sms_tel_verify'))}
    if not host:
        out['steps'].append({'what': 'the address', 'ok': False, 'secs': 0,
                             'said': 'no address of the gateway is saved'})
        return out

    def step(what, fn):
        t = time.time()
        try:
            got = fn()
        except SmsError as e:
            out['steps'].append({'what': what, 'ok': False, 'secs': round(time.time() - t, 2),
                                 'said': str(e)})
            return None, False
        out['steps'].append({'what': what, 'ok': True, 'secs': round(time.time() - t, 2),
                             'said': got if isinstance(got, str) else ''})
        return got, True

    with TELTONIKA_LOCK:
        if mode == 'cgi':
            _x, ok = step('signing in (Post/Get)', tel_check)
            out['ok'] = ok
            return out
        TELTONIKA['token'] = None
        TELTONIKA['modem'] = None
        _x, ok = step('signing in', lambda: (_tel_token(fresh=True) and 'let in as %s'
                                            % (CONFIG.get('sms_tel_user') or 'admin')))
        if not ok:
            return out
        rows, ok = step('its modems', lambda: _tel_rest('/modems/status'))
        if not ok:
            return out
        if isinstance(rows, dict):
            rows = [rows]
        rows = [r for r in (rows or []) if isinstance(r, dict)]
        want = str(CONFIG.get('sms_tel_modem') or '').strip()
        chosen = want or (str(rows[0].get('id')) if rows and rows[0].get('id') else '')
        for r in rows[:6]:
            out['modems'].append({'id': str(r.get('id') or ''), 'sends': str(r.get('id')) == chosen,
                                  'fields': tel_modem_words(r)})
        out['steps'][-1]['said'] = '%d modem(s)' % len(rows)
        if want and not any(str(r.get('id')) == want for r in rows):
            out['steps'].append({'what': 'the modem set', 'ok': False, 'secs': 0,
                                 'said': 'the gateway has no modem %s - it has %s' % (
                                     want, ', '.join(str(r.get('id')) for r in rows) or 'none')})
            return out
        if not chosen:
            out['steps'].append({'what': 'the modem', 'ok': False, 'secs': 0,
                                 'said': 'the gateway named no modem'})
            return out
        TELTONIKA['modem'] = chosen
        out['ok'] = True
    return out


def sms_send(to, text):
    """One SMS. Returns what the gateway said; raises SmsError."""
    mode = CONFIG.get('sms_mode') or 'off'
    if mode == 'off':
        raise SmsError('sending SMS is switched off - Settings → Codes by mail and SMS')
    text = sms_plain(text)
    if mode == 'teltonika':
        return tel_send(to, text)
    if mode == 'spool':
        folder = Path(str(CONFIG.get('sms_spool_dir') or '').strip())
        if not folder.is_dir():
            raise SmsError('the spool folder %s is not there' % folder)
        # smstools3: a file "To: 420…", an empty line, the text. Written
        # beside and renamed in, so the daemon never reads half of one.
        body = 'To: %s\nAlphabet: UTF-8\n\n%s\n' % (to.lstrip('+'), text)
        name = 'otp-%d-%s' % (int(time.time()), secrets.token_hex(4))
        tmp = folder / ('.' + name)
        try:
            with open(str(tmp), 'w', encoding='utf-8') as f:
                f.write(body)
            os.chmod(str(tmp), 0o664)
            os.rename(str(tmp), str(folder / name))
        except OSError as e:
            try:
                tmp.unlink()
            except OSError:
                pass
            raise SmsError('it could not be written into %s: %s' % (folder, e))
        return 'written into %s as %s' % (folder, name)
    url = str(CONFIG.get('sms_url') or '').strip()
    if not url:
        raise SmsError('no gateway address is set - Settings → Codes by mail and SMS')
    token = unseal_secret(CONFIG.get('sms_token') or '') or '' if CONFIG.get('sms_token') else ''
    vals = {'to': to, 'to_digits': to.lstrip('+'), 'text': text, 'token': token}

    def fill(tpl, how):
        def one(m):
            k = m.group(1)
            v = vals.get(k)
            if v is None:
                return m.group(0)
            if how == 'url':
                return urllib.parse.quote(v, safe='')
            if how == 'json':
                return json.dumps(v)[1:-1]
            return v
        return re.sub(r'\{(to|to_digits|text|token)\}', one, tpl)
    full = fill(url, 'url')
    method = (CONFIG.get('sms_method') or 'POST').upper()
    tpl = str(CONFIG.get('sms_body') or '')
    data, ctype = None, None
    if method == 'POST':
        if tpl.strip().startswith('{'):
            data, ctype = fill(tpl, 'json').encode('utf-8'), 'application/json'
        elif tpl.strip():
            data, ctype = fill(tpl, 'url').encode('utf-8'), 'application/x-www-form-urlencoded'
        else:
            data = b''
    req = urllib.request.Request(full, data=data, method=method)
    if ctype:
        req.add_header('Content-Type', ctype)
    for line in str(CONFIG.get('sms_headers') or '').splitlines():
        if ':' in line:
            k, _, v = line.partition(':')
            if k.strip():
                req.add_header(k.strip(), fill(v.strip(), 'raw'))
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            said = r.read(4000).decode('utf-8', 'replace')
            status = r.status
    except urllib.error.HTTPError as e:
        raise SmsError('the gateway answered %d: %s' % (e.code, e.read(300).decode('utf-8', 'replace')))
    except (urllib.error.URLError, OSError) as e:
        raise SmsError('the gateway could not be reached: %s' % getattr(e, 'reason', e))
    want = str(CONFIG.get('sms_ok_status') or '').strip()
    if want and want.lower() not in said.lower():
        raise SmsError('the gateway answered %d without "%s": %s' % (status, want, said[:300]))
    return 'the gateway answered %d%s' % (status, (': ' + said[:200]) if said.strip() else '')


def code_mail_html(code, purpose, lang, name='', display='', w=None):
    """The mail of a code in the same shape and colours as a token's mail
    with its QR code (1.0.79): the blue band, the white card, the code in a
    grey box, the warning in orange - tables and styles on each element, as
    every mail program shows them alike. Its words as Settings → Message
    texts has them (1.0.103), or `w` - the editor's, not yet saved."""
    lang = lang if lang in CODE_TEXTS else code_lang()
    if w is None:
        w = texts_for('code', lang)
    h = lambda t: html.escape(str(t or ''), quote=True)
    site = str(CONFIG.get('site_name') or socket.gethostname())
    issuer = str(CONFIG.get('totp_issuer') or '') or site
    minutes = max(1, int(CONFIG.get('code_ttl_s') or 300) // 60)
    # name@domain kept plain text, as in the token's mail.
    acc = ('<span style="white-space:nowrap">%s</span>' % h(name).replace('@', '@&#8205;')
           if name else '')
    font = "font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;"
    rows = []
    v = '' if purpose == 'signin' else 'v_'
    hello = (w['h_%shello' % v].format(name=h(display)) if display
             else w['h_%shello_anon' % v].format())
    if hello.strip():
        rows.append('<p style="margin:0 0 6px;font-size:16px;color:#111827">%s</p>' % hello)
    if purpose == 'signin':
        lede = w['h_lede'].format(account=acc) if name else w['h_lede_anon'].format()
        facts, note, warn = w['h_facts'], w['h_warn'], True
    else:
        lede = w['h_v_lede'].format(account=acc) if name else w['h_v_lede_anon'].format()
        facts, note, warn = w['h_v_facts'], w['h_v_note'], False
    if lede.strip():
        rows.append('<p style="margin:0 0 18px;font-size:15px;line-height:1.55;color:#374151">'
                    '%s</p>' % lede)
    spaced = ' '.join(code[i:i + 3] for i in range(0, len(code), 3)) if len(code) == 6 else code
    rows.append('<table role="presentation" width="100%%" cellspacing="0" cellpadding="0" '
                'border="0" style="margin:0 0 10px"><tr><td align="center">'
                '<table role="presentation" cellspacing="0" cellpadding="0" border="0"><tr>'
                '<td align="center" bgcolor="#f3f4f6" style="padding:16px 30px;background:#f3f4f6;'
                'border:1px solid #e5e7eb;border-radius:12px;font-family:Consolas,Menlo,'
                '\'Courier New\',monospace;font-size:34px;font-weight:700;letter-spacing:6px;'
                'color:#111827;white-space:nowrap">%s</td></tr></table></td></tr></table>' % h(spaced))
    if facts.strip():
        rows.append('<p style="margin:0 0 22px;font-size:13.5px;line-height:1.5;color:#6b7280;'
                    'text-align:center;%s">%s</p>' % (font, facts.format(minutes=minutes)))
    else:
        rows.append('<div style="height:12px;line-height:12px;font-size:1px">&nbsp;</div>')
    note = note.format()
    if not note.strip():
        pass
    elif warn:
        rows.append('<table role="presentation" width="100%%" cellspacing="0" cellpadding="0" '
                    'border="0"><tr><td bgcolor="#fff7ed" style="padding:12px 16px;'
                    'background:#fff7ed;border-left:4px solid #f59e0b;font-size:13px;'
                    'line-height:1.5;color:#7c2d12;%s">%s</td></tr></table>' % (font, note))
    else:
        rows.append('<table role="presentation" width="100%%" cellspacing="0" cellpadding="0" '
                    'border="0"><tr><td bgcolor="#eff6ff" style="padding:12px 16px;'
                    'background:#eff6ff;border-left:4px solid #2563eb;font-size:13px;'
                    'line-height:1.5;color:#1e3a8a;%s">%s</td></tr></table>' % (font, note))
    subject = (w['mail_subject'] if purpose == 'signin' else w['verify_subject']).format(
        code=code, site=site, minutes=minutes)
    title = (w['h_title'] if purpose == 'signin' else w['h_v_title']).format(site=site)
    foot = (w['h_foot'] if purpose == 'signin' else w['h_v_foot']).format(site=h(site))
    return ('<!doctype html><html lang="%s" xmlns:v="urn:schemas-microsoft-com:vml" '
            'xmlns:o="urn:schemas-microsoft-com:office:office"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1"><title>%s</title>'
            '<!--[if mso]><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch>'
            '</o:OfficeDocumentSettings></xml><![endif]--></head>'
            '<body style="margin:0;padding:0;background:#f3f4f6;%s">'
            '<table role="presentation" width="100%%" cellspacing="0" cellpadding="0" '
            'border="0" bgcolor="#f3f4f6" style="background:#f3f4f6"><tr><td align="center" '
            'style="padding:28px 12px">'
            '<table role="presentation" width="560" cellspacing="0" cellpadding="0" border="0" '
            'bgcolor="#ffffff" style="max-width:560px;width:100%%;background:#ffffff;'
            'border-radius:14px;overflow:hidden;border:1px solid #e5e7eb">'
            '<tr><td bgcolor="#1e3a8a" style="background:#1e3a8a;padding:20px 28px;'
            'color:#ffffff;%s">'
            '<p style="margin:0;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;'
            'color:#c7d2fe">%s</p><p style="margin:4px 0 0;font-size:20px;font-weight:700;'
            'color:#ffffff">%s</p></td></tr>'
            '<tr><td style="padding:26px 28px;%s">%s</td></tr>'
            '<tr><td style="padding:14px 28px 22px;font-size:12px;color:#9ca3af;%s;'
            'border-top:1px solid #f3f4f6">%s</td></tr></table></td></tr></table></body></html>'
            % (lang, h(subject), font, font, h(issuer), h(title), font, ''.join(rows),
               font, foot))


def code_message(kind, to, code, purpose='signin', lang=None, name='', display='', fmt=None,
                 w=None):
    """The mail or the SMS text of a code. `w`: the words to use instead of
    those saved - the message texts editor's test (1.0.103)."""
    if kind == 'sms':
        return code_words('sms' if purpose == 'signin' else 'sms_verify', lang=lang, w=w,
                          code=code)
    site = str(CONFIG.get('site_name') or socket.gethostname())
    msg = EmailMessage()
    msg['Subject'] = code_words('mail_subject' if purpose == 'signin' else 'verify_subject',
                                lang=lang, w=w, code=code)
    sender = str(CONFIG.get('mail_from') or '').strip()
    if not sender:
        raise MailError('no sender address is set - Settings → Mail → From (address)')
    msg['From'] = formataddr((str(CONFIG.get('mail_from_name') or site), sender))
    msg['To'] = to
    if CONFIG.get('mail_reply_to'):
        msg['Reply-To'] = str(CONFIG.get('mail_reply_to'))
    msg['Date'] = formatdate(localtime=True)
    msg['Message-ID'] = make_msgid(domain=sender.rsplit('@', 1)[-1] or None)
    msg['Auto-Submitted'] = 'auto-generated'
    msg.set_content(code_words('mail_body' if purpose == 'signin' else 'verify_body', lang=lang,
                               w=w, code=code))
    if (fmt or ('text' if CONFIG.get('code_mail_fmt') == 'text' else 'html')) != 'text':
        msg.add_alternative(code_mail_html(code, purpose, lang, name, display, w=w),
                            subtype='html')
    return msg


def code_send(store, kind, to, code, purpose='signin', name='', lang=None, fmt=None):
    """A code sent now; what the server said, or raises MailError/SmsError.
    In the token's own language and mail format unless given (1.0.82)."""
    tok = None
    if name:
        try:
            tok = store.token(name)
        except Exception:                               # noqa: BLE001
            tok = None
    lang = lang if lang in CODE_TEXTS else (token_lang(tok) if tok else None)
    if kind == 'mail':
        display = (tok or {}).get('display') or ''
        msg = code_message('mail', to, code, purpose, lang=lang, name=name, display=display,
                           fmt=fmt or (token_mail_fmt(tok) if tok else None))
        # Through the outgoing mail (1.0.95): greylisted, it is tried again
        # while the code is good - and the person gets it a minute later
        # rather than never.
        try:
            steps = mail_deliver(store, msg, [to], kind={'signin': 'code', 'verify': 'verify'}
                                 .get(purpose, 'test'), name=name, purpose=purpose,
                                 expires=time.time() + int(CONFIG.get('code_ttl_s') or 300))
        except MailError as e:
            if e.queued == 'waiting':
                return 'not taken yet (%s) - it waits in the outgoing mail and is tried again' % e
            raise
        last = [s for s in steps if s.get('ok')]
        return (last[-1].get('said') or 'sent') if last else 'sent'
    if kind == 'sms':
        return sms_send(to, code_message('sms', to, code, purpose, lang=lang))
    raise ValueError('%s tokens get no codes sent' % kind)


def code_send_later(store, kind, to, code, name, rid=''):
    """Sent by a thread of its own: the VPN gets its Access-Challenge at once
    rather than after a slow mail server."""
    def go():
        try:
            said = code_send(store, kind, to, code, name=name)
            store.otp_add({'ts': time.time(), 'name': name, 'ok': 1,
                           'said': 'A code was sent by %s to %s' % (
                               'mail' if kind == 'mail' else 'SMS', dest_masked(kind, to)),
                           'how': 'send-' + kind, 'src': '', 'rid': str(rid)[:120],
                           'step_off': None})
            if debugging('radius'):
                log('a code for %s went by %s: %s' % (name, kind, said), 'debug')
        except Exception as e:                          # noqa: BLE001
            log_sparing('code-send:%s' % kind, 'a code for %s could not be sent by %s: %s'
                        % (name, kind, e), 'warn', every=60)
            try:
                store.add_event('mail' if kind == 'mail' else 'radius',
                                'the code for %s could not be sent by %s to %s: %s'
                                % (name, 'mail' if kind == 'mail' else 'SMS',
                                   dest_masked(kind, to), str(e)[:300]), 'bad', who=name)
                store.otp_add({'ts': time.time(), 'name': name, 'ok': 0,
                               'said': 'The code could not be sent: %s' % str(e)[:200],
                               'how': 'send-' + kind, 'src': '', 'rid': str(rid)[:120],
                               'step_off': None})
            except Exception:                           # noqa: BLE001
                pass
    threading.Thread(target=go, name='code-send', daemon=True).start()


# ---- the challenges ------------------------------------------------------------------
def chal_key(state):
    return 'chal:' + hashlib.sha256(bytes(state)).hexdigest()[:40]


def chal_new(store, data):
    """A challenge kept; returns the State the VPN sends back."""
    state = CHAL_PREFIX + secrets.token_bytes(24)
    data = dict(data, exp=time.time() + int(CONFIG.get('code_ttl_s') or 300), tries=0,
                made=time.time(), node=node_name())
    store.set_meta(chal_key(state), json.dumps(data))
    return state


def chal_get(store, state):
    k = chal_key(state)
    raw = store.get_meta(k)
    if not raw:
        return None, None
    try:
        got = json.loads(raw)
    except ValueError:
        return None, None
    return got, raw


def chal_put(store, state, raw_was, data):
    """Written only if nobody wrote it meanwhile; whether it was."""
    return bool(store.db.run('UPDATE meta SET v = ? WHERE k = ? AND v = ?',
                             (json.dumps(data), chal_key(state), raw_was)))


def chal_take(store, state, raw_was):
    """Used up: of two nodes taking the same answer at once, only one wins."""
    return bool(store.db.run('DELETE FROM meta WHERE k = ? AND v = ?', (chal_key(state), raw_was)))


def chal_tidy(store):
    """Challenges past their time, and the counts of sent codes."""
    t = time.time()
    for r in store.db.rows("SELECT k, v FROM meta WHERE k LIKE 'chal:%' OR k LIKE 'codesent:%'"):
        try:
            v = json.loads(r['v'] or 'null')
        except ValueError:
            v = None
        if r['k'].startswith('chal:'):
            gone = not isinstance(v, dict) or float(v.get('exp') or 0) < t - 60
        else:
            span = 60 * int(CONFIG.get('code_send_window_min') or 15)
            gone = not isinstance(v, list) or not any(t - float(x) < span for x in v)
        if gone:
            store.db.run('DELETE FROM meta WHERE k = ? AND v = ?', (r['k'], r['v']))


# ---------------------------------------------------------------------------
# Deciding: one Access-Request, step by step
# ---------------------------------------------------------------------------
# The order (1.0.33): the realm and whether this client may use it, the
# directory - is the account there, in use, in a group that lets in - and
# its password, and the code last. Somebody who does not know the password
# can then neither guess codes nor lock a token out by guessing them, and a
# code is only used up by a request that would otherwise be let in. (Until
# 1.0.32 the code came first, as the old token server had it.)
#
# Every step is written down - what was asked, what came back, how long it
# took - and kept with the request, so that "why was I refused" is answered
# by opening one row rather than by reading a debug log.

class Decision(object):
    def __init__(self):
        self.steps = []
        self.began = time.time()
        self.result = 'reject'
        self.reason = ''
        self.otp = ''
        self.reply = []                 # [(Name, value)]
        self.realm = ''
        self.user = ''
        self.token_name = ''
        self.display = ''
        self.state = None               # an Access-Challenge's State (1.0.76)
        self.message = ''               # and the words of its second window

    def step(self, what, ok, said='', since=None):
        one = {'what': what, 'ok': ok, 'said': str(said or '')[:600]}
        if since is not None:
            one['ms'] = int((time.time() - since) * 1000)
        self.steps.append(one)
        if debugging('radius'):
            log('radius %s: %s%s' % (self.user or '?', what,
                                     (' - ' + str(said)) if said else ''), 'debug')
        return one

    def refuse(self, reason):
        self.result = 'reject'
        self.reason = reason
        return self


def client_realm_list(client):
    """The realms a client may use, by name, lower case; [] for any."""
    raw = (client or {}).get('realms') or ''
    if isinstance(raw, (list, tuple)):
        got = raw
    else:
        got = re.split(r'[,;\n]+', str(raw))
    return [str(x).strip().lower() for x in got if str(x).strip()]


class Authenticator(object):
    """What the RADIUS server asks: may this person in, and with what."""

    def __init__(self, store, tokens, dirs):
        self.store = store
        self.tokens = tokens
        self.dirs = dirs                 # name -> Directory

    def directory(self, name):
        return self.dirs.get(str(name or '').lower())

    @staticmethod
    def full_name(user, client_realm):
        """The name as it will be looked up: DOMAIN\\name as name, and the
        client's own realm added to a name that has none - what FreeRADIUS's
        hints file did, NAS by NAS. A dot at the end of the realm is dropped
        (corp.cz. is corp.cz) and a name with nothing before its @ is no
        name at all (1.0.33)."""
        said = str(user or '').strip()
        if said.count('@') > 1:
            # novak@foo@x.cz (1.0.101): the realm by the last @, the account
            # by the first - and a token under the rest, a second one for the
            # same person. Not a name.
            return ''
        if '\\' in said and '@' in said:
            # DOMAIN\\name@realm (1.0.101): the directory finds name, the
            # token is looked for under the whole of it - a second token for
            # the same person, made by whoever has the password before its
            # owner enrols. Not a name.
            return ''
        if '\\' in said:
            said = said.split('\\', 1)[1]
        if '@' in said:
            who, _, where = said.rpartition('@')
            where = where.strip().rstrip('.')
            who = who.strip()
            if not who or not where:
                return ''
            return '%s@%s' % (who, where)
        if not said:
            return ''
        if client_realm:
            said = '%s@%s' % (said, str(client_realm).lstrip('@'))
        return said

    @staticmethod
    def token_name(user, realm):
        if realm and realm.get('token_name') == 'bare':
            # Before the last @, as the realm is found by it (1.0.101).
            return norm_name(user.rpartition('@')[0] or user)
        return norm_name(user)

    def decide(self, user, password, client_realm='', src='', rid='', chap=False,
               how='radius', client=None):
        d = Decision()
        d.user = self.full_name(user, client_realm or CONFIG.get('default_realm') or '')
        if not d.user:
            d.step('a name', False, 'the request carries no User-Name, or only a realm')
            return d.refuse('the request carries no User-Name')
        if d.user != str(user):
            d.step('the name is read as %s' % d.user, True,
                   'the client adds @%s to a name without a realm' % client_realm
                   if client_realm and '@' not in str(user) else '')
        realm = self.store.realm_for(d.user)
        if not realm:
            d.step('a realm for %s' % d.user, False, 'no realm takes this name')
            return d.refuse('no realm takes the name %s' % d.user)
        d.realm = realm['name']
        d.step('the realm is %s' % realm['name'], True, {
            'otp': 'the password is the code from the phone',
            'password_otp': 'the password is the directory password followed by the code',
            'password': 'the password is the directory password alone',
            'challenge': 'the directory password, then the code in a second window'}[
                realm['auth_mode']])
        # Whether this client may use that realm at all (1.0.33): without it
        # the name typed chose the realm, and with it how strictly the
        # person is checked - user@wifi through the VPN, password alone.
        allowed = client_realm_list(client)
        if allowed and realm['name'].lower() not in allowed:
            d.step('the client may use the realm %s' % realm['name'], False,
                   'the client %s may use only: %s' % ((client or {}).get('name') or '?',
                                                       ', '.join(allowed)))
            return d.refuse('the client %s may not use the realm %s'
                            % ((client or {}).get('name') or '?', realm['name']))
        if chap or password is None:
            d.step('a password', False, 'CHAP or no User-Password: a one-time code can only '
                   'travel as PAP')
            return d.refuse('the request carries no User-Password (PAP)')
        if password and any(ord(c) < 32 or c == '\ufffd' for c in password):
            d.step('the password reads as text', False, 'what came is not text - is the shared '
                   'secret the same on both sides?')
            return d.refuse('the password does not decode: the shared secret is probably '
                            'not the same as on the client')
        if not password:
            d.step('a password', False, 'it is empty')
            return d.refuse('the password is empty')
        d.token_name = self.token_name(d.user, realm)
        mode = realm['auth_mode']
        # ---- a code in a second window (1.0.76) ---------------------------
        # A token that gets its codes by mail or SMS always signs in so - the
        # password is the directory's and the code is asked for after it,
        # whatever the realm says of a code from the phone; a realm in the
        # "challenge" mode asks so of the app's tokens too. Everybody else
        # signs in exactly as before.
        challenge = None
        tok = self.store.token(d.token_name) if mode != 'password' else None
        kind = token_kind(tok) if tok else None
        if mode == 'challenge':
            if not tok:
                d.step('a token for %s' % d.token_name, False, SAY_NONE)
                d.otp = SAY_NONE
                return d.refuse('Denied by the token server: ' + SAY_NONE)
            challenge = kind
        elif tok and kind in ('mail', 'sms'):
            challenge = kind
        if challenge:
            if tok.get('state') == 'pending':
                d.step('the token of %s' % d.token_name, False, SAY_PENDING)
                d.otp = SAY_PENDING
                return d.refuse('Denied by the token server: ' + SAY_PENDING)
            if challenge in ('mail', 'sms') and challenge not in code_channels():
                why = ('sending mail is not set up' if challenge == 'mail'
                       else 'sending SMS is not set up')
                d.step('a code by %s' % ('mail' if challenge == 'mail' else 'SMS'), False, why)
                return d.refuse('Denied by the token server: the code cannot be sent - ' + why)
            d.step('the code comes in a second window', True,
                   'the token gets %s; the password is the directory password'
                   % CODE_KIND_WORDS[challenge])
        # ---- where the password ends and the code begins -------------------
        code, ad_password = None, None
        guessed = False
        if challenge:
            ad_password = password
        elif mode == 'otp':
            code = password
        elif mode == 'password_otp':
            tok = self.store.token(d.token_name)
            digits = int((tok or {}).get('digits') or CONFIG.get('totp_digits') or 6)
            splits = []
            if len(password) > digits:
                splits.append((password[-digits:], password[:-digits]))
            sd = int(CONFIG.get('scratch_digits') or 8)
            if len(password) > sd and sd != digits:
                splits.append((password[-sd:], password[:-sd]))
            if not splits:
                d.step('the code', False, 'nothing after the password looks like a code')
                d.otp = SAY_BAD
                return d.refuse('Denied by the token server: ' + SAY_BAD)
            code, ad_password = splits[0]
            if len(splits) > 1:
                guessed = splits[1][1]
                # Which one: the code that is right now, found with a dry
                # check that counts nothing and writes nothing - so one
                # password costs the directory one try, not two.
                for c, rest in splits:
                    ok, _said, _f = self.tokens.check(d.token_name, c, how=how, src=src,
                                                      rid=rid, dry=True, quiet=True)
                    if ok:
                        code, ad_password = c, rest
                        guessed = False
                        break
        # ---- the directory -----------------------------------------------
        entry = None
        lookup = realm.get('lookup') or ''
        if lookup not in ('upn', 'sam'):
            # No way chosen: by the form of the name. A realm with a directory
            # always asks it - its groups and a switched-off account are never
            # skipped because nobody picked how to look a name up.
            lookup = 'upn' if '@' in d.user else 'sam'
        if (realm.get('groups') or []) and not realm.get('directory'):
            d.step('the groups of %s' % d.user, False, 'the realm names groups and no directory '
                   'to ask them of')
            return d.refuse('account does not pass LDAP group filter(s): the realm %s has no '
                            'directory' % realm['name'])
        if realm.get('directory'):
            ad = self.directory(realm['directory'])
            if not ad:
                d.step('the directory %s' % realm['directory'], False, 'it is not set up')
                return d.refuse('the directory %s is not set up' % realm['directory'])
            t = time.time()
            try:
                entry = ad.find_user(d.user, lookup)
            except LdapError as e:
                d.step('look %s up in %s' % (d.user, ad.name), False, str(e), t)
                return d.refuse('LDAP server(s) have gone away' if isinstance(
                    e, LdapUnreachable) else 'the directory could not be asked: %s' % e)
            if not entry:
                d.step('look %s up in %s' % (d.user, ad.name), False,
                       'by %s: there is no such account' % {'upn': 'userPrincipalName',
                                                           'sam': 'sAMAccountName'}.get(lookup,
                                                                                         lookup),
                       t)
                return d.refuse('account does not pass LDAP user filter: %s is not in %s'
                                % (d.user, ad.name))
            d.display = entry.get('display') or ''
            if entry.get('many'):
                # Two accounts answer to the name (1.0.57): which one would
                # be checked is chance, so neither is.
                d.step('look %s up in %s' % (d.user, ad.name), False,
                       'more than one account answers to the name', t)
                return d.refuse('more than one account in %s answers to %s'
                                % (ad.name, d.user))
            d.step('found %s' % entry['dn'], True, entry.get('display') or '', t)
            if realm.get('check_disabled', 1):
                why = entry_unusable(entry)
                if why:
                    d.step('the account is in use', False, why)
                    if entry.get('disabled'):
                        return d.refuse('the account is disabled in the directory')
                    if entry.get('expires') and entry['expires'] < time.time():
                        return d.refuse('the account has expired in the directory')
                    return d.refuse('the account may not sign in: %s' % why)
            if mode in ('password', 'password_otp') or challenge:
                pw = password if mode == 'password' else ad_password
                if code is not None or challenge:
                    # A token locked out or paused is refused before its
                    # password is tried in the directory (1.0.57).
                    stop = self.tokens.blocked(d.token_name)
                    if stop:
                        d.step('the code for the token %s' % d.token_name, False, stop)
                        return d.refuse('Denied by the token server: ' + stop)
                t = time.time()
                try:
                    ad.password_ok(entry, pw)
                    d.step('the directory password', True, '', t)
                except LdapError as e:
                    d.step('the directory password', False, str(e), t)
                    if guessed and not isinstance(e, LdapUnreachable) and \
                            int((tok or {}).get('scratch_left') or 0) > 0:
                        # No split gave a right code, and the password before
                        # a code from the phone was refused (1.0.101). If the
                        # password was right, what followed it was a wrong
                        # recovery code - nothing counted that before, past
                        # the pause and the lockout. The directory is not asked
                        # twice to find out (a typo would count twice there);
                        # each such request is counted towards the token's
                        # recovery codes instead: past a day's few, they are
                        # not taken for a while. Codes from the app go on.
                        scratch_guard_note(self.store, d.token_name)
                    return d.refuse('the directory refused the password: %s' % e
                                    if not isinstance(e, LdapUnreachable)
                                    else 'LDAP server(s) have gone away')
            wanted = realm.get('groups') or []
            if wanted:
                t = time.time()
                try:
                    have = ad.groups_of(entry, bool(realm.get('nested', 1)))
                except LdapError as e:
                    d.step('the groups of %s' % d.user, False, str(e), t)
                    return d.refuse('LDAP server(s) have gone away')
                hit = group_matches(wanted, have, ad)
                if not hit:
                    names = ', '.join(cn_of(w.get('group') or '') or w.get('group') or ''
                                      for w in wanted[:6]) + (' …' if len(wanted) > 6 else '')
                    d.step('a member of one of %d group(s)' % len(wanted), False,
                           'a member of %d group(s)%s, none of them one of: %s'
                           % (len(have), ' (nested counted)' if realm.get('nested', 1) else '',
                              names), t)
                    return d.refuse('account does not pass LDAP group filter(s): %s is in '
                                    'none of %s' % (d.user, names))
                d.step('a member of %s' % hit['group'], True, '', t)
                try:
                    d.reply.extend(reply_lines(hit.get('reply') or ''))
                except RadiusError as e:
                    # Never an Accept without what limits it (1.0.57).
                    d.step('the answer of the group %s' % hit['group'], False, str(e))
                    return d.refuse('the answer for the group cannot be built: %s' % e)
        elif mode in ('password', 'password_otp') or challenge:
            d.step('the directory password', False, 'the realm has no directory to ask')
            return d.refuse('the realm %s has no directory' % realm['name'])
        if challenge:
            try:
                reply = reply_lines(realm.get('reply') or '') + d.reply
            except RadiusError as e:
                d.step('the answer', False, str(e))
                return d.refuse('the answer of the realm cannot be built: %s' % e)
            return self.challenge_start(d, realm, tok, challenge, reply, client, src, rid)
        # ---- the code, last ----------------------------------------------
        if code is not None:
            t = time.time()
            ok, said, facts = self.tokens.check(d.token_name, code, how=how, src=src, rid=rid)
            d.otp = said
            d.step('the code for the token %s' % d.token_name, ok, said, t)
            if not ok:
                return d.refuse('Denied by the token server: ' + said)
        try:
            d.reply = reply_lines(realm.get('reply') or '') + d.reply
        except RadiusError as e:
            d.step('the answer', False, str(e))
            return d.refuse('the answer of the realm cannot be built: %s' % e)
        d.result = 'accept'
        d.step('let in', True, ', '.join('%s = %s' % p for p in d.reply))
        return d


    # ---- the second window (1.0.76) ----------------------------------------------
    def challenge_start(self, d, realm, tok, kind, reply, client, src, rid):
        """The password was right: a code sent (mail, SMS) or asked for (the
        app), and an Access-Challenge to say so."""
        name = d.token_name
        data = {'name': name, 'user': d.user, 'realm': realm['name'],
                'client': (client or {}).get('id'), 'kind': kind,
                'reply': [list(p) for p in reply], 'src': src}
        if kind in ('mail', 'sms'):
            dest = str(tok.get('dest') or '')
            if not dest:
                d.step('where the code goes', False, 'the token has no address or number')
                return d.refuse('Denied by the token server: the token has nowhere to send '
                                'a code')
            if not code_send_allowed(self.store, name):
                said = ('%d codes were sent in %d min already'
                        % (int(CONFIG.get('code_send_max') or 5),
                           int(CONFIG.get('code_send_window_min') or 15)))
                d.step('a code sent', False, said)
                d.otp = 'Too many codes sent'
                return d.refuse('Denied by the token server: too many codes sent - ' + said)
            code = code_new()
            data['code'] = code_hash(name, code)
            data['dest'] = dest          # the answer checks the token still sends there (1.0.94)
            d.state = chal_new(self.store, data)
            code_send_later(self.store, kind, dest, code, name, rid)
            d.message = code_words('ask_' + kind, lang=token_lang(tok), dest=dest_masked(kind, dest))
            d.step('a code sent by %s to %s' % ('mail' if kind == 'mail' else 'SMS',
                                                 dest_masked(kind, dest)), True,
                   'good for %d s' % int(CONFIG.get('code_ttl_s') or 300))
            d.otp = 'Code sent by %s' % ('mail' if kind == 'mail' else 'SMS')
        else:
            d.state = chal_new(self.store, data)
            d.message = code_words('ask_totp', lang=token_lang(tok))
            d.step('the code from the app asked for', True, '')
            d.otp = 'Code asked for'
        d.result = 'challenge'
        d.reason = 'the code is asked for in a second window'
        return d

    def answer(self, user, password, state, client_realm='', src='', rid='', chap=False,
               how='radius', client=None):
        """The second Access-Request: the code typed into the second window,
        with the State of the challenge."""
        d = Decision()
        d.user = self.full_name(user, client_realm or CONFIG.get('default_realm') or '')
        chal, raw = chal_get(self.store, state)
        if not chal:
            d.step('the question this answers', False, 'there is none - it was answered, or '
                   'ran out, or was asked by another server')
            return d.refuse('the code was asked for too long ago: sign in again')
        d.realm = chal.get('realm') or ''
        d.token_name = name = chal.get('name') or ''
        kind = chal.get('kind') or 'totp'
        if float(chal.get('exp') or 0) < time.time():
            chal_take(self.store, state, raw)
            d.step('the question this answers', False, 'it ran out %s' % stamp(chal.get('exp')))
            d.otp = 'The code ran out'
            return d.refuse('Denied by the token server: the code ran out - sign in again')
        if norm_name(chal.get('user') or '') != norm_name(d.user) or \
                chal.get('client') != (client or {}).get('id'):
            d.step('the question this answers', False, 'it was asked of another name or through '
                   'another client')
            return d.refuse('the answer does not belong to the question it names')
        d.step('the answer to the code asked for: %s' % CODE_KIND_WORDS.get(kind, kind), True,
               'asked %s' % stamp(chal.get('made')))
        if chap or not password:
            d.step('the code', False, 'nothing came, or not as PAP')
            return d.refuse('the request carries no code (PAP)')
        code = str(password).strip()
        t = time.time()
        # A try is taken before the code is looked at (1.0.101): written to
        # the question with a conditional update, so of answers that came
        # at the same moment only as many as there are tries are compared -
        # not all of them, each having read "0 tries so far".
        limit = int(CONFIG.get('code_tries') or 3)
        for _round in range(64):
            if int(chal.get('tries') or 0) >= limit:
                chal_take(self.store, state, raw)
                d.step('the code for the token %s' % name, False, 'no tries left', t)
                d.otp = SAY_RATE
                return d.refuse('Denied by the token server: no tries left - sign in again')
            nxt = dict(chal)
            nxt['tries'] = int(chal.get('tries') or 0) + 1
            if chal_put(self.store, state, raw, nxt):
                chal, raw = nxt, json.dumps(nxt)
                break
            chal, raw = chal_get(self.store, state)
            if not chal:
                d.step('the question this answers', False, 'answered meanwhile')
                return d.refuse('the code was asked for too long ago: sign in again')
        else:
            return d.refuse('Denied by the token server: too many answers at once')
        if kind in ('mail', 'sms'):
            stop = self.tokens.blocked(name)
            # The token as it is now (1.0.94): taken away, made anew for the
            # app, or sending elsewhere since - the code sent is nothing then.
            now_tok = self.store.token(name)
            if not stop and (not now_tok or token_kind(now_tok) != kind or (
                    chal.get('dest') and str(now_tok.get('dest') or '') != chal.get('dest'))):
                stop = 'the token changed since the code was sent - sign in again'
            if stop:
                chal_take(self.store, state, raw)
                d.step('the code for the token %s' % name, False, stop, t)
                d.otp = stop
                return d.refuse('Denied by the token server: ' + stop)
            if re.fullmatch(r'[0-9]{4,10}', code, re.ASCII) and \
                    hmac.compare_digest(code_hash(name, code), str(chal.get('code') or '')):
                ok, said = True, 'Code sent by %s accepted' % ('mail' if kind == 'mail' else 'SMS')
                if chal_take(self.store, state, raw) and once_take(
                        self.store, 'chal', name, hashlib.sha256(bytes(state)).hexdigest()):
                    self.tokens.used_sent(name, kind)
                    self.tokens._said(name, True, said, how, src, rid)
                else:
                    ok, said = False, SAY_REUSED
            else:
                # A recovery code - or a wrong code, counted as one from the
                # phone is, towards the lockout.
                ok, said, _f = self.tokens.check(name, code, how=how, src=src, rid=rid)
                if ok and not chal_take(self.store, state, raw):
                    ok, said = False, SAY_REUSED
        else:
            ok, said, _f = self.tokens.check(name, code, how=how, src=src, rid=rid)
            if ok and not chal_take(self.store, state, raw):
                ok, said = False, SAY_REUSED
        d.otp = said
        d.step('the code for the token %s' % name, ok, said, t)
        if ok:
            d.reply = [tuple(p) for p in chal.get('reply') or []]
            d.result = 'accept'
            d.step('let in', True, ', '.join('%s = %s' % p for p in d.reply))
            return d
        if said == SAY_REUSED or chal['tries'] >= limit or self.tokens.blocked(name):
            chal_take(self.store, state, raw)
            return d.refuse('Denied by the token server: ' + said)
        d.state = state
        d.message = code_words('again', lang=token_lang(self.store.token(name)))
        d.result = 'challenge'
        d.reason = 'the code was not right: asked again (%d of %d)' % (
            chal['tries'], limit)
        return d


# ---------------------------------------------------------------------------
# The RADIUS server
# ---------------------------------------------------------------------------
class SentReply(bytes):
    """An answer, and whether it has gone out already."""
    sent = False
    late = False


class RadiusServer(object):
    """Two UDP sockets - authentication and accounting - read by a thread
    each and answered by a pool of workers."""

    def __init__(self, daemon):
        self.d = daemon
        self.socks = {}
        self.jobs = queue.Queue(maxsize=5000)
        # duplicate key -> (time, reply or None), oldest first, never more
        # than SEEN_MAX: a flood fills it to the brim and no further (1.0.33).
        self.seen = collections.OrderedDict()
        self.seen_lock = threading.Lock()
        self.unknown_said = {}
        self.unknown_lock = threading.Lock()
        # What is not written down one by one - malformed packets, and more
        # than a few unknown addresses a minute - is counted and summed up
        # once a minute instead (1.0.33): a flood of junk was a row each.
        self.quiet = collections.Counter()
        self.quiet_at = time.time()
        self.drops_this_minute = 0
        # Clients that have sent a right Message-Authenticator (1.0.33).
        self.ma_seen = set()
        self.ma_asked = {}
        # Refusals waiting out radius_reject_delay_ms (1.0.36).
        self.late = []
        self.late_lock = threading.Lock()
        self.late_wake = threading.Event()
        self.late_thread = None
        self.workers = []
        self.readers = []
        self.stop_flag = False
        self.counts = collections.Counter()
        self.bound = []
        self.trouble = ''

    # ---- the sockets -------------------------------------------------------------
    def want(self):
        bind = str(CONFIG.get('radius_bind') or '0.0.0.0')
        out = [('auth', bind, int(CONFIG.get('radius_auth_port') or 1812))]
        if int(CONFIG.get('radius_acct_port') or 0):
            out.append(('acct', bind, int(CONFIG.get('radius_acct_port'))))
        return out

    def start(self):
        self.stop_flag = False
        self.open_sockets()
        for i in range(int(CONFIG.get('radius_workers') or 16)):
            t = threading.Thread(target=self.work, name='radius-%d' % i, daemon=True)
            t.start()
            self.workers.append(t)

    def open_sockets(self):
        want = self.want()
        if [(k, b, p) for k, (b, p, _s) in sorted(self.socks.items())] == sorted(want):
            return
        # Only what changed is closed and opened again (1.0.67): the auth port
        # changed closed the accounting socket too, and binding it again while
        # its reader was still inside recvfrom failed - accounting stopped.
        keep = {}
        wanted = {(k, b, p) for k, b, p in want}
        old_readers = []
        for kind, (b, p, sock) in list(self.socks.items()):
            if (kind, b, p) in wanted:
                keep[kind] = (b, p, sock)
                continue
            try:
                sock.close()
            except OSError:
                pass
            old_readers += [t for t in self.readers if t.name == 'radius-' + kind]
        self.socks = dict(keep)
        for t in old_readers:
            t.join(2.5)             # out of its recvfrom (1 s timeout) before the port is taken again
        self.readers = [t for t in self.readers if t.is_alive()]
        self.bound = ['%s:%d/%s' % (b, p, k) for k, (b, p, _s) in sorted(keep.items())]
        troubles = []
        for kind, bind, port in want:
            if kind in keep:
                continue
            fam = socket.AF_INET6 if ':' in bind else socket.AF_INET
            try:
                sock = socket.socket(fam, socket.SOCK_DGRAM)
            except OSError as e:
                # IPv6 switched off on the machine (1.0.94): said, as a port in
                # use is - it killed the daemon at start, round and round.
                troubles.append('%s:%d (%s) could not be listened on: %s' % (bind, port, kind, e))
                continue
            # No SO_REUSEADDR: on UDP it lets a second process bind the very same
            # port and take half the packets. A port in use has to say so.
            if fam == socket.AF_INET6:
                try:
                    sock.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 0)
                except OSError:
                    pass
            err = None
            for _try in range(6):
                try:
                    sock.bind((bind, port))
                    err = None
                    break
                except OSError as e:
                    err = e
                    time.sleep(0.5)
            if err is not None:
                troubles.append('%s:%d (%s) could not be listened on: %s' % (bind, port, kind, err))
                sock.close()
                continue
            sock.settimeout(1.0)
            self.socks[kind] = (bind, port, sock)
            self.bound.append('%s:%d/%s' % (bind, port, kind))
            t = threading.Thread(target=self.read, args=(kind, sock), name='radius-' + kind,
                                 daemon=True)
            t.start()
            self.readers.append(t)
        self.trouble = '; '.join(troubles)
        if troubles:
            self.d.store.add_event('radius', self.trouble, 'bad')
        else:
            log('RADIUS listening on %s' % ', '.join(self.bound))

    def stop(self):
        self.stop_flag = True
        for _b, _p, sock in self.socks.values():
            try:
                sock.close()
            except OSError:
                pass

    def read(self, kind, sock):
        while not self.stop_flag:
            try:
                data, peer = sock.recvfrom(4096)
            except socket.timeout:
                continue
            except OSError:
                if self.socks.get(kind, (None, None, None))[2] is not sock:
                    return
                time.sleep(0.2)
                continue
            if self.socks.get(kind, (None, None, None))[2] is not sock:
                return
            try:
                self.jobs.put_nowait((kind, sock, data, peer, time.time()))
            except queue.Full:
                self.counts['overflow'] += 1

    def work(self):
        while not self.stop_flag:
            try:
                kind, sock, data, peer, arrived = self.jobs.get(timeout=1.0)
            except queue.Empty:
                continue
            # Older than any NAS waits (1.0.57): after a stall the queue held
            # minutes of requests whose NAS had long given up, each with its
            # directory binds and its code used up, ahead of the new ones.
            if time.time() - arrived > int(CONFIG.get('radius_stale_s') or 15):
                self.counts['stale'] += 1
                with self.unknown_lock:
                    self.quiet['too old to answer'] += 1
                continue
            try:
                self.handle(kind, sock, data, peer, arrived)
            except Exception as e:
                # Sparingly (1.0.59): a packet that breaks it once breaks it
                # every time it is sent, by anybody using the NAS's address.
                log_sparing('radius-broke:%s:%s' % (type(e).__name__, str(e)[:60]),
                            'a RADIUS request from %s broke: %s\n%s'
                            % (peer[0], e, traceback.format_exc()), 'error', every=300)

    # ---- one packet -----------------------------------------------------------
    def handle(self, kind, sock, data, peer, arrived):
        ip, port = peer[0], peer[1]
        if ip.startswith('::ffff:'):
            ip = ip[7:]
        self.counts['packets'] += 1
        self.sum_up()
        # In maintenance nothing is answered (1.0.37): the VPN takes this
        # node for down and asks the other, as it would any node that is.
        if maintenance_now(self.d.store).get('on'):
            self.counts['maintenance'] += 1
            return
        client = self.d.store.client_for(ip)
        try:
            pkt = Packet.parse(data)
        except RadiusError as e:
            self.counts['malformed'] += 1
            # Only from a client is one written down, and then sparingly:
            # anybody can send junk to the port, from any address.
            if client:
                self.drop(ip, port, '', 'not a RADIUS packet: %s' % e, client=client, sparing=True)
            else:
                with self.unknown_lock:
                    self.quiet['malformed from %s' % ip if len(self.quiet) < 1000
                               else 'malformed, from other addresses'] += 1
            return
        if not client:
            self.counts['unknown'] += 1
            self.drop(ip, port, pkt.text(1), 'the address %s is not one of the clients' % ip,
                      pkt=pkt, unknown=True)
            return
        secret = (client.get('_secret') or '').encode('utf-8')
        if not secret:
            self.drop(ip, port, pkt.text(1), 'the secret of the client %s cannot be opened '
                      'on this machine' % client['name'], pkt=pkt, client=client)
            return
        # The whole packet in the key (1.0.57), as FreeRADIUS compares it: a
        # made-up packet with the same ident and authenticator from the NAS's
        # address can no longer stand in for the real one.
        key = (ip, port, pkt.ident, pkt.authenticator, kind, hashlib.sha256(data).digest()[:16])
        window = int(CONFIG.get('radius_dup_window_s') or 0)
        if window:
            with self.seen_lock:
                got = self.seen.get(key)
                if got and arrived - got[0] < window:
                    self.counts['repeated'] += 1
                    if got[1]:
                        try:
                            sock.sendto(got[1], peer)
                        except OSError:
                            pass
                    return
                self.seen[key] = (arrived, None)
                self.seen.move_to_end(key)
                # Old ones go from the front; past the limit the oldest go
                # whatever their age - never a rebuild of the whole table.
                cut = arrived - window
                while self.seen:
                    k0, v0 = next(iter(self.seen.items()))
                    if v0[0] >= cut and len(self.seen) <= self.SEEN_MAX:
                        break
                    self.seen.popitem(last=False)
        try:
            if kind == 'acct':
                reply = self.accounting(pkt, client, ip, port, secret, arrived)
            elif pkt.code == STATUS_SERVER:
                reply = self.status(pkt, client, ip, port, secret)
            elif pkt.code == ACCESS_REQUEST:
                remember = None
                if window:
                    def remember(b, key=key):
                        # The answer kept for a repeat the moment it is sent
                        # (1.0.101), not after it is written down: a repeat
                        # coming meanwhile got nothing.
                        with self.seen_lock:
                            if key in self.seen:
                                self.seen[key] = (arrived, b)
                reply = self.access(pkt, client, ip, port, secret, arrived, sock, peer, remember)
            else:
                # Not proven to come from the client: written down sparingly
                # (1.0.57) - anybody can send it from the NAS's address.
                self.drop(ip, port, pkt.text(1), 'a %s is not something this port answers'
                          % CODE_WORDS.get(pkt.code, 'code %d' % pkt.code), pkt=pkt,
                          client=client, sparing=True)
                reply = None
        except BaseException:
            # Nothing answered: a repeat of it is not swallowed as "repeated"
            # for the whole window (1.0.57).
            if window:
                with self.seen_lock:
                    self.seen.pop(key, None)
            raise
        if reply and not getattr(reply, 'sent', False):
            try:
                sock.sendto(reply, peer)
            except OSError as e:
                log('the answer to %s could not be sent: %s' % (ip, e), 'warn')
        if window:
            with self.seen_lock:
                # A refusal still waiting out its delay is not handed to a
                # repeat of the request either (1.0.36): it would have skipped
                # the wait.
                if reply is None and pkt.code == ACCESS_REQUEST:
                    # Left unanswered (no database, 1.0.59): the NAS's repeat
                    # is tried again, not swallowed as "repeated".
                    self.seen.pop(key, None)
                elif key in self.seen and not getattr(reply, 'late', False):
                    self.seen[key] = (arrived, bytes(reply) if reply else None)
        try:
            self.d.store.client_seen(client['id'])
        except Exception as e:                          # noqa: BLE001
            log_sparing('radius-client-seen', 'the client %s could not be marked as seen: %s'
                        % (client['name'], str(e).split('\n')[0][:200]), 'warn')

    SEEN_MAX = 20000

    def sum_up(self):
        """Once a minute, what was only counted, in one line."""
        t = time.time()
        if t - self.quiet_at < 60:
            return
        with self.unknown_lock:
            if t - self.quiet_at < 60:
                return
            said, self.quiet = self.quiet, collections.Counter()
            self.quiet_at = t
            self.drops_this_minute = 0
        if said:
            top = ', '.join('%s: %d' % kv for kv in said.most_common(8))
            try:
                self.d.store.add_event('radius', 'not answered and not written down one by one '
                                       'in the last minute: %d packet(s) - %s'
                                       % (sum(said.values()), top), 'warn')
            except Exception as e:                      # noqa: BLE001
                log('could not write the minute\'s summary: %s' % e, 'warn')

    def drop(self, ip, port, user, reason, pkt=None, client=None, unknown=False,
             sparing=False):
        """A packet that is not answered: written down - for an unknown
        address only once a minute, so a VPN pointed here before it was
        added does not fill the log, and never more than 30 a minute in
        all, so a flood from made-up addresses does not either (1.0.33)."""
        self.counts['dropped'] += 1
        if unknown or sparing:
            if unknown and not CONFIG.get('radius_unknown_log', 1):
                return
            with self.unknown_lock:
                t = time.time()
                last = self.unknown_said.get(ip, 0)
                if t - last < 60 or self.drops_this_minute >= 30:
                    # Bounded (1.0.57): a flood from made-up addresses made
                    # one key each until the minute was up.
                    self.quiet[(('unknown address %s' if unknown else 'dropped from %s') % ip)
                               if len(self.quiet) < 1000 else 'from other addresses'] += 1
                    return
                self.unknown_said[ip] = t
                self.drops_this_minute += 1
                if len(self.unknown_said) > 4000:
                    # Kept to the newest addresses, so a scan of the port
                    # cannot grow this table without end.
                    newest = sorted(self.unknown_said.items(), key=lambda kv: kv[1])[-2000:]
                    self.unknown_said = dict(newest)
        self.d.store.radius_add({
            'ts': time.time(), 'client': (client or {}).get('name') or '', 'nas_ip': ip,
            'src': '%s:%d' % (ip, port), 'packet': CODE_WORDS.get(pkt.code, '?') if pkt else '?',
            'username': str(user or '')[:190], 'realm': '', 'calling': '', 'called': '',
            'result': 'drop', 'reason': reason[:500], 'otp': '', 'rid': '', 'took_ms': 0,
            'attrs': json.dumps(pkt.words() if pkt else []), 'reply': '[]',
            'steps': json.dumps([{'what': 'answered', 'ok': False, 'said': reason}]),
            'device': '', 'tunnel': ''})
        if unknown:
            self.d.store.add_event('radius', 'a request from %s, which is not a client, was '
                                   'not answered' % ip, 'warn')

    def ma_check(self, pkt, client, secret, ip, port):
        """Whether the Message-Authenticator lets this one through."""
        got = pkt.message_authenticator_ok(secret)
        if got is False:
            self.drop(ip, port, pkt.text(1), 'the Message-Authenticator is wrong: the shared '
                      'secret is not the same as on the client', pkt=pkt, client=client,
                      sparing=True)
            return False
        if got is True:
            # Per address of the client (1.0.57): one device of a range that
            # sends it no longer made it required of all the others. Only an
            # Access-Request's makes it required (1.0.59): a Status-Server
            # always carries one, and a monitor asking that from the NAS's
            # address had every plain PAP request after it dropped.
            if pkt.code == ACCESS_REQUEST and (client['id'], ip) not in self.ma_seen:
                self.ma_seen.add((client['id'], ip))
                # Kept in the database too (1.0.101): a restart, or the other
                # node, no longer forgets that this NAS signs its requests.
                try:
                    # Under this node's name (1.0.101): one key written by
                    # both nodes at once stopped replication on the second.
                    self.d.store.set_meta('maseen:%s:%s:%s' % (node_name(), client['id'], ip),
                                          '1')
                except Exception:                       # noqa: BLE001
                    pass
            return True
        # None: there is none. A client that has sent one before must go on
        # sending one (1.0.33) - what is stripped off on the way, as
        # BlastRADIUS does, is refused.
        sticky = CONFIG.get('radius_ma_sticky', 1) and self.ma_known(client['id'], ip)
        # Proxy-State and no Message-Authenticator: the shape BlastRADIUS
        # needs (CVE-2024-3596), refused as FreeRADIUS's limit_proxy_state
        # does (1.0.57).
        if pkt.code == ACCESS_REQUEST and pkt.all(33):
            self.drop(ip, port, pkt.text(1), 'Proxy-State without a Message-Authenticator '
                      '(the shape of a BlastRADIUS forgery)', pkt=pkt, client=client,
                      sparing=True)
            return False
        if client.get('require_ma') or pkt.code == STATUS_SERVER or sticky:
            self.drop(ip, port, pkt.text(1), 'there is no Message-Authenticator, and this '
                      'client must send one%s' % (' - it has sent one before' if sticky and
                                                  not client.get('require_ma') else ''),
                      pkt=pkt, client=client, sparing=True)
            return False
        return True

    def ma_known(self, cid, ip):
        """Whether this address of the client has signed a request before -
        here, or on the other node, or before a restart (1.0.101). Looked up
        at most once a minute for an address that has not."""
        if (cid, ip) in self.ma_seen:
            return True
        t = time.time()
        if self.ma_asked.get((cid, ip), 0) > t - 60:
            return False
        if len(self.ma_asked) > 20000:
            self.ma_asked.clear()
        self.ma_asked[(cid, ip)] = t
        try:
            want = ':%s:%s' % (cid, ip)
            for r in self.d.store.db.rows("SELECT k FROM meta WHERE k LIKE 'maseen:%' AND "
                                          "substr(k, length(k) - ? + 1) = ?",
                                          (len(want), want)):
                if r['k'].split(':', 2)[-1] == want[1:]:
                    self.ma_seen.add((cid, ip))
                    return True
        except Exception:                               # noqa: BLE001
            pass
        return False

    def status(self, pkt, client, ip, port, secret):
        if not CONFIG.get('radius_status_server', 1):
            return None
        if not self.ma_check(pkt, client, secret, ip, port):
            return None
        self.counts['status'] += 1
        return build_reply(pkt, ACCESS_ACCEPT, [attr_bytes('Reply-Message', 'otp is alive')],
                           secret, True)

    def access(self, pkt, client, ip, port, secret, arrived, sock=None, peer=None,
               remember=None):
        if not self.ma_check(pkt, client, secret, ip, port):
            return None
        rid = '%s:%d' % (ip, port)
        user = pkt.text(1)
        try:
            password = pkt.password(secret)
        except RadiusError:
            password = None
        chap = pkt.get(3) is not None
        words = pkt.words()
        w = dict(words)
        state = pkt.get(24)
        try:
            if state is not None and bytes(state).startswith(CHAL_PREFIX):
                # The code from the second window (1.0.76).
                d = self.d.auth.answer(user, password, bytes(state), client.get('realm') or '',
                                       src=ip, rid=rid, chap=chap, client=client)
            else:
                d = self.d.auth.decide(user, password, client.get('realm') or '', src=ip,
                                       rid=rid, chap=chap, client=client)
        except DbError as e:
            # The database gone (1.0.59): no answer, as a node in maintenance
            # gives none - the VPN asks the other node, where a refusal would
            # have refused everybody until the database was back.
            self.counts['no_database'] += 1
            log_sparing('radius-db', 'RADIUS requests go unanswered: the database cannot be '
                        'reached (%s)' % str(e).split('\n')[0][:200], 'error')
            return None
        except Exception as e:
            # Whatever went wrong inside, the VPN gets an answer - a refusal
            # with the reason written down - rather than silence and a retry.
            log_sparing('radius-decide:%s' % type(e).__name__,
                        'a request for %s could not be decided: %s' % (user, e), 'error')
            d = Decision()
            d.user = str(user or '')
            d.step('the decision', False, 'it could not be made: %s' % e)
            d.refuse('the token server could not decide: %s' % str(e)[:120])
        pairs = []
        for name, value in d.reply:
            try:
                pairs.append(attr_bytes(name, value))
            except RadiusError as e:
                d.step('the answer', False, str(e))
                # Never an Accept without what limits it (1.0.101): one
                # attribute that cannot be built refuses, not drops.
                if d.result == 'accept':
                    d.refuse('the answer cannot be built whole: %s' % e)
        if d.result == 'accept':
            self.counts['accept'] += 1
            code = ACCESS_ACCEPT
        elif d.result == 'challenge' and d.state:
            # The second window (1.0.76): the State the VPN sends back with
            # the code, and the words it shows. Nothing that lets in.
            self.counts['challenge'] += 1
            code = ACCESS_CHALLENGE
            pairs = [attr_bytes('State', '0x' + bytes(d.state).hex())]
            said = (d.message or '').encode('utf-8')[:253].decode('utf-8', 'ignore')
            if said:
                pairs.append(attr_bytes('Reply-Message', said))
        else:
            self.counts['reject'] += 1
            code = ACCESS_REJECT
            # The reason is cut by bytes, not characters, so a reason full of
            # accented letters still fits the attribute; and if the attribute
            # cannot be built for whatever reason the reject still goes out
            # without it rather than the request going unanswered and unlogged.
            pairs = []
            # The reason stays here unless asked for (1.0.33): sent back, a
            # VPN may show it to whoever is signing in - whether the name has
            # a token, whether the code was right and the password not.
            if CONFIG.get('radius_reject_reason'):
                try:
                    said = (d.reason or '').encode('utf-8')[:253].decode('utf-8', 'ignore')
                    if said:
                        pairs = [attr_bytes('Reply-Message', said)]
                except (RadiusError, ValueError) as e:
                    d.step('the answer', False, 'the reason could not be sent along: %s' % e)
                    pairs = []
        try:
            reply = build_reply(pkt, code, pairs, secret, bool(CONFIG.get('radius_reply_ma', 1)))
        except RadiusError as e:
            # Too long with what the realm and the groups add (1.0.44): a
            # refusal still goes out and is written down - never an Accept
            # without the attributes that limit what it lets in to.
            d.step('the answer', False, '%s - refused, since it cannot be sent whole' % e)
            if code == ACCESS_ACCEPT:
                self.counts['accept'] -= 1
                self.counts['reject'] += 1
                d.refuse('the answer would be longer than a RADIUS packet may be: too many '
                         'reply attributes in the realm and its groups')
                code = ACCESS_REJECT
            reply = build_reply(pkt, code, [], secret, bool(CONFIG.get('radius_reply_ma', 1)))
        took = int((time.time() - arrived) * 1000)
        # The answer goes out before anything is written down (1.0.33): a
        # database that is slow or locked delays the log, not the person -
        # and never leaves a request that was let in without its answer.
        reply = SentReply(reply)
        delay = int(CONFIG.get('radius_reject_delay_ms') or 0) if code == ACCESS_REJECT else 0
        # To the address the request came from, as it came (1.0.36): on a
        # socket listening on :: an IPv4 client is ::ffff:a.b.c.d there, and
        # the bare a.b.c.d could not be sent to - every answer was lost.
        sock = sock or self.socks.get('auth', (None, None, None))[2]
        peer = peer or (ip, port)
        if delay:
            # Waited out by one thread for all of them, not a thread each
            # (1.0.36), and not in a worker: a flood of wrong codes cannot
            # tie up the workers sleeping.
            reply.late = True
            self.later(min(delay, 10000) / 1000.0, sock, bytes(reply), peer)
        else:
            try:
                if sock is not None:
                    sock.sendto(bytes(reply), peer)
            except OSError as e:
                log('the answer to %s could not be sent: %s' % (ip, e), 'warn')
            if remember is not None:
                remember(bytes(reply))
        reply.sent = True
        try:
            self.write_down(pkt, client, ip, port, rid, arrived, d, code, reply, took, words, w)
        except Exception as e:                          # noqa: BLE001
            log_sparing('radius-write', 'the request from %s for %s could not be written down: %s'
                        % (ip, d.user, str(e).split('\n')[0][:200]), 'error')
        return reply

    def later(self, wait, sock, data, peer):
        """An answer sent after `wait` seconds, by the one thread that sends
        the late ones. Past 10 000 waiting the newest are sent at once rather
        than kept."""
        with self.late_lock:
            if len(self.late) >= 10000:
                # Dropped, not sent at once (1.0.57): sent at once, a flood
                # of wrong guesses went round the delay. The NAS asks again.
                self.counts['late_dropped'] += 1
                return
            heapq.heappush(self.late, (time.time() + wait, id(data), sock, data, peer))
            if self.late_thread is None or not self.late_thread.is_alive():
                self.late_thread = threading.Thread(target=self.send_lates, name='radius-late',
                                                    daemon=True)
                self.late_thread.start()
        self.late_wake.set()

    def send_lates(self):
        while not self.stop_flag:
            # Cleared before the queue is looked at, not after the wait: one
            # put in between would otherwise sleep a whole second.
            self.late_wake.clear()
            with self.late_lock:
                due = []
                now = time.time()
                while self.late and self.late[0][0] <= now:
                    due.append(heapq.heappop(self.late))
                wait = (self.late[0][0] - now) if self.late else 1.0
            for _t, _i, sock, data, peer in due:
                self.send_late(sock, data, peer)
            self.late_wake.wait(max(0.005, min(wait, 1.0)))

    @staticmethod
    def send_late(sock, data, peer):
        try:
            if sock is not None:
                sock.sendto(data, peer)
        except OSError:
            pass

    def write_down(self, pkt, client, ip, port, rid, arrived, d, code, reply, took, words, w):
        if d.result == 'accept' and d.token_name:
            self.d.tokens.mark_from(d.token_name, w.get('Calling-Station-Id') or ip,
                                    (client or {}).get('name') or '')
        av = {}
        for name, value in words:
            if name == 'Cisco-AVPair' and '=' in value:
                k, _, v = value.partition('=')
                if k == 'mdm-tlv':
                    k, _, v = v.partition('=')
                av[k] = v
        tunnel = ''
        for name, value in words:
            if name == 'Vendor-3076-Attr-146' and value.startswith('0x'):
                try:
                    tunnel = bytes.fromhex(value[2:]).decode('ascii', 'ignore').strip('\x00')
                except ValueError:
                    pass
        reply_words = [(n, v) for n, v in Packet.parse(bytes(reply)).words()
                       if n != 'Message-Authenticator']
        self.d.store.radius_add({
            'ts': arrived, 'client': client['name'], 'nas_ip': w.get('NAS-IP-Address') or ip,
            'src': rid, 'packet': 'Access-Request',
            'username': d.user[:190] or (pkt.text(1) or '')[:190],
            'realm': d.realm, 'calling': (w.get('Calling-Station-Id') or '')[:190],
            'called': (w.get('Called-Station-Id') or '')[:190], 'result': d.result,
            'reason': d.reason[:1000], 'otp': d.otp[:190], 'rid': rid, 'took_ms': took,
            'attrs': json.dumps(words), 'reply': json.dumps(reply_words),
            'steps': json.dumps(d.steps), 'device': (av.get('computer-name') or '')[:190],
            'tunnel': tunnel[:190]})
        self.ship(pkt, words, reply_words, code, ip, port, rid, arrived)

    def accounting(self, pkt, client, ip, port, secret, arrived):
        if pkt.code == STATUS_SERVER:
            # Asked on the accounting port, answered with an
            # Accounting-Response (RFC 5997 4; 1.0.44).
            if not CONFIG.get('radius_status_server', 1):
                return None
            if not self.ma_check(pkt, client, secret, ip, port):
                return None
            self.counts['status'] += 1
            return build_reply(pkt, ACCOUNTING_RESPONSE, [], secret, True)
        # Sparingly, as on the other port (1.0.59): neither is proven to come
        # from the client, and each one was a row in the database.
        if pkt.code != ACCOUNTING_REQUEST:
            self.drop(ip, port, pkt.text(1), 'only Accounting-Request is answered on this port',
                      pkt=pkt, client=client, sparing=True)
            return None
        if not pkt.accounting_ok(secret):
            self.drop(ip, port, pkt.text(1), 'the authenticator of the accounting request is '
                      'wrong: the shared secret is not the same as on the client', pkt=pkt,
                      client=client, sparing=True)
            return None
        # A Message-Authenticator, where there is one, has to be right too
        # (1.0.59) - over the packet with the authenticator as noughts.
        if pkt.message_authenticator_ok(secret, zero_authenticator=True) is False and \
                pkt.message_authenticator_ok(secret) is not True:
            self.drop(ip, port, pkt.text(1), 'the Message-Authenticator of the accounting '
                      'request is wrong', pkt=pkt, client=client, sparing=True)
            return None
        self.counts['accounting'] += 1
        words = pkt.words()
        w = dict(words)
        self.d.store.radius_add({
            'ts': arrived, 'client': client['name'], 'nas_ip': w.get('NAS-IP-Address') or ip,
            'src': '%s:%d' % (ip, port), 'packet': 'Accounting-Request',
            'username': (w.get('User-Name') or '')[:190], 'realm': '',
            'calling': (w.get('Calling-Station-Id') or '')[:190],
            'called': (w.get('Called-Station-Id') or '')[:190], 'result': 'acct',
            'reason': (w.get('Acct-Status-Type') or '')[:100], 'otp': '', 'rid': '',
            'took_ms': int((time.time() - arrived) * 1000), 'attrs': json.dumps(words),
            'reply': '[]', 'steps': '[]', 'device': '', 'tunnel': ''})
        if self.d.shipper:
            self.d.shipper.detail_line(ip, 'detail', arrived, self.header(
                'Accounting-Request', ip, port, port_here=self.port_of('acct')) + words)
        return build_reply(pkt, ACCOUNTING_RESPONSE, [], secret, with_ma=False)

    def port_of(self, kind):
        got = self.socks.get(kind)
        return got[1] if got else 0

    @staticmethod
    def header(packet, ip, port, port_here, reply=False):
        """What FreeRADIUS writes first in a detail record under
        `log_packet_header = yes`."""
        if reply:
            return [('Packet-Type', packet), ('Packet-Dst-IP-Address', ip),
                    ('Packet-Dst-IP-Port', str(port))]
        return [('Packet-Type', packet), ('Packet-Src-IP-Address', ip),
                ('Packet-Src-IP-Port', str(port)), ('Packet-Dst-IP-Port', str(port_here))]

    def ship(self, pkt, words, reply_words, code, ip, port, rid, arrived):
        sh = self.d.shipper
        if not sh:
            return
        here = self.port_of('auth')
        ask = self.header('Access-Request', ip, port, here) + words + [('Totp-Request-Id', rid)]
        sh.detail_line(ip, 'auth-detail', arrived, ask)
        answer = self.header(CODE_WORDS[code], ip, port, here, reply=True) + reply_words + [
            ('Totp-Request-Id', rid)]
        sh.detail_line(ip, 'reply-detail', time.time(), answer)

    def state(self):
        return {'listening': self.bound, 'trouble': self.trouble, 'counts': dict(self.counts),
                'queued': self.jobs.qsize()}


# ---------------------------------------------------------------------------
# Bringing an old token server over: totpcgi and its FreeRADIUS
# ---------------------------------------------------------------------------
# The server this replaces kept a file per person (`name@realm.totp`, the
# google-authenticator format: the key, a few `" OPTION` lines, the recovery
# codes), its RADIUS clients in clients.conf, the realm a client's names
# belong to in hints, and the directory and its groups in a YAML file beside
# the Perl handler. All of it is read here so that nobody has to enrol again.

def parse_totp_file(text):
    """(secret, options, recovery codes) out of one google-authenticator file."""
    lines = [l.strip() for l in str(text or '').splitlines() if l.strip()]
    if not lines:
        raise ValueError('the file is empty')
    secret = lines[0]
    # At least 80 bits, as google-authenticator writes them (1.0.36): any
    # word at all was taken for a key, and a file of rubbish made an active
    # token with a 35-bit key.
    if len(b32_clean(secret)) < 10:
        raise ValueError('the first line is not a key of at least 16 base32 characters')
    opts, codes = {}, []
    for line in lines[1:]:
        if line.startswith('"'):
            bits = line[1:].split()
            if bits:
                opts[bits[0].upper()] = bits[1:]
        elif re.match(r'^[0-9]{6,10}\Z', line):
            codes.append(line)
    if 'HOTP_COUNTER' in opts:
        raise ValueError('a counter (HOTP) token, not a time one: it would not give the '
                         'same codes here')
    return re.sub(r'[\s\-=]', '', secret).upper(), opts, codes


TOKEN_WINDOW_MOST = 20     # the most the pages allow (1.0.101)


def import_totp(store, name, text, by='import', replace=False):
    """One person's token, from the old server's file. Returns what happened."""
    secret, opts, codes = parse_totp_file(text)
    name = norm_name(name)
    if store.token(name) and not replace:
        return 'kept (there is a token for %s already)' % name
    window = -1
    if 'WINDOW_SIZE' in opts and opts['WINDOW_SIZE']:
        try:
            # As many steps either side as the pages allow, never more
            # (1.0.101): WINDOW_SIZE 200001 took codes from days back.
            window = min(TOKEN_WINDOW_MOST, max(0, (int(opts['WINDOW_SIZE'][0]) - 1) // 2))
        except ValueError:
            window = -1
    store.token_write(name, {
        'secret': seal_secret(secret, token_bind(name)), 'digits': 6, 'period': 30,
        'algorithm': 'SHA1',
        'window_steps': window, 'state': 'active', 'last_step': 0,
        'scratch': json.dumps([scratch_hash(name, c) for c in codes]),
        'scratch_sealed': seal_codes(codes, token_bind(name)),
        'scratch_left': len(codes), 'created': time.time(), 'created_by': by,
        'activated': time.time(), 'failures': 0, 'fail_times': '[]', 'locked_until': None,
        'pending_secret': None, 'pending_scratch': None, 'pending_at': None, 'pending_by': None,
        'issuer': str(CONFIG.get('totp_issuer') or ''), 'label': name,
        'note': 'brought over from totpcgi' + ('' if 'TOTP_AUTH' in opts else
                                               ' (the file was not marked TOTP_AUTH)')})
    try:
        store.db.run('DELETE FROM meta WHERE k = ?', ('staged:' + name,))
    except Exception:                                   # noqa: BLE001
        pass
    return 'imported, %d recovery code(s)' % len(codes)


# ---- a whole backup of tokens, of every kind (1.0.96) -------------------------------
# What a token is - its key, its recovery codes (used and not), how its codes
# come (the app, mail, SMS) and where to, its language, its state - as one
# file, locked with a passphrase if one is given (the same lock as the HA
# bundle: scrypt, then a keyed stream and an HMAC). Read back on this
# server or another otp: all of them, or the ones picked. The keys are in
# it in the clear (inside the lock): the sealing key of this machine is not
# needed on the other.

TOKENS_KIND = 'otp-tokens'


def token_backup_row(tok):
    """One token as the backup keeps it, or None when its key cannot be
    opened here."""
    name = tok['name']
    kind = token_kind(tok)
    out = {'name': name, 'kind': kind, 'state': tok.get('state') or 'active'}
    if kind == 'totp':
        secret = unseal_secret(tok.get('secret') or '', token_bind(name))
        if not secret:
            return None
        out.update(secret=re.sub(r'[\s\-=]', '', str(secret)).upper(),
                   digits=int(tok.get('digits') or 6),
                   period=int(tok.get('period') or 30),
                   algorithm=str(tok.get('algorithm') or 'SHA1').upper())
    else:
        out['dest'] = tok.get('dest') or ''
    codes = open_codes(tok.get('scratch_sealed'), token_bind(name))
    out['codes'] = [{'c': c['c'], 'used': c.get('used')} for c in (codes or [])]
    if codes is None and int(tok.get('scratch_left') or 0):
        out['codes_lost'] = int(tok.get('scratch_left') or 0)
    for k in ('window_steps', 'last_step'):
        if tok.get(k) is not None:
            out[k] = int(tok.get(k))
    for k in ('lang', 'mail_fmt', 'note', 'display', 'issuer', 'label', 'created_by',
              'last_from', 'last_how'):
        if tok.get(k):
            out[k] = str(tok.get(k))
    for k in ('created', 'activated', 'last_used'):
        if tok.get(k):
            out[k] = float(tok.get(k))
    return out


def tokens_backup(store, names, by=''):
    rows, lost = [], []
    for n in names:
        tok = store.token(n)
        if not tok:
            continue
        one = token_backup_row(tok)
        if one is None:
            lost.append(n)
        else:
            rows.append(one)
    return {'kind': TOKENS_KIND, 'format': 1, 'made': time.time(), 'by': by,
            'node': node_name(), 'version': __version__, 'count': len(rows),
            'lost': lost, 'tokens': rows}


def tokens_backup_open(text, passphrase=''):
    """The backup in a file: plain, or locked (then the passphrase opens it).
    None when the file is no backup at all (a .totp file, say)."""
    try:
        got = json.loads(text)
    except (ValueError, TypeError):
        return None
    if not isinstance(got, dict) or got.get('kind') != TOKENS_KIND:
        return None
    if got.get('locked'):
        if not passphrase:
            raise PermissionError('the backup is locked: its passphrase opens it')
        got = bundle_open(got, passphrase, kinds=(TOKENS_KIND,))
    if not isinstance(got.get('tokens'), list):
        raise ValueError('the backup holds no list of tokens')
    return got


def token_restore(store, t, by='restore', replace=False):
    """One token out of a backup. Returns what happened."""
    if not isinstance(t, dict):
        raise ValueError('not a token')
    name = norm_name(t.get('name'))
    if not name or len(name) > 190:
        raise ValueError('no name')
    kind = str(t.get('kind') or 'totp')
    if kind not in ('totp', 'mail', 'sms'):
        raise ValueError('a kind this version does not know: %s' % kind)
    if store.token(name) and not replace:
        return 'kept (there is a token for %s already)' % name
    state = str(t.get('state') or 'active')
    if state not in ('active', 'pending', 'disabled'):
        state = 'active'
    codes = []
    for c in t.get('codes') or []:
        code = str((c or {}).get('c') if isinstance(c, dict) else c)
        if not re.fullmatch(r'[0-9]{6,10}', code):
            raise ValueError('a recovery code that is not one')
        codes.append({'c': code, 'used': (c or {}).get('used') if isinstance(c, dict) else None})
    left = [c['c'] for c in codes if not c.get('used')]
    row = {'state': state, 'kind': '' if kind == 'totp' else kind, 'dest': '',
           'scratch': json.dumps([scratch_hash(name, c) for c in left]),
           'scratch_sealed': seal_codes(codes, token_bind(name)) if codes else '',
           'scratch_left': len(left), 'failures': 0, 'fail_times': '[]', 'locked_until': None,
           'pending_secret': None, 'pending_scratch': None, 'pending_at': None,
           'pending_by': None, 'created': float(t.get('created') or time.time()),
           'created_by': str(t.get('created_by') or by)[:190],
           'activated': t.get('activated') or (time.time() if state == 'active' else None),
           'last_used': t.get('last_used'), 'last_from': str(t.get('last_from') or '')[:190],
           'last_how': str(t.get('last_how') or '')[:190],
           'note': str(t.get('note') or '')[:2000], 'display': str(t.get('display') or '')[:300],
           'issuer': str(t.get('issuer') or CONFIG.get('totp_issuer') or '')[:190],
           'label': str(t.get('label') or name)[:190],
           'lang': t.get('lang') if t.get('lang') in ('cs', 'en') else '',
           'mail_fmt': t.get('mail_fmt') if t.get('mail_fmt') in ('html', 'text') else ''}
    if kind == 'totp':
        secret = re.sub(r'[\s\-=]', '', str(t.get('secret') or '')).upper()
        try:
            if len(b32_clean(secret)) < 10:
                raise ValueError
        except ValueError:
            raise ValueError('the key is not a key of at least 16 base32 characters')
        digits, period = int(t.get('digits') or 6), int(t.get('period') or 30)
        algo = str(t.get('algorithm') or 'SHA1').upper()
        if digits not in (6, 7, 8) or not 10 <= period <= 300 or \
                algo not in ('SHA1', 'SHA256', 'SHA512'):
            raise ValueError('digits, period or algorithm this version does not take')
        row.update(secret=seal_secret(secret, token_bind(name)), digits=digits, period=period,
                   algorithm=algo, window_steps=max(-1, min(TOKEN_WINDOW_MOST, int(t['window_steps'])))
                   if t.get('window_steps') is not None else -1,
                   last_step=int(t.get('last_step') or 0))
    else:
        row.update(secret='', dest=dest_checked(kind, t.get('dest')), digits=6, period=30,
                   algorithm='SHA1', window_steps=-1, last_step=0)
    store.token_write(name, row)
    try:
        store.db.run('DELETE FROM meta WHERE k = ?', ('staged:' + name,))
    except Exception:                                   # noqa: BLE001
        pass
    return 'restored (%s, %d recovery code(s) left)' % (
        {'totp': 'the app', 'mail': 'codes by mail', 'sms': 'codes by SMS'}[kind], len(left))


def _legacy_root(root):
    root = Path(root)
    for cand in (root, root / 'otp', root / 'otp' / 'otp'):
        if (cand / 'etc' / 'raddb').is_dir() or (cand / 'etc' / 'totpcgi').is_dir():
            return cand
    raise ValueError('%s holds no etc/raddb or etc/totpcgi' % root)


def parse_clients_conf(text):
    """FreeRADIUS clients.conf as [{name, address, secret, shortname}]."""
    out = []
    body = re.sub(r'#[^\n]*', '', str(text or ''))
    for m in re.finditer(r'client\s+(\S+)\s*\{([^}]*)\}', body):
        key, inside = m.group(1), m.group(2)
        vals = dict((a.strip().lower(), b.strip().strip('"'))
                    for a, b in re.findall(r'^\s*([A-Za-z_]+)\s*=\s*(.+?)\s*$', inside, re.M))
        addr = vals.get('ipaddr') or vals.get('ipv4addr') or key
        out.append({'name': vals.get('shortname') or key, 'address': addr,
                    'secret': vals.get('secret', ''),
                    'require_ma': 1 if vals.get('require_message_authenticator') == 'yes'
                    else 0})
    return out


def parse_hints(text):
    """The realm FreeRADIUS's hints file adds to names, by NAS address."""
    out = {}
    lines = str(text or '').splitlines()
    for i, line in enumerate(lines):
        m = re.match(r'^\s*DEFAULT\s+NAS-IP-Address\s*==\s*"?([0-9a-fA-F.:]+)"?', line)
        if not m:
            continue
        for nxt in lines[i + 1:i + 4]:
            r = re.search(r'User-Name\s*:?=\s*"%\{User-Name\}@([^"]+)"', nxt)
            if r:
                out[m.group(1)] = r.group(1)
                break
    return out


def parse_handler_yaml(text):
    """What the old Perl handler was told about the directory."""
    got = {'hosts': [], 'groups': []}
    in_list = None
    for raw in str(text or '').splitlines():
        line = raw.split('#', 1)[0].rstrip() if not raw.strip().startswith("- '") else raw
        if not line.strip():
            continue
        m = re.match(r'^(\w+)\s*:\s*(.*)\Z', line.strip())
        if m and not line.startswith(' '):
            k, v = m.group(1), m.group(2).strip().strip("'\"")
            in_list = k if not v else None
            got[k] = v
            continue
        m = re.match(r'^\s*-\s*[\'"]?(.*?)[\'"]?\s*\Z', line)
        if m and in_list:
            got.setdefault(in_list + '_list', []).append(m.group(1))
    hosts = got.get('ldaphosts_list') or []
    got['hosts'] = [re.sub(r'^ldaps?://', '', h).rstrip('/') for h in hosts]
    got['tls'] = 'ldaps' if any(h.startswith('ldaps') for h in hosts) else 'none'
    groups = []
    for f in got.get('groupSearch_list') or []:
        m = re.search(r'\(cn=([^)]+)\)', f, re.I)
        if m:
            groups.append(m.group(1))
    got['groups'] = groups
    return got


def bind_tokens(store):
    """Every token's secrets sealed again tied to its name (1.0.33), where
    they were sealed the old way, without it; then the old way is no longer
    taken for a token at all. Run at start and after a restore."""
    cols = ('secret', 'pending_secret', 'scratch_sealed', 'pending_scratch')
    done = left = 0
    try:
        # ...and one never sealed at all (1.0.101): sealed now, so that from
        # here on a value not sealed is taken for no token - a row written
        # into the database (by replication, by a restore) with a key its
        # writer knows no longer opens the door.
        rows = store.db.rows("SELECT id, name, %s FROM tokens WHERE %s"
                             % (', '.join(cols), ' OR '.join(
                                 "%s LIKE 'sealed:1:%%' OR (%s <> '' AND %s NOT LIKE 'sealed:%%')"
                                 % (c, c, c) for c in cols)))
    except Exception as e:                              # noqa: BLE001
        log('the tokens could not be read to seal them again: %s' % e, 'warn')
        return
    for r in rows:
        fields = {}
        for c in cols:
            v = r.get(c)
            if isinstance(v, str) and v.startswith(SEALED):
                plain = unseal_secret(v)
                if plain is None:
                    left += 1
                    continue
                fields[c] = seal_secret(plain, token_bind(r['name']))
            elif isinstance(v, str) and v and not v.startswith('sealed:'):
                fields[c] = seal_secret(v, token_bind(r['name']))
        if fields:
            # Only if still as read: the other node may have done it already.
            sets = ', '.join('%s = ?' % c for c in fields)
            conds = ' AND '.join('%s = ?' % c for c in fields)
            store.db.run('UPDATE tokens SET %s WHERE id = ? AND %s' % (sets, conds),
                         list(fields.values()) + [r['id']] + [r[c] for c in fields])
            done += 1
    if done:
        log('%d token(s) sealed again, tied to their names' % done)
    if not left:
        BIND_STRICT['tokens'] = True
    else:
        log('%d sealed value(s) of tokens do not open with this key and were left as they are'
            % left, 'warn')


def import_legacy(store, root, by='import', replace=False, say=print):
    """Everything the old server held, into this one. Returns counts."""
    base = _legacy_root(root)
    done = collections.Counter()
    raddb = base / 'etc' / 'raddb'
    hints = parse_hints((raddb / 'hints').read_text(errors='replace')) \
        if (raddb / 'hints').exists() else {}
    realms_seen = set(hints.values())
    # ---- the directory and the realm -----------------------------------
    yaml_file = raddb / 'totpcgi-handler.yaml'
    directory = ''
    if yaml_file.exists():
        y = parse_handler_yaml(yaml_file.read_text(errors='replace'))
        if y['hosts'] and y.get('userSearchBase'):
            directory = 'AD'
            if not store.directory(directory) or replace:
                old = store.directory(directory)
                store.directory_save({
                    'id': old['id'] if old else None, 'name': directory,
                    'hosts': ', '.join(y['hosts']), 'tls': y['tls'],
                    'port': 636 if y['tls'] == 'ldaps' else 389, 'verify': 1,
                    'base': y.get('userSearchBase'), 'bind_dn': y.get('bindDN', ''),
                    'bind_pw': y.get('bindPassword', ''), 'user_attr': 'sAMAccountName',
                    'nested': 0,
                    'note': 'brought over from totpcgi-handler.yaml'}, by)
                done['directories'] += 1
                say('directory %s: %s (base %s, signing in as %s). Its certificate is '
                    'checked: import the certificate authority that signed the domain '
                    'controllers’ certificates, or switch the check off.'
                    % (directory, ', '.join(y['hosts']), y.get('userSearchBase'),
                       y.get('bindDN')))
            lookup = 'upn' if 'userPrincipalName' in str(y.get('search') or
                                                          y.get('userAttribute') or '') \
                else 'sam'
            for suffix in sorted(realms_seen) or ['*']:
                if any(str(r.get('suffix')) == suffix for r in store.realms()) and not replace:
                    continue
                old = next((r for r in store.realms() if r.get('suffix') == suffix), None)
                store.realm_save({
                    'id': old['id'] if old else None, 'name': suffix if suffix != '*'
                    else 'default', 'suffix': suffix, 'directory': directory,
                    'lookup': lookup, 'auth_mode': 'otp', 'check_disabled': 1, 'nested': 0,
                    'groups': [{'group': g, 'reply': ''} for g in y['groups']],
                    'token_name': 'whole',
                    'note': 'brought over: the code alone, then the user filter and the '
                            'group filter the old handler applied'}, by)
                done['realms'] += 1
                say('realm %s: %d group(s), looked up by %s' % (suffix, len(y['groups']),
                                                                lookup))
    # ---- the clients ---------------------------------------------------------
    if (raddb / 'clients.conf').exists():
        for c in parse_clients_conf((raddb / 'clients.conf').read_text(errors='replace')):
            try:
                net = address_net(c['address'])
            except ValueError:
                say('client %s: %r is not an address, left out' % (c['name'], c['address']))
                continue
            plain = str(net.network_address) if net.num_addresses == 1 else str(net)
            realm = hints.get(plain, '')
            if plain in ('127.0.0.1', '::1') and not realm:
                realm = hints.get('127.0.0.1', '')
            name = c['name'] if c['name'] != c['address'] else (
                'localhost' if plain == '127.0.0.1' else plain)
            old = next((x for x in store.clients() if x['name'].lower() == name.lower()), None)
            if old and not replace:
                say('client %s: there is one already, left as it is' % name)
                continue
            # Another client at the very same address (1.0.103): two of the
            # same width, the one named first wins - the NAS already here
            # would have been answered with the imported one's secret.
            same = next((x for x in store.clients() if (not old or x['id'] != old['id']) and
                         str(x.get('address') or '').strip().lower() == plain.lower()), None)
            if same:
                say('client %s: %s is the address of the client %s here already, left out'
                    % (name, plain, same['name']))
                continue
            store.client_save({'id': old['id'] if old else None, 'name': name,
                               'address': plain, 'secret': c['secret'], 'realm': realm,
                               'require_ma': c['require_ma'], 'enabled': 1,
                               'note': 'brought over from clients.conf'}, by)
            done['clients'] += 1
            say('client %s: %s%s' % (name, plain, (', names get @' + realm) if realm else ''))
    # ---- the settings ----------------------------------------------------------
    prov = base / 'etc' / 'totpcgi' / 'provisioning.conf'
    if prov.exists():
        text = prov.read_text(errors='replace')
        def ini(key):
            m = re.search(r'^\s*%s\s*=\s*(.+?)\s*$' % key, text, re.M)
            return m.group(1) if m else None
        changes = {}
        if ini('totp_issuer'):
            changes['totp_issuer'] = ini('totp_issuer')
        if ini('window_size'):
            try:
                changes['totp_window'] = max(0, (int(ini('window_size')) - 1) // 2)
            except ValueError:
                pass
        if ini('rate_limit'):
            m = re.match(r'(\d+)\s*,\s*(\d+)', ini('rate_limit'))
            if m:
                changes['rate_limit_tries'] = int(m.group(1))
                changes['rate_limit_s'] = int(m.group(2))
        if ini('scratch_tokens_n'):
            try:
                changes['scratch_count'] = int(ini('scratch_tokens_n'))
            except ValueError:
                pass
        if realms_seen:
            r = sorted(realms_seen)[0]
            changes['portal_realm'] = r
            changes['portal_hint'] = 'login@%s' % r
        # Each one by itself, brought into the range this version takes, and
        # one saved here already kept unless --replace (1.0.103): a window of
        # 25 stopped the import half done, with no token brought over.
        saved = store.settings_saved()
        taken = {}
        for k, v in changes.items():
            if k in saved and not replace:
                say('setting %s: set here already (%s), left as it is' % (k, saved[k]))
                continue
            shape = TUNABLE.get(k)
            if isinstance(shape, tuple) and len(shape) == 2 and all(
                    isinstance(x, int) for x in shape) and isinstance(v, int):
                if not shape[0] <= v <= shape[1]:
                    say('setting %s: %s is more than this version takes - %s'
                        % (k, v, min(max(v, shape[0]), shape[1])))
                    v = min(max(v, shape[0]), shape[1])
            try:
                v = check_setting(k, v)
            except BadSetting as e:
                say('setting %s: left out (%s)' % (k, e))
                continue
            store.save_setting(k, v, by)
            CONFIG[k] = v
            taken[k] = v
            done['settings'] += 1
        if taken:
            say('settings: %s' % ', '.join('%s=%s' % kv for kv in sorted(taken.items())))
    # ---- the tokens -------------------------------------------------------------
    for folder in (base / 'etc' / 'totpcgi' / 'totp',):
        if not folder.is_dir():
            continue
        for f in sorted(folder.glob('*.totp')):
            name = f.name[:-5]
            try:
                said = import_totp(store, name, f.read_text(errors='replace'), by, replace)
                done['tokens' if said.startswith('imported') else 'tokens_kept'] += 1
            except ValueError as e:
                say('%s: %s' % (f.name, e))
                done['tokens_bad'] += 1
    loose = sorted((base / 'etc' / 'totpcgi').glob('*.totp')) \
        if (base / 'etc' / 'totpcgi').is_dir() else []
    if loose:
        say('left alone, outside the totp folder the old server read: %s'
            % ', '.join(f.name for f in loose))
    store.add_event('import', 'brought over from %s: %s' % (
        root, ', '.join('%s %d' % kv for kv in sorted(done.items())) or 'nothing'), who=by)
    return done


# ---------------------------------------------------------------------------
# Copies of the database
# ---------------------------------------------------------------------------
def make_backup(store, why='by hand'):
    """A copy of everything into the backups folder - and the key that opens
    the tokens beside it, because one without the other is nothing."""
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    stamp_ = datetime.now().strftime('%Y%m%d-%H%M%S')
    # A name of its own (two in one second overwrote each other) and written
    # under another until it is whole (1.0.59): a half file counted as a
    # kept copy and pushed a good one out.
    # The name taken with O_EXCL (1.0.61): two processes - the daemon's
    # nightly copy and a root --backup - in the same second both saw it free.
    base = stamp_
    for suffix in [''] + ['-' + c for c in 'bcdefghijklmnopqrstuvwxyz']:
        stamp_ = base + suffix
        out = BACKUP_DIR / ('otp-%s.json.gz' % stamp_)
        try:
            os.close(os.open(str(out), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o640))
            break
        except FileExistsError:
            continue
    else:
        raise ValueError('no free name for a copy in %s' % BACKUP_DIR)
    # A name nobody can have put there first, opened without following a
    # link, its mode and owner set on the open file (1.0.101): run by root
    # (--ha-resync, --backup) in a folder the service's account can write,
    # the name it wrote to was the service account's to point anywhere.
    part = BACKUP_DIR / ('.otp-%s-%s.json.gz.part' % (stamp_, secrets.token_hex(6)))
    owner = service_ids() if os.geteuid() == 0 else None
    try:
        fd = os.open(str(part), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o640)
        os.fchmod(fd, 0o640)
        if owner:
            os.fchown(fd, owner[0], owner[1])
        with os.fdopen(fd, 'wb') as raw_f:
            dump_tables(store.db, raw_f)
        os.replace(str(part), str(out))
    except BaseException:
        try:
            out.unlink()            # the empty name taken, given back
        except OSError:
            pass
        raise
    finally:
        try:
            part.unlink()
        except OSError:
            pass
    key = sealing_key()
    if key:
        # Made by root on the command line (1.0.59): the service's own, or
        # the pages could neither list, download nor put it back.
        write_replacing(BACKUP_DIR / ('otp-%s.key' % stamp_), key.hex() + '\n', 0o600,
                        owner=owner)
    keep = int(CONFIG.get('backup_keep') or 14)
    copies = sorted(list(BACKUP_DIR.glob('otp-*.json.gz')) + list(BACKUP_DIR.glob('opt-*.json.gz')),
                    key=lambda f: f.stat().st_mtime)
    for old in copies[:-keep] if len(copies) > keep else []:
        for f in (old, old.with_name(old.name.replace('.json.gz', '.key'))):
            try:
                f.unlink()
            except OSError:
                pass
    store.add_event('backups', 'a copy of the database was made (%s): %s' % (why, out.name))
    return out


def backups():
    if not BACKUP_DIR.is_dir():
        return []
    out = []
    for f in sorted(list(BACKUP_DIR.glob('otp-*.json.gz')) + list(BACKUP_DIR.glob('opt-*.json.gz')),
                   key=lambda f: f.stat().st_mtime, reverse=True):
        st = f.stat()
        out.append({'name': f.name, 'size': st.st_size, 'at': st.st_mtime,
                    'key': f.with_name(f.name.replace('.json.gz', '.key')).exists()})
    return out


# ---------------------------------------------------------------------------
# PHP and php2shell, as the daemon can tell from outside it
# ---------------------------------------------------------------------------
# The pages say what version of PHP they run on, and a version below the
# fixed ones (8.2.35, 8.3.36, 8.4.27, 8.5.12) is "may be affected" - because a
# distribution that backported the fix keeps its old number. The packages'
# own changelog says whether the fix is in, and the daemon can read it where
# PHP cannot: so the warning on the pages goes away when the fix is there.
PHP_FIXED = {'8.2': (8, 2, 35), '8.3': (8, 3, 36), '8.4': (8, 4, 27), '8.5': (8, 5, 12)}
_PHP_STATE = {'at': 0, 'state': None}


_SOFTWARE = {'at': 0.0, 'state': None}


def _first_line(cmd, timeout=5):
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
    except (OSError, subprocess.SubprocessError):
        return ''
    text = (r.stdout or '') + (r.stderr or '')
    return (text.strip().splitlines() or [''])[0].strip()[:200]


def software_info(store=None):
    """What this node runs on (1.0.99): otp, its Python and the modules it
    uses, the libraries under them, the programs beside it and the system -
    for Settings → About, of every node. Asked at most once an hour."""
    if time.time() - _SOFTWARE['at'] < 3600 and _SOFTWARE['state'] is not None:
        out = dict(_SOFTWARE['state'])
    else:
        import platform
        import sqlite3
        out = {'otp': __version__,
               'python': '%s %s' % (platform.python_implementation(), platform.python_version()),
               'python_path': os.path.realpath(sys.executable),
               'openssl': ssl.OPENSSL_VERSION, 'sqlite': sqlite3.sqlite_version,
               'kernel': '%s %s' % (platform.system(), platform.release()),
               'arch': platform.machine(), 'modules': {}, 'programs': {}}
        try:
            with open('/etc/os-release', encoding='utf-8') as f:
                rel = dict(l.strip().split('=', 1) for l in f if '=' in l)
            out['os'] = rel.get('PRETTY_NAME', '').strip('"')
        except OSError:
            out['os'] = ''
        for mod, attr in (('psycopg2', '__version__'), ('pymysql', '__version__'),
                          ('colorama', '__version__')):
            try:
                m = __import__(mod)
                v = str(getattr(m, attr, '') or '').split(' ')[0]
                if mod == 'psycopg2':
                    lib = getattr(m, '__libpq_version__', 0)
                    if lib:
                        v += ' (libpq %d.%d)' % (lib // 10000, lib % 10000 // 100 if lib < 100000
                                                 else lib % 100)
                out['modules'][mod] = v
            except Exception:                           # noqa: BLE001
                out['modules'][mod] = ''
        progs = (('nginx', ['nginx', '-v']), ('php', ['php', '-v']),
                 ('php-fpm', None), ('keepalived', ['keepalived', '--version']),
                 ('pg_dump', ['pg_dump', '--version']),
                 ('mariadb-dump', ['mariadb-dump', '--version']),
                 ('openssl', ['openssl', 'version']), ('systemd', ['systemctl', '--version']),
                 ('iptables', ['iptables', '--version']),
                 ('firewalld', ['firewall-cmd', '--version']))
        for name, cmd in progs:
            if name == 'php-fpm':
                import glob
                fpm = sorted(glob.glob('/usr/sbin/php-fpm*') + glob.glob('/usr/sbin/php*-fpm*'))
                line = _first_line([fpm[-1], '-v']) if fpm else ''
            else:
                exe = shutil.which(cmd[0]) or next((p for p in ('/usr/sbin/' + cmd[0], '/sbin/' + cmd[0])
                                                    if os.path.exists(p)), None)
                line = _first_line([exe] + cmd[1:]) if exe else ''
            m = re.search(r'(\d+\.\d+(?:\.\d+)?[^\s,()]*)', line or '')
            if m and not re.search(r'(?i)denied|not found|error', line):
                out['programs'][name] = m.group(1)
            elif name == 'systemd':
                m = re.search(r'^systemd\s+(\d+)', line or '')
                if m:
                    out['programs'][name] = m.group(1)
        _SOFTWARE.update(at=time.time(), state=dict(out))
    # What changes without a restart, asked each time it is wanted.
    if store is not None:
        try:
            out['database'] = store.db.version() or ''
        except Exception:                               # noqa: BLE001
            pass
    try:
        out['php_cli'] = (php_state() or {}).get('version') or ''
    except Exception:                                   # noqa: BLE001
        pass
    return out


def php_state():
    if time.time() - _PHP_STATE['at'] < 3600 and _PHP_STATE['state'] is not None:
        return _PHP_STATE['state']
    out = {'version': '', 'fixed': None, 'how': ''}
    php = shutil.which('php') or next((p for p in ('/usr/bin/php', '/usr/local/bin/php')
                                       if os.path.exists(p)), None)
    if php:
        try:
            out['version'] = subprocess.run([php, '-r', 'echo PHP_VERSION;'], capture_output=True,
                                            text=True, timeout=10).stdout.strip()
        except (OSError, subprocess.SubprocessError):
            pass
    m = re.match(r'^(\d+)\.(\d+)\.(\d+)', out['version'])
    if m:
        v = tuple(int(x) for x in m.groups())
        want = PHP_FIXED.get('%d.%d' % v[:2])
        if want and v >= want or (not want and v[:2] > (8, 5)):
            out.update(fixed=True, how='version')
    if not out['fixed']:
        said = ''
        rpm = shutil.which('rpm')
        if rpm:
            for pkg in ('php-fpm', 'php-common'):
                try:
                    said += subprocess.run([rpm, '-q', '--changelog', pkg], capture_output=True,
                                           text=True, timeout=20).stdout
                except (OSError, subprocess.SubprocessError):
                    pass
        else:
            import gzip
            import glob
            for f in glob.glob('/usr/share/doc/php*-fpm/changelog.Debian.gz') + glob.glob(
                    '/usr/share/doc/php*-common/changelog.Debian.gz'):
                try:
                    with gzip.open(f, 'rt', errors='replace') as g:
                        said += g.read(200000)
                except OSError:
                    pass
        if 'CVE-2026-109618' in said:
            out.update(fixed=True, how='changelog')
        elif out['version']:
            out['fixed'] = False
    _PHP_STATE.update(at=time.time(), state=out)
    return out


# ---------------------------------------------------------------------------
# The daemon
# ---------------------------------------------------------------------------
class Daemon(object):
    def __init__(self, store, serve=True):
        self.store = store
        self._reader = None
        self._reader_lock = threading.Lock()
        self.started = time.time()
        self.stop_flag = threading.Event()
        self.shipper = None
        self.dirs = {}
        self.reload_directories()
        self.tokens = Tokens(store)
        self.auth = Authenticator(store, self.tokens, self.dirs)
        self.radius = None
        self.api = None
        self.serial = 0
        self.conf_serial = store.get_meta('conf_serial', '0')
        self.login_fails = collections.defaultdict(list)
        # What each count is (1.0.112): its limit, how long it lasts, and the
        # names tried from an address / the addresses a name was tried from -
        # for Settings - Accounts - Locked out.
        self.login_info = {}
        if serve:
            self.shipper = Shipper()
            self.tokens.on_check = self.shipper.token_line
            store.on_event = self.shipper.event_line
            self.radius = RadiusServer(self)

    def reload_directories(self):
        self.store._dirs = None
        fresh = {}
        for row in self.store.directories(with_secret=True):
            if row.get('enabled', 1):
                fresh[row['name'].lower()] = Directory(row)
        # Swapped in whole (1.0.44): emptied and filled again, a request in
        # between found no directory at all.
        self.dirs = fresh
        if getattr(self, 'auth', None) is not None:
            self.auth.dirs = fresh

    def fill_names(self, names=None, limit=500, by='', quiet=False):
        """The name a person goes by, from the directory, for the tokens that
        have none - those brought over from totpcgi or made here, which an
        enrolment on the pages would have given one. Each token's own realm
        says which directory to ask and how to look the name up. (1.0.14)"""
        done = {'filled': 0, 'not_found': 0, 'no_directory': 0, 'trouble': 0}
        dead = set()
        if names is None:
            rows = self.store.db.rows("SELECT name FROM tokens WHERE COALESCE(display, '') = '' "
                                      "ORDER BY id LIMIT %d" % int(limit))
            names = [r['name'] for r in rows]
        for name in names:
            realm = self.store.realm_for(name)
            ad = self.dirs.get(str((realm or {}).get('directory') or '').lower())
            if not realm or not ad:
                done['no_directory'] += 1
                continue
            lookup = realm.get('lookup') or ''
            if lookup not in ('upn', 'sam'):
                lookup = 'upn' if '@' in name else 'sam'
            if ad.name in dead:
                done['trouble'] += 1
                continue
            try:
                entry = ad.find_user(name, lookup)
            except Exception:                           # noqa: BLE001
                # Not reached: the rest of its tokens are not asked of it now
                # - every one would wait out the same timeout.
                dead.add(ad.name)
                done['trouble'] += 1
                continue
            if not entry or not entry.get('display'):
                done['not_found'] += 1
                continue
            # Only a token still there (1.0.59): token_write made a deleted
            # one again, empty, when it was taken away meanwhile.
            if self.store.db.run('UPDATE tokens SET display = ? WHERE name = ?',
                                 (str(entry['display'])[:300], name)):
                done['filled'] += 1
        if (done['filled'] or by) and not quiet:
            self.store.add_event('tokens', 'names from the directory: %d token(s) given their '
                                 'owner\'s name, %d not found, %d with no directory, %d could not '
                                 'be asked' % (done['filled'], done['not_found'],
                                               done['no_directory'], done['trouble']),
                                 who=by or None)
        return done

    def fill_names_later(self, names=None, by=''):
        threading.Thread(target=lambda: self.fill_names(names, by=by), name='fill-names',
                         daemon=True).start()

    RELOAD_LOCK = threading.RLock()

    def reload_all(self, why=''):
        """Everything read again from the database: the settings, the
        clients, the realms, the directories. One at a time (1.0.94): a save
        on the pages and the loop's own both opened the RADIUS sockets."""
        with self.RELOAD_LOCK:
            return self._reload_all(why)

    def _reload_all(self, why=''):
        load_config(saved=self.store.settings_saved())
        if not BIND_STRICT.get('tokens'):
            bind_tokens(self.store)
        self.store._clients = None
        self.store._realms = None
        self.reload_directories()
        if self.shipper:
            self.shipper.configure()
        if self.radius:
            self.radius.open_sockets()
        self.conf_serial = self.store.get_meta('conf_serial', '0')
        if why:
            log('read the configuration again (%s)' % why)

    def changed(self, what=''):
        """Something the other processes (the command line) must notice."""
        try:
            # A mark of its own, not a count: two nodes counting up at the
            # same moment would write the same number, and neither would
            # see that the other changed something. (1.0.14)
            mark = '%.6f:%s' % (time.time(), node_name())
            self.store.set_meta('conf_serial', mark)
            self.conf_serial = mark
        except Exception:
            pass
        self.store._clients = None
        self.store._realms = None
        if what in ('directories', 'all'):
            self.reload_directories()

    # ---- settings ---------------------------------------------------------------
    def cluster_nodes(self):
        try:
            return [n['name'] for n in ha_nodes(self.store)]
        except Exception:                               # noqa: BLE001
            return [node_name()]

    def save_settings(self, changes, by='', node=None, drawn_by=None):
        checked = {}
        # The page's boxes were drawn by one node and the save reached
        # another through the web address (1.0.110): otp1 took otp2's name
        # from a page otp2 had drawn. What belongs to one machine is saved
        # only on the machine the page was drawn by.
        drawn_by = str(drawn_by or '').strip()
        if drawn_by and drawn_by != node_name():
            local = sorted(k for k in (changes or {}) if k in FILE_ONLY_KEYS and
                           not (k in SECRET_KEYS and is_masked(changes[k])))
            if local:
                raise NodeMoved('this page was drawn by %s, but %s answers now (the web address '
                                'moved): %s belongs to one machine, so nothing was saved - load '
                                'the page again' % (drawn_by, node_name(), ', '.join(local)))
            if node is None:
                node = drawn_by
        # In a cluster a node's own settings go to that node alone (1.0.37).
        many = bool(CONFIG.get('ha_mode')) or len(self.cluster_nodes()) > 1
        node = str(node or node_name())
        # '*': the cluster's own value of a node's setting (1.0.67) - the one
        # every node takes that has none of its own. It could not be changed
        # from the pages at all in a cluster.
        cluster_wide = node == '*'
        if cluster_wide:
            node = node_name()
        if node not in self.cluster_nodes() + [node_name()]:
            raise BadSetting('there is no node %s' % node)
        for key, value in (changes or {}).items():
            if key in SECRET_KEYS and is_masked(value):
                continue
            checked[key] = check_setting(key, value)
            # A secret kept in the database is sealed with the tokens' key
            # (1.0.20): a copy of the database alone does not give it away.
            if key in SEALED_KEYS and checked[key]:
                checked[key] = seal_secret(checked[key])
        if 'node_name' in checked:
            taken = node_name_taken(self.store, checked['node_name'])
            if taken:
                raise BadSetting('node_name: %s is the name of another node (%s, answering now) - '
                                 'two machines with one name look like one, and the other as '
                                 'gone' % (checked['node_name'], taken.get('address') or '?'))
        file_side = {k: v for k, v in checked.items() if k in FILE_ONLY_KEYS}
        if file_side and node != node_name() and not cluster_wide:
            raise NodeMoved('%s belongs to the machine %s and is saved on it (its own address), '
                            'not from %s' % (', '.join(sorted(file_side)), node, node_name()))
        db_side = {k: v for k, v in checked.items() if k not in FILE_ONLY_KEYS}
        saved_now = self.store.settings_saved()
        for k, v in db_side.items():
            if k in NODE_KEYS and many and not cluster_wide:
                shared = saved_now.get(k, FILE_CONFIG.get(k, DEFAULTS[k]))
                if v == shared:
                    self.store.drop_setting(k + '@' + node)
                else:
                    self.store.save_setting(k + '@' + node, v, by)
                continue
            if v == FILE_CONFIG.get(k, DEFAULTS[k]):
                self.store.drop_setting(k)
            else:
                self.store.save_setting(k, v, by)
        said = []
        if file_side:
            if any(k in DB_KEYS for k in file_side) and (
                    file_side.get('db_engine', CONFIG.get('db_engine')) != 'sqlite' or
                    CONFIG.get('db_engine') != 'sqlite'):
                test = dict(CONFIG)
                test.update(file_side)
                try:
                    probe = open_db(test)
                    probe.make_tables()
                    probe.close()
                except Exception as e:
                    raise BadSetting('the database could not be used, so nothing was '
                                     'changed: %s' % e)
            write_file_settings(file_side)
            said.append('the database settings go into %s and take effect when the service '
                        'is restarted (systemctl restart otp)' % CONFIG_FILE)
        # Who may sign in from the directory changed (1.0.33): everybody
        # signed in from it is signed out, so their role is decided again by
        # the groups as they are now - not kept until their session ends.
        if any(k in checked for k in ('admin_directory', 'admin_group_full',
                                      'admin_group_token', 'admin_group_readonly')):
            try:
                self.store.db.run(
                    "DELETE FROM sessions WHERE kind = 'admin' AND LOWER(name) IN "
                    "(SELECT LOWER(name) FROM accounts WHERE source = 'directory')")
            except Exception as e:                      # noqa: BLE001
                log('the directory sign-ins could not be ended: %s' % e, 'warn')
        if checked:
            self.store.add_event('settings', 'changed: %s' % ', '.join(
                '%s%s=%s' % (k, ('@' + node) if (k in NODE_KEYS and many and not cluster_wide)
                             else '',
                         '***' if k in SECRET_KEYS else json.dumps(v, ensure_ascii=False))
                for k, v in sorted(checked.items())), who=by)
        self.changed('settings')
        self.reload_all()
        return {'message': ' '.join(['%d setting(s) saved.' % len(checked)] + said),
                'saved': sorted(checked)}

    def settings_state(self, may_change=True):
        out = []
        saved = self.store.settings_saved()
        written = self.store.settings_written()
        for key in DEFAULTS:
            if key in ('ha_mode', 'ha_slot', 'ha_peer', 'ha_peer_port', 'ha_address', 'ha_tls',
                       'ha_tls_ca'):
                continue                    # the cluster's own wiring, set by its wizard
            value = CONFIG.get(key)
            shape = TUNABLE.get(key)
            source = 'saved' if key in saved else ('file' if key in FILE_KEYS else 'default')
            one = {'key': key, 'value': value, 'default': DEFAULTS[key],
                   'name': NAMES.get(key, key), 'says': SAYS.get(key, ''),
                   'secret': key in SECRET_KEYS, 'source': source,
                   'source_says': {'saved': 'saved on these pages',
                                   'file': 'from config.json',
                                   'default': 'the built-in default'}[source],
                   'in_file': key in FILE_KEYS,
                   'file': FILE_CONFIG.get(key) if key in FILE_KEYS else None,
                   'file_only': key in FILE_ONLY_KEYS,
                   'node_key': key in NODE_KEYS}
            if key in NODE_KEYS:
                one['per_node'] = {k.split('@', 1)[1]: v for k, v in saved.items()
                                   if k.startswith(key + '@')}
                one['shared'] = saved.get(key, FILE_CONFIG.get(key, DEFAULTS[key]))
                if key + '@' + node_name() in saved:
                    one['source'], one['source_says'] = 'node', 'saved for this node'
            if key in written:
                one['saved_at'] = written[key]['at']
                one['saved_by'] = written[key]['by']
            if key in SECRET_KEYS:
                plain = unseal_secret(value) if key in SEALED_KEYS else value
                one['value'] = secret_shown(plain or '') if may_change else ''
                one['set'] = bool(value)
                one['file'] = None
            if isinstance(shape, tuple) and shape and isinstance(shape[0], str):
                one['choices'] = list(shape)
                if key in CHOICE_WORDS:
                    one['choice_words'] = CHOICE_WORDS[key]
            elif isinstance(shape, tuple):
                one['min'], one['max'] = shape
            out.append(one)
        return out

    # ---- what it is doing ------------------------------------------------------
    def status(self):
        c = self.store.token_counts()
        last = self.store.db.row("SELECT ts, result, username FROM radius_log WHERE packet = "
                                 "'Access-Request' ORDER BY ts DESC LIMIT 1")
        day = time.time() - 86400
        acc = int(self.store.db.value("SELECT COUNT(*) AS n FROM radius_log WHERE ts >= ? AND "
                                      "result = 'accept'", (day,), 0) or 0)
        rej = int(self.store.db.value("SELECT COUNT(*) AS n FROM radius_log WHERE ts >= ? AND "
                                      "result IN ('reject', 'drop')", (day,), 0) or 0)
        serial = self.store.db.value('SELECT MAX(id) AS n FROM radius_log', (), 0) or 0
        ev = self.store.db.value('SELECT MAX(id) AS n FROM events', (), 0) or 0
        r = self.radius.state() if self.radius else {}
        problems = []
        if self.radius and self.radius.trouble:
            problems.append(self.radius.trouble)
        if self.radius and not self.radius.bound:
            problems.append('the RADIUS server is not listening')
        sh = self.shipper.state() if self.shipper else {}
        if sh.get('on') and not sh.get('targets'):
            problems.append('sending to isemon is on and nowhere to send to is set')
        if sh.get('trouble'):
            problems.extend('isemon %s: %s' % kv for kv in sorted(sh['trouble'].items()))
        lost = int(self.store.db.value('SELECT COUNT(*) AS n FROM tokens', (), 0) or 0) and \
            not sealing_key()
        if lost:
            problems.append('the key that opens the tokens (%s) is missing: no code can be '
                            'checked' % sealing_key_path())
        if name_clash_words():
            problems.insert(0, name_clash_words())
        if not self.store.clients():
            problems.append('there is no RADIUS client yet: nobody can ask this server')
        if not self.store.realms():
            problems.append('there is no realm yet: every request is refused')
        return {
            'ok': True, 'version': __version__, 'site': CONFIG.get('site_name') or short_host(),
            'host': socket.gethostname(), 'started': self.started,
            'uptime': time.time() - self.started, 'now': time.time(),
            'radius': r, 'isemon': sh, 'tokens': c,
            'clients': len(self.store.clients()), 'realms': len(self.store.realms()),
            'directories': len(self.dirs),
            'day': {'accept': acc, 'reject': rej},
            'last': last, 'serial': '%s/%s' % (serial, ev), 'problems': problems,
            'database': {'engine': self.store.db.engine, 'where': self.store.db.where()},
            'lang': CONFIG.get('ui_lang') or 'cs', 'php': php_state(), 'admin_show_key': bool(CONFIG.get('admin_show_key')),
            'default_realm': CONFIG.get('default_realm') or '',
            'node': node_name(),
            'nodes': [{'name': n['name'], 'alive': n['alive'], 'age': n['age'],
                       'version': n.get('version')} for n in ha_nodes(self.store)],
            'realm_suffixes': sorted(set(r['suffix'] for r in self.store.realms()
                                         if r.get('suffix') and r['suffix'] != '*')),
            # The overview's second row of cards (1.0.37): this server, the
            # cluster, the database, maintenance.
            'maintenance': maintenance_now(self.store),
            'maint_nodes': [n['name'] for n in ha_nodes(self.store)
                            if n.get('alive') and maintenance_row(self.store, n['name']).get('on')],
            'replication': self._repl_summary(),
            'db': self._db_summary(),
            'upgrade': self._upgrade_summary(),
        }

    def _repl_summary(self):
        if CONFIG.get('ha_mode') != 'replicated':
            return {'mode': CONFIG.get('ha_mode') or ''}
        try:
            r = ha_repl_state(self.store)
            return {'mode': 'replicated', 'healthy': bool(r.get('healthy')),
                    'lost': bool(r.get('lost')), 'trouble': r.get('trouble') or '',
                    'behind': max([int(x.get('behind') or 0) for x in r.get('outgoing') or []]
                                  or [0])}
        except Exception as e:                          # noqa: BLE001
            return {'mode': 'replicated', 'healthy': False, 'trouble': str(e)[:200]}

    DB_SUMMARY = {'at': 0, 'got': {}}

    def _db_summary(self):
        if time.time() - self.DB_SUMMARY['at'] > 60:
            got = {'engine': self.store.db.engine, 'where': self.store.db.where()}
            try:
                got['size'] = self.store.db.size()
            except Exception:                           # noqa: BLE001
                got['size'] = None
            try:
                kept = backups()
                got['backups'] = len(kept)
                # The nightly dumps count as a copy too (1.0.59): they are
                # kept in their own folder, and only the copies were looked at.
                try:
                    kept = kept + kept_dumps(self.store.db.engine)
                except Exception:                       # noqa: BLE001
                    pass
                got['last_backup'] = max([float(b.get('at') or b.get('mtime') or 0)
                                          for b in kept] or [0]) or None
            except Exception:                           # noqa: BLE001
                pass
            got['key_there'] = bool(sealing_key())
            self.DB_SUMMARY.update(at=time.time(), got=got)
        return self.DB_SUMMARY['got']

    def _upgrade_summary(self):
        try:
            plan = upgrade_plan(self.store)
            pkg = json.loads(self.store.get_meta('upgrade:pkg') or 'null')
        except Exception:                               # noqa: BLE001
            return {}
        return {'plan': {'state': plan['state'], 'version': plan['version']} if plan else None,
                'package': pkg['version'] if pkg else None}

    # ---- running -------------------------------------------------------------------
    def run(self):
        log('otp %s starting: the database is %s' % (__version__, self.store.db.where()))
        if not sealing_key():
            # A database that already holds sealed secrets gets no new key in
            # place of a missing one (1.0.33): the secrets would stay lost, and
            # on two nodes each would seal with a key of its own.
            held = 0
            try:
                held = int(self.store.db.value(
                    "SELECT COUNT(*) FROM tokens WHERE secret LIKE 'sealed:%'", (), 0) or 0)
            except Exception:                           # noqa: BLE001
                pass
            if held:
                log('%s is missing, and the database holds %d token(s) sealed with it: no new '
                    'key is made. Put the key back (it is beside every backup), or the tokens '
                    'cannot be opened.' % (sealing_key_path(), held), 'error')
                self.store.add_event('starting and stopping', 'the key that opens the tokens '
                                     'is missing: %s' % sealing_key_path(), 'bad')
            else:
                sealing_key(make=True)
        else:
            bind_tokens(self.store)
        if CONFIG.get('ha_mode') == 'replicated':
            # The other node's tables given the columns this version adds
            # (1.0.76): logical replication sends every column of a row, and
            # one the other node does not have yet stopped what goes to it
            # until it was upgraded too. Old code there never reads them.
            threading.Thread(target=ha_peer_columns, name='peer-columns', daemon=True).start()
        self.radius.start()
        self.api = ApiServer(self)
        self.api.start()
        HA_STORE['store'] = self.store
        node_name_check(self.store)             # renamed since the last start? (1.0.48)
        self.store.add_event('starting and stopping', 'otp %s started on %s, RADIUS on %s'
                             % (__version__, node_name(),
                                ', '.join(self.radius.bound) or 'nothing'))
        try:
            heartbeat(self.store, self)
        except Exception as e:                          # noqa: BLE001
            log('the heartbeat could not be written: %s' % e, 'warn')
        last_beat = time.monotonic()    # a clock stepped back stops nothing (1.0.94)
        maintenance_ensure(self.store)
        # Tests the other node's pages ask of this one (1.0.45): looked for
        # every half second, only while this node is one of a cluster.
        def tests_for_me():
            while not self.stop_flag.wait(1.5):
                if not CONFIG.get('ha_mode') or HA_REBUILDING.is_set():
                    continue
                try:
                    radtest_serve(self)
                except Exception as e:                  # noqa: BLE001
                    log('a test asked by the other node: %s' % e, 'warn')
                    self.stop_flag.wait(5)
        threading.Thread(target=tests_for_me, name='tests-for-me', daemon=True).start()

        # The outgoing mail (1.0.95): what was not taken yet, tried again.
        def mail_queue():
            while not self.stop_flag.wait(10):
                if HA_REBUILDING.is_set():
                    continue
                try:
                    mailq_tick(self.store)
                except Exception as e:                  # noqa: BLE001
                    log_sparing('mail-queue', 'the outgoing mail: %s' % e, 'warn', every=300)
        threading.Thread(target=mail_queue, name='mail-queue', daemon=True).start()
        # The cluster's web address: whether this node may hold it (1.0.47).
        threading.Thread(target=vip_watch, args=(self,), name='vip-watch', daemon=True).start()
        try:
            upgrade_tick(self)
        except Exception as e:                          # noqa: BLE001
            log('the upgrade: %s' % e, 'warn')
        signal.signal(signal.SIGTERM, lambda *_: self.stop_flag.set())
        signal.signal(signal.SIGINT, lambda *_: self.stop_flag.set())
        # Only noted in the handler (1.0.94): read again in this loop, not in
        # the middle of whatever the main thread was doing - a log line
        # holding its lock, a query on the connection - every night when
        # logrotate reloads.
        self.hup_asked = threading.Event()
        signal.signal(signal.SIGHUP, lambda *_: self.hup_asked.set())
        last_tidy = time.monotonic() - 3601
        last_backup_day = self.store.get_meta('backup_day', '')
        while not self.stop_flag.wait(5):
            if self.hup_asked.is_set():
                self.hup_asked.clear()
                self._hup()
            if HA_REBUILDING.is_set():
                continue                # nothing of its own written meanwhile (1.0.44)
            try:
                if time.monotonic() - last_beat >= HEARTBEAT_S:
                    last_beat = time.monotonic()
                    heartbeat(self.store, self)
                elif CONFIG.get('ha_mode'):
                    try:
                        fw_now_publish(self.store)  # asked by the other node's page (1.0.71)
                    except Exception:               # noqa: BLE001
                        pass
                if self.store.get_meta('conf_serial', '0') != self.conf_serial:
                    self.reload_all('changed elsewhere')
                try:
                    upgrade_tick(self)
                except Exception as e:                  # noqa: BLE001
                    log('the upgrade: %s' % e, 'warn')
                try:
                    web_tick(self.store)
                except Exception as e:                  # noqa: BLE001
                    log('TLS and the web address: %s' % e, 'warn')
                try:
                    rb_tick(self)               # backups to the destinations (1.0.109)
                except Exception as e:          # noqa: BLE001
                    log_sparing('rbackup-tick', 'the scheduled backup: %s' % e, 'warn', every=600)
                if CONFIG.get('ha_mode') == 'replicated':
                    hatls_tick(self.store)      # the link between the databases (1.0.104)
                    try:
                        readdress_tick(self.store, self)    # told a new address (1.0.106)
                    except Exception as e:      # noqa: BLE001
                        log('a new address of the cluster: %s' % e, 'warn')
                try:
                    lockouts_tick(self)         # who is locked out, for the pages (1.0.112)
                except Exception as e:          # noqa: BLE001
                    log_sparing('lockouts-tick', 'the list of who is locked out: %s' % e,
                                'warn', every=600)
                try:
                    ha_watch_tick(self.store)
                except Exception as e:                  # noqa: BLE001
                    log('the cluster\'s history: %s' % e, 'warn')
                if time.monotonic() - last_tidy > 3600:
                    last_tidy = time.monotonic()
                    # In a thread of its own (1.0.57): long directory lookups
                    # and a big first tidy held the heartbeat back, and the
                    # other node took this one for gone.
                    self.background('tidy', self.hourly)
                if CONFIG.get('backup_daily'):
                    today = datetime.now().strftime('%Y-%m-%d')
                    # 3:30 is 03:30 (1.0.44): compared as numbers, not as text.
                    try:
                        hh, mm = (int(x) for x in str(CONFIG.get('backup_at') or '03:30')
                                  .strip().split(':', 1))
                    except ValueError:
                        hh, mm = 3, 30
                    nw = datetime.now()
                    if today != last_backup_day and (nw.hour, nw.minute) >= (hh, mm):
                        # One node of a cluster makes it: the one whose
                        # conditional UPDATE took the day. (1.0.13) The day
                        # counts as done only once that was asked (1.0.94):
                        # a database away just then lost the day's copy.
                        mine = claim_once(self.store, 'backup_day' + (
                            ':' + node_name() if CONFIG.get('ha_mode') == 'replicated' else ''),
                            today)
                        last_backup_day = today
                    else:
                        mine = False
                    if mine:
                        self.background('dump', self.nightly)
            except DbError as e:
                # The database away is said once in a while, not with a
                # traceback every 5 seconds (1.0.59).
                log_sparing('housekeeping-db', 'housekeeping waits for the database: %s'
                            % str(e).split('\n')[0][:200], 'error', every=60)
            except Exception as e:
                log('housekeeping broke: %s\n%s' % (e, traceback.format_exc()), 'error')
        try:
            self.store.add_event('starting and stopping', 'otp stopped on %s' % node_name())
        except Exception:                               # noqa: BLE001
            pass                # the database away: the rest still stops cleanly (1.0.94)
        self.radius.stop()
        if self.shipper:
            self.shipper.flush()
        if self.api:
            self.api.stop()

    def background(self, name, fn):
        """`fn` in a thread of its own, never two of one name at once."""
        busy = getattr(self, '_bg', None)
        if busy is None:
            busy = self._bg = {}
        t = busy.get(name)
        if t is not None and t.is_alive():
            return
        t = threading.Thread(target=fn, name='otp-' + name, daemon=True)
        busy[name] = t
        t.start()

    def reader(self):
        """The database as the pages' long lists read it (1.0.101): the Log
        searched over months, the suggestions under a search box - on a
        connection of their own, with a limit of 20 s a statement. On the one
        every sign-in shares, four such searches at once held RADIUS for
        seconds and the health check failed."""
        main = self.store.db
        if main.engine == 'sqlite':
            return self.store
        with self._reader_lock:
            r = self._reader
            if r is not None and r.db.where() != main.where():
                try:
                    r.db.close()
                except Exception:                       # noqa: BLE001
                    pass
                r = self._reader = None
            if r is None:
                try:
                    r = self._reader = Storage.view(
                        db_open({k: CONFIG.get(k) for k in DB_KEYS}, statement_s=20))
                except Exception as e:                  # noqa: BLE001
                    log_sparing('reader-db', 'the lists of the pages read through the shared '
                                'connection: their own could not be opened (%s)'
                                % str(e).split('\n')[0][:200], 'warn')
                    return self.store
            return r

    def hourly(self):
        if CONFIG.get('ha_mode') == 'replicated' and self.store.db.engine == 'postgres':
            try:
                ha_sequences_check(self.store.db, int(CONFIG.get('ha_slot') or 1))
            except Exception as e:                      # noqa: BLE001
                log('the numbering of the tables could not be checked: %s' % e, 'warn')
            # The other node's columns again (1.0.94): tried once at start, a
            # peer away just then kept replication to it stalled until its
            # own upgrade. Adding what is there already does nothing.
            ha_peer_columns()
            # A table the other node has and this node's subscription does
            # not take yet - one a later version added, the two nodes
            # upgraded by hand - taken from now on (1.0.101).
            try:
                db = self.store.db
                sub = ha_sub_here(db, 3 - int(CONFIG.get('ha_slot') or 1))
                if sub and int(db.value('SELECT COUNT(*) FROM pg_subscription_rel r JOIN '
                                        'pg_subscription s ON s.oid = r.srsubid WHERE '
                                        's.subname = ?', (sub,)) or 0) < len(TABLES):
                    db.run(RawSql('ALTER SUBSCRIPTION %s REFRESH PUBLICATION WITH '
                                  '(copy_data = false)' % sub))
            except Exception as e:                      # noqa: BLE001
                log('the tables taken from the other node could not be read again: %s'
                    % str(e).split('\n')[0][:200], 'info')
        try:
            chal_tidy(self.store)                       # codes asked for and gone (1.0.76)
        except Exception as e:                          # noqa: BLE001
            log('the old challenges could not be tidied: %s' % e, 'warn')
        try:
            once_tidy(self.store)                       # used once, long ago (1.0.101)
        except Exception as e:                          # noqa: BLE001
            log('the codes used once could not be tidied: %s' % e, 'warn')
        try:
            self.fill_names(limit=100)
        except Exception as e:                          # noqa: BLE001
            log('names from the directory: %s' % e, 'warn')
        try:
            # One node of two deletes the old rows; the deletes go over to the
            # other anyway (1.0.57).
            if CONFIG.get('ha_mode') == 'replicated' and not claim_once(
                    self.store, 'tidy_hour', time.strftime('%Y-%m-%d %H')):
                return
            gone = self.store.tidy()
            if any(gone.values()):
                log('tidied: %s' % gone)
        except Exception as e:                          # noqa: BLE001
            log('tidying broke: %s' % e, 'warn')

    def nightly(self):
        try:
            # As isemon's: the engine's own dump every night, or a portable
            # copy where its program is missing.
            make_dump(self.store, 'daily')
        except Exception as e:                          # noqa: BLE001
            self.store.add_event('backups', 'the daily dump failed: %s' % e, 'bad')
        try:
            note_size(self.store)
        except Exception:                               # noqa: BLE001
            pass

    def _hup(self):
        log_open()
        try:
            self.reload_all('SIGHUP')
        except Exception as e:
            log('reading the configuration again failed: %s' % e, 'error')


# ---------------------------------------------------------------------------
# Moving to another database, looking after the one in use, tuning its
# server - the database page, as isemon has it
# ---------------------------------------------------------------------------
ENGINE_WORDS = {'sqlite': 'the file on this machine (SQLite)', 'mariadb': 'MariaDB',
                'postgres': 'PostgreSQL'}
# DB_KEYS is 00_head's (1.0.94): a second one here, without db_tls and
# db_tls_ca, left the database's TLS out of the test before a save, of the
# cluster's bundle and of the move to another database.
DB_IDENT = re.compile(r'[A-Za-z_][A-Za-z0-9_]{0,62}\Z')


def file_db_settings():
    """The database settings as config.json has them now - Set it up writes
    the address and the password made there while the old database is
    still the one in use, and the steps after it must find them (1.0.37)."""
    try:
        with open(str(CONFIG_FILE), encoding='utf-8') as f:
            got = json.load(f)
        return {k: got[k] for k in DB_KEYS if k in got} if isinstance(got, dict) else {}
    except (OSError, ValueError):
        return {}


def engine_asked(given):
    """The database the page means: what it typed, over what is set."""
    c = {k: CONFIG.get(k) for k in DB_KEYS}
    on_file = file_db_settings()
    for k, v in on_file.items():
        if k != 'db_engine':
            c[k] = v
    for k, v in (given or {}).items():
        if k not in DB_KEYS or v is None:
            continue
        if k == 'db_password' and is_masked(v):
            continue
        c[k] = v
    if c.get('db_engine') not in ('sqlite', 'mariadb', 'postgres'):
        raise ValueError('the engine is sqlite, mariadb or postgres')
    for k in ('db_name', 'db_user'):
        if c['db_engine'] != 'sqlite' and not DB_IDENT.match(str(c.get(k) or '')):
            raise ValueError('%s is letters, digits and _ only, starting with a letter' % k)
    return c


def db_open(c, statement_s=None):
    return Db(c.get('db_engine') or 'sqlite', c.get('db_host') or '', c.get('db_port') or 0,
              c.get('db_name') or 'otp', c.get('db_user') or 'otp', c.get('db_password') or '',
              c.get('db_timeout_s') or 10,
              tls=c.get('db_tls') if 'db_tls' in c else CONFIG.get('db_tls'),
              tls_ca=c.get('db_tls_ca') if 'db_tls_ca' in c else CONFIG.get('db_tls_ca'),
              statement_s=statement_s)


def db_own(store, statement_s=0):
    """A connection of its own to the database in use, for a long job
    (1.0.101): a VACUUM FULL, a check of every table - on the one every
    sign-in shares, each held them all for as long as it took. SQLite has
    one file and one connection: that one. Closed by the caller."""
    if store.db.engine == 'sqlite':
        return None
    return db_open({k: CONFIG.get(k) for k in DB_KEYS}, statement_s=statement_s)


def same_database(c, db):
    """Whether the page's database is the one in use."""
    if c.get('db_engine') != db.engine:
        return False
    if db.engine == 'sqlite':
        return True
    port = int(c.get('db_port') or {'mariadb': 3306, 'postgres': 5432}[db.engine])
    here = {'', 'localhost', '127.0.0.1', '::1'}
    a, b = str(c.get('db_host') or '').lower(), str(db.host or '').lower()
    return ((a == b or (a in here and b in here)) and port == int(db.port or port)
            and str(c.get('db_name')) == str(db.name))


def db_try(c):
    """Reach a database as this program would. Never raises."""
    out = {'reached': False, 'engine': c.get('db_engine'),
           'words': ENGINE_WORDS.get(c.get('db_engine'), c.get('db_engine'))}
    try:
        db = db_open(c)
    except Exception as e:
        out['trouble'] = str(e).split('\n')[0][:300]
        return out
    try:
        out['reached'] = True
        out['where'] = db.where()
        out['version'] = db.version()
        names = db.tables()
        ours = [t for t in TABLES if t in names]
        out['tables'] = ours
        out['rows'] = sum(int(db.value('SELECT COUNT(*) FROM %s' % t) or 0)
                          for t in ours if t not in ('meta',))
        try:
            db.run('CREATE TABLE otp_probe (x INTEGER)')
            db.run('DROP TABLE otp_probe')
            out['writable'] = True
        except Exception as e:
            out['writable'] = False
            out['trouble'] = 'it answers, but this account may not make a table: %s' % (
                str(e).split('\n')[0][:200])
    except Exception as e:
        out['trouble'] = str(e).split('\n')[0][:300]
    finally:
        db.close()
    return out


def db_password_made():
    alphabet = 'abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join(secrets.choice(alphabet) for _ in range(24))


def db_make(c, admin_user, admin_password):
    """The database and its account, made by an administrator of that
    server who is used for this one connection and kept nowhere."""
    eng = c['db_engine']
    host = str(c.get('db_host') or '127.0.0.1')
    port = int(c.get('db_port') or {'mariadb': 3306, 'postgres': 5432}[eng])
    name, user, pw = c['db_name'], c['db_user'], c['db_password']
    done = []
    if eng == 'mariadb':
        import pymysql
        conn = pymysql.connect(host=host, port=port, user=admin_user, password=admin_password,
                               connect_timeout=int(c.get('db_timeout_s') or 10), autocommit=True)
        try:
            cur = conn.cursor()
            cur.execute('CREATE DATABASE IF NOT EXISTS `%s` CHARACTER SET utf8mb4 '
                        'COLLATE utf8mb4_unicode_ci' % name)
            done.append('the database %s' % name)
            local = host in ('localhost', '127.0.0.1', '::1')
            for at in (('localhost', '127.0.0.1') if local else ('%',)):
                cur.execute("CREATE USER IF NOT EXISTS %s@%s IDENTIFIED BY %s", (user, at, pw))
                cur.execute("ALTER USER %s@%s IDENTIFIED BY %s", (user, at, pw))
                cur.execute('GRANT ALL PRIVILEGES ON `%s`.* TO %%s@%%s' % name, (user, at))
                done.append("the account '%s'@'%s', with every right on %s and none elsewhere"
                            % (user, at, name))
            cur.execute('FLUSH PRIVILEGES')
        finally:
            conn.close()
        return done
    import psycopg2
    conn = psycopg2.connect(host=host, port=port, user=admin_user, password=admin_password,
                            dbname='postgres', connect_timeout=int(c.get('db_timeout_s') or 10))
    conn.autocommit = True
    try:
        cur = conn.cursor()
        cur.execute('SELECT 1 FROM pg_roles WHERE rolname = %s', (user,))
        if cur.fetchone():
            cur.execute('ALTER ROLE "%s" WITH LOGIN PASSWORD %%s' % user, (pw,))
            done.append('the account %s was there; its password is new' % user)
        else:
            cur.execute('CREATE ROLE "%s" WITH LOGIN PASSWORD %%s' % user, (pw,))
            done.append('the account %s' % user)
        cur.execute('SELECT 1 FROM pg_database WHERE datname = %s', (name,))
        if cur.fetchone():
            cur.execute('ALTER DATABASE "%s" OWNER TO "%s"' % (name, user))
            done.append('the database %s was there; %s owns it now' % (name, user))
        else:
            cur.execute("CREATE DATABASE \"%s\" OWNER \"%s\" ENCODING 'UTF8' TEMPLATE template0"
                        % (name, user))
            done.append('the database %s, owned by %s' % (name, user))
    finally:
        conn.close()
    conn = psycopg2.connect(host=host, port=port, user=admin_user, password=admin_password,
                            dbname=name, connect_timeout=int(c.get('db_timeout_s') or 10))
    conn.autocommit = True
    try:
        conn.cursor().execute('GRANT ALL ON SCHEMA public TO "%s"' % user)
    except Exception:
        pass
    finally:
        conn.close()
    return done


def db_empty(c):
    db = db_open(c)
    try:
        gone = []
        for t in reversed(TABLES):
            if t in db.tables():
                db.run('DROP TABLE %s' % t)
                gone.append(t)
        return gone
    finally:
        db.close()


# ---- one long job at a time, which the page asks after ---------------------
DB_JOB = {'id': 0, 'what': '', 'running': False, 'done': 0, 'whole': 0, 'says': '',
          'error': '', 'result': None, 'began': 0, 'ended': 0}
DB_JOB_LOCK = threading.Lock()


def db_job(what, work):
    with DB_JOB_LOCK:
        if DB_JOB['running']:
            raise ValueError('%s is going on already' % DB_JOB['what'])
        DB_JOB.update({'id': DB_JOB['id'] + 1, 'what': what, 'running': True, 'done': 0,
                       'whole': 0, 'says': '', 'error': '', 'result': None,
                       'began': time.time(), 'ended': 0})

    def progress(done, whole, says):
        DB_JOB.update({'done': done, 'whole': whole, 'says': says})
        if time.time() - DB_JOB.get('_pub', 0) > 1:
            DB_JOB['_pub'] = time.time()
            job_publish({k: v for k, v in DB_JOB.items() if not k.startswith('_')})

    def run():
        try:
            DB_JOB['result'] = work(progress)
        except Exception as e:
            DB_JOB['error'] = scrub_secret(str(e).split('\n')[0][:400])
            log('%s failed: %s' % (what, scrub_secret(e)), 'error')
        finally:
            DB_JOB.update({'running': False, 'ended': time.time()})
            job_publish({k: v for k, v in DB_JOB.items() if not k.startswith('_')})

    def beat():
        # Said again every half minute, so the other node - or this one,
        # after a restart - can tell a job going on from one that died.
        while DB_JOB.get('running'):
            time.sleep(30)
            if DB_JOB.get('running'):
                job_publish({k: v for k, v in DB_JOB.items() if not k.startswith('_')})

    threading.Thread(target=run, name='db-job', daemon=True).start()
    threading.Thread(target=beat, name='db-job-beat', daemon=True).start()
    return dict(DB_JOB)


def db_move(store, c, by):
    """Everything here into the other database, through a copy."""
    def work(progress):
        progress(0, 0, 'making a copy of what is here')
        before = store.counts()
        copy = make_backup(store, 'before moving, by %s' % by)
        whole = sum(before.values())
        far = db_open(c)
        tally = {}
        try:
            def along(table, done):
                tally[table] = done
                progress(sum(tally.values()), whole, '%s: %s' % (table, done))
            load_tables(far, copy, say=along)
            after = {t: int(far.value('SELECT COUNT(*) FROM %s' % t) or 0)
                     for t in TABLES if t != 'meta'}
        finally:
            far.close()
        short = {t: (before.get(t, 0), after.get(t, 0)) for t in after
                 if after.get(t, 0) < before.get(t, 0) and t not in ('sessions',)}
        store.add_event('settings', 'everything was carried into %s (%s), by %s'
                        % (ENGINE_WORDS.get(c['db_engine']), db_where(c), by), who=by)
        progress(whole, whole, 'done')
        return {'copy': copy.name, 'rows': sum(after.values()), 'short': short,
                'where': db_where(c)}
    return db_job('carrying everything across', work)


def db_where(c):
    if c.get('db_engine') == 'sqlite':
        return str(DB_FILE)
    return '%s@%s:%s/%s' % (c.get('db_user'), c.get('db_host') or 'localhost',
                            c.get('db_port') or {'mariadb': 3306, 'postgres': 5432}
                            [c['db_engine']], c.get('db_name'))


# ---- looking after the one in use --------------------------------------------
def db_table_sizes(db):
    """Rows and bytes of every table, as far as the engine says."""
    out = []
    sizes = {}
    try:
        if db.engine == 'mariadb':
            for r in db.rows('SELECT TABLE_NAME AS t, DATA_LENGTH + INDEX_LENGTH AS b, '
                             'DATA_FREE AS f FROM information_schema.TABLES '
                             'WHERE TABLE_SCHEMA = DATABASE()'):
                sizes[r['t']] = (int(r['b'] or 0), int(r['f'] or 0))
        elif db.engine == 'postgres':
            for t in TABLES:
                sizes[t] = (int(db.value('SELECT pg_total_relation_size(?)', (t,)) or 0), 0)
        else:
            try:
                for r in db.rows('SELECT name AS t, SUM(pgsize) AS b FROM dbstat GROUP BY name'):
                    sizes[r['t']] = (int(r['b'] or 0), 0)
            except Exception:
                pass
    except Exception:
        pass
    for t in TABLES:
        try:
            n = int(db.value('SELECT COUNT(*) FROM %s' % t) or 0)
        except Exception:
            n = 0
        b, free = sizes.get(t, (None, 0))
        out.append({'table': t, 'rows': n, 'bytes': b, 'free': free})
    return out


def db_free_inside(db):
    """Room the engine holds that it would give back to the disk."""
    try:
        if db.engine == 'sqlite':
            pages = int(db.value('PRAGMA freelist_count') or 0)
            return pages * int(db.value('PRAGMA page_size') or 4096)
        if db.engine == 'mariadb':
            return int(db.value('SELECT SUM(DATA_FREE) FROM information_schema.TABLES '
                                'WHERE TABLE_SCHEMA = DATABASE()') or 0)
        return int(db.value('SELECT COALESCE(SUM(n_dead_tup), 0) FROM pg_stat_user_tables') or 0)
    except Exception:
        return 0


def db_check(db):
    """Read the database through and say whether anything is broken."""
    said = []
    if db.engine == 'sqlite':
        got = [r for r in db.rows('PRAGMA integrity_check')]
        words = [list(r.values())[0] for r in got]
        return {'ok': words == ['ok'], 'said': words[:20]}
    if db.engine == 'mariadb':
        ok = True
        for t in TABLES:
            for r in db.rows('CHECK TABLE %s' % t):
                v = {k.lower(): x for k, x in r.items()}
                if str(v.get('msg_type')).lower() in ('error', 'warning') or \
                        str(v.get('msg_text')).lower() not in ('ok', 'table is already up to date'):
                    ok = False
                    said.append('%s: %s' % (t, v.get('msg_text')))
        return {'ok': ok, 'said': said or ['every table: OK']}
    ok = True
    for t in TABLES:
        try:
            n = db.value('SELECT COUNT(*) FROM %s' % t)
            said.append('%s: %s row(s) read' % (t, n))
        except Exception as e:
            ok = False
            said.append('%s: %s' % (t, str(e).split('\n')[0]))
    return {'ok': ok, 'said': said}


def db_statistics(db):
    """Fresh statistics for the planner - quick, nothing is locked."""
    if db.engine == 'sqlite':
        db.run('ANALYZE')
        db.run('PRAGMA optimize')
    elif db.engine == 'mariadb':
        for t in TABLES:
            db.rows('ANALYZE TABLE %s' % t)
    else:
        db.run('ANALYZE')
    return 'the statistics of every table are fresh'


def db_give_back(store, progress):
    """Give the room deleted rows left back to the disk: VACUUM, OPTIMIZE
    TABLE, VACUUM FULL. Each holds a table shut while it works."""
    own = db_own(store)
    try:
        return _db_give_back(own or store.db, progress)
    finally:
        if own:
            own.close()


def _db_give_back(db, progress):
    before = db.size()
    if db.engine == 'sqlite':
        progress(0, 1, 'VACUUM')
        db.run('PRAGMA wal_checkpoint(TRUNCATE)')
        db.run('VACUUM')
        db.run('PRAGMA wal_checkpoint(TRUNCATE)')
    else:
        for i, t in enumerate(TABLES):
            progress(i, len(TABLES), t)
            if db.engine == 'mariadb':
                db.rows('OPTIMIZE TABLE %s' % t)
            else:
                db.run('VACUUM (FULL, ANALYZE) %s' % t)
    after = db.size()
    progress(1, 1, 'done')
    return {'before': before, 'after': after}


def db_prune(store, days):
    """Forget the requests and the checks of a code older than `days`."""
    edge = time.time() - int(days) * 86400 if int(days) > 0 else time.time() + 86400
    gone = {}
    for t in ('radius_log', 'otp_log'):
        # In batches (1.0.57): one DELETE of millions of rows held RADIUS -
        # and the health check the web address follows - for minutes.
        gone[t] = store.delete_older(t, edge)
    return gone


# ---- the server's own settings, for its machine (isemon's DbTune, smaller) --
def tune_machine(c, typed):
    """What the database server's machine has: read here when it is this
    machine, typed on the page when it is not."""
    host = str(c.get('db_host') or '').lower()
    local = host in ('', 'localhost', '127.0.0.1', '::1') or host == socket.gethostname().lower()
    facts = {'local': local, 'ram_gb': None, 'cpus': None, 'disk': None, 'avail': None,
             'ram': None, 'virtual': None, 'rotational': None,
             'source': 'this machine' if local else ''}
    if local:
        try:
            with open('/proc/meminfo') as f:
                for line in f:
                    if line.startswith('MemTotal:'):
                        facts['ram'] = int(line.split()[1]) * 1024
                    elif line.startswith('MemAvailable:'):
                        facts['avail'] = int(line.split()[1]) * 1024
            if facts['ram']:
                facts['ram_gb'] = round(facts['ram'] / 1073741824.0, 1)
        except OSError:
            pass
        facts['cpus'] = os.cpu_count()
        try:
            with open('/proc/cpuinfo') as f:
                facts['virtual'] = ' hypervisor' in f.read()
        except OSError:
            pass
        try:
            rot = [open(p).read().strip() for p in
                   [str(x) for x in Path('/sys/block').glob('*/queue/rotational')]
                   if not re.search(r'/(loop|ram|zram|sr|dm-)\d', p)]
            if rot:
                facts['rotational'] = all(r == '1' for r in rot)
        except OSError:
            pass
    for k in ('ram_gb', 'cpus'):
        if typed.get(k) not in (None, ''):
            try:
                v = float(str(typed[k]).replace(',', '.')) if k == 'ram_gb' else int(typed[k])
            except ValueError:
                raise ValueError('the memory is a number of GB, the processors a whole number')
            if k == 'ram_gb' and facts['ram_gb'] and abs(v - facts['ram_gb']) > 0.05 * v:
                facts['source'] = 'typed' if not local else facts['source']
            if k == 'cpus' and v != facts['cpus'] and not local:
                facts['source'] = 'typed'
            facts[k] = v
            if k == 'ram_gb':
                facts['ram'] = int(v * 1073741824)
    return facts


def tune_commit_ms(db):
    """How long the server takes to make one small write safe: the middle of
    twenty, each its own transaction, less a round trip."""
    if db.engine == 'sqlite':
        return None
    took, trip = [], []
    # A row of this node's own (1.0.59): two nodes measuring at once wrote
    # the same key, and replication stopped on the duplicate.
    probe = 'tune_probe:' + node_name()
    try:
        # The row is there to be written (1.0.44): an UPDATE of nothing
        # commits nothing and every disk looked fast.
        db.run('DELETE FROM meta WHERE k = ?', (probe,))
        db.run('INSERT INTO meta (k, v) VALUES (?, ?)', (probe, '0'))
        for _ in range(5):
            t = time.perf_counter()
            db.value('SELECT 1')
            trip.append(time.perf_counter() - t)
        for i in range(20):
            t = time.perf_counter()
            db.run('UPDATE meta SET v = ? WHERE k = ?', (str(i), probe))
            took.append(time.perf_counter() - t)
        db.run('DELETE FROM meta WHERE k = ?', (probe,))
    except Exception:                                   # noqa: BLE001
        return None
    took.sort()
    trip.sort()
    return max(0.0, (took[len(took) // 2] - trip[len(trip) // 2]) * 1000.0)


def tune_disk_guess(facts, commit_ms):
    """As isemon's: what the disk says of itself first - except in a virtual
    machine, where a disk says it spins whatever it is on - then how long a
    small write takes to be made safe."""
    rot = facts.get('rotational')
    if rot is False:
        return 'ssd', 'the disk says it does not spin'
    if rot is True and not facts.get('virtual'):
        return 'hdd', 'the disk says it spins'
    if commit_ms is not None:
        if commit_ms < 2.5:
            return 'ssd', 'a write is made safe in %.1f ms, which is an SSD' % commit_ms
        if commit_ms > 6:
            return 'hdd', 'a write is made safe in %.1f ms, which is a disk that spins' % commit_ms
    return 'ssd', ('not known for certain - most servers are on SSDs now; choose the other if '
                   'this one is not')


def _mb(n):
    n = int(n)
    return '%dGB' % (n // 1024) if n >= 1024 and n % 1024 == 0 else '%dMB' % n


def tune_plan(engine, m):
    """name -> (value, why, needs_restart)"""
    ram = int((m.get('ram_gb') or 4) * 1024)
    cpus = max(1, int(m.get('cpus') or 2))
    ssd = (m.get('disk') or 'ssd') == 'ssd'
    # Shared with otp itself (and nginx, PHP) when it is this machine.
    share = 0.8 if m.get('local') else 1.0
    if engine == 'postgres':
        sb = max(128, min(int(ram * share / 4), 16384))
        return {
            'shared_buffers': (_mb(sb), 'a quarter of the memory: the server’s own cache', True),
            'effective_cache_size': (_mb(int(ram * share * 3 / 4)),
                                     'how much the planner may assume is cached', False),
            'maintenance_work_mem': (_mb(max(64, min(ram // 16, 2048))),
                                     'for VACUUM and building indexes', False),
            'work_mem': (_mb(max(4, min(ram // 256, 64))), 'for each sort and hash', False),
            'wal_buffers': ('16MB', 'the write-ahead log’s buffer', True),
            'max_wal_size': ('4GB' if ssd else '2GB', 'fewer checkpoints under load', False),
            'min_wal_size': ('1GB', 'kept between checkpoints', False),
            'checkpoint_completion_target': ('0.9', 'checkpoints spread out', False),
            'random_page_cost': ('1.1' if ssd else '4', 'an SSD reads anywhere as fast', False),
            'effective_io_concurrency': ('200' if ssd else '2', 'reads the disk takes at once', False),
            'max_worker_processes': (str(max(8, cpus)), 'one per processor', True),
            'max_parallel_workers': (str(cpus), 'parallel queries over every processor', False),
            'max_parallel_workers_per_gather': (str(max(1, min(4, cpus // 2))),
                                                'per query', False),
        }
    pool = max(128, int(ram * share * (0.5 if m.get('local') else 0.7)) // 128 * 128)
    return {
        'innodb_buffer_pool_size': (str(pool * 1048576), 'the server’s own cache: %s'
                                    % _mb(pool), False),
        'innodb_log_file_size': (str(min(pool // 4, 2048) * 1048576),
                                 'a log large enough for a busy hour', True),
        'innodb_flush_method': ('O_DIRECT', 'no second copy in the system’s cache', True),
        'innodb_io_capacity': ('2000' if ssd else '200', 'what the disk takes per second', False),
        'innodb_io_capacity_max': ('4000' if ssd else '400', '...at most', False),
        'innodb_flush_neighbors': ('0' if ssd else '1', 'an SSD has no neighbours', False),
        'tmp_table_size': (str(64 * 1048576), 'in-memory temporary tables', False),
        'max_heap_table_size': (str(64 * 1048576), '...the same', False),
        'table_open_cache': ('2000', 'tables kept open', False),
    }


def tune_current(db, names):
    out = {}
    for n in names:
        try:
            if db.engine == 'postgres':
                out[n] = str(db.value('SHOW %s' % n))
            else:
                r = db.row("SHOW GLOBAL VARIABLES LIKE ?", (n,))
                out[n] = str(list(r.values())[1]) if r else ''
        except Exception:
            out[n] = ''
    return out


def tune_same(engine, a, b):
    def norm(v):
        v = str(v).strip()
        m = re.match(r'^(\d+(?:\.\d+)?)\s*(kB|MB|GB|TB)?\Z', v, re.I)
        if not m:
            return v.lower()
        mult = {'kb': 1, 'mb': 1024, 'gb': 1048576, 'tb': 1073741824}.get(
            (m.group(2) or '').lower(), None)
        return float(m.group(1)) * mult if mult else float(m.group(1))
    try:
        x, y = norm(a), norm(b)
        if isinstance(x, float) and isinstance(y, float) and max(x, y) >= 1024:
            # Memory: within a tenth is the same - what is free moves from one
            # look to the next, and a setting is not changed for that.
            return abs(x - y) <= 0.1 * max(x, y)
        return x == y
    except Exception:
        return str(a) == str(b)


def tune_connect(store, admin_user, admin_password):
    """The server, as an administrator when one is given, else as ourselves."""
    c = {k: CONFIG.get(k) for k in DB_KEYS}
    if admin_user:
        c['db_user'], c['db_password'] = admin_user, admin_password
        if c['db_engine'] == 'postgres':
            pass
    return db_open(c) if admin_user else store.db


def tune_last(store):
    try:
        return json.loads(store.get_meta('tune_last:' + node_name()) or 'null')
    except ValueError:
        return None


def tune_pending(db):
    if db.engine != 'postgres':
        return []
    try:
        return [r['name'] for r in db.rows('SELECT name FROM pg_settings WHERE pending_restart')]
    except Exception:                                   # noqa: BLE001
        return []


def tune_plan_for(store, typed, probe=True):
    db = store.db
    if db.engine == 'sqlite':
        raise ValueError('the file on this machine has no server to tune: this program sets '
                         'it up itself')
    c = {k: CONFIG.get(k) for k in DB_KEYS}
    typed = typed or {}
    m = tune_machine(c, typed)
    commit_ms = tune_commit_ms(db) if probe else None
    disk, why = tune_disk_guess(m, commit_ms)
    if typed.get('disk') in ('ssd', 'hdd') and typed['disk'] != disk:
        disk, why = typed['disk'], 'chosen'
    m['disk'], m['why'], m['commit_ms'] = disk, why, commit_ms
    out = {'engine': db.engine, 'words': ENGINE_WORDS.get(db.engine), 'where': db.where(),
           'version': str(db.version() or '').split(' on ')[0].split(',')[0],
           'size': int(db.size() or 0), 'machine': m, 'facts': m,
           'restart': tune_restart_ready(store), 'last': tune_last(store), 'rows': [],
           'items': []}
    try:
        if db.engine == 'postgres':
            out['connections'] = int(db.value('SHOW max_connections') or 0)
        else:
            r = db.row("SHOW GLOBAL VARIABLES LIKE 'max_connections'")
            out['connections'] = int(list(r.values())[1]) if r else 0
    except Exception:                                   # noqa: BLE001
        pass
    if not m.get('ram_gb') or not m.get('cpus'):
        out['need_facts'] = True
        return out
    plan = tune_plan(db.engine, m)
    now = tune_current(db, plan.keys())
    pending = set(tune_pending(db))
    last = out['last'] or {}
    mine = last.get('engine') == db.engine and not last.get('undone') \
        and last.get('where') == db.where()
    put = (last.get('set') or {}) if mine else {}
    rows = []
    for n, (v, why_, rs) in plan.items():
        same = tune_same(db.engine, now.get(n, ''), v)
        row = {'name': n, 'now': now.get(n, ''), 'want': v, 'why': why_, 'restart': rs,
               'takes': 'at the next start' if rs else 'at once', 'same': same,
               'change': not same, 'pending': n in pending}
        if n in pending and n in put and tune_same(db.engine, put[n], v):
            row.update(change=False, waiting=True)
        rows.append(row)
    out['rows'] = out['items'] = rows
    if db.engine == 'mariadb':
        out['snippet'] = out['cnf'] = (
            '# Written by otp %s for this machine, as zz-otp-tuning.cnf in /etc/my.cnf.d/\n'
            '# (or /etc/mysql/mariadb.conf.d/) so that the settings outlast a restart.\n'
            '[mariadb]\n' % __version__) + ''.join('%s = %s\n' % (r['name'], r['want'])
                                                    for r in rows)
    return out


def tune_apply(store, typed, admin_user, admin_password, by):
    plan = tune_plan_for(store, typed, probe=False)
    if plan.get('need_facts'):
        raise ValueError('say what the machine has first: its memory and its processors')
    db = tune_connect(store, admin_user, admin_password)
    done, later, failed = [], [], []
    before = json.loads(store.get_meta('tune_before:' + node_name()) or '{}')
    try:
        for r in plan['rows']:
            if not r['change']:
                continue
            before.setdefault(r['name'], r['now'])
            try:
                if plan['engine'] == 'postgres':
                    db.run("ALTER SYSTEM SET %s = '%s'" % (r['name'], r['want'].replace("'", '')))
                    (later if r['restart'] else done).append(r['name'])
                else:
                    if r['restart']:
                        later.append(r['name'])
                        continue
                    db.run('SET GLOBAL %s = %s' % (r['name'], r['want'] if r['want'].isdigit()
                                                  else "'%s'" % r['want']))
                    done.append(r['name'])
            except Exception as e:
                failed.append('%s: %s' % (r['name'], str(e).split('\n')[0][:160]))
        if plan['engine'] == 'postgres' and (done or later):
            db.run('SELECT pg_reload_conf()')
    finally:
        if db is not store.db:
            db.close()
    store.set_meta('tune_before:' + node_name(), json.dumps(before))
    if done or later:
        store.set_meta('tune_last:' + node_name(), json.dumps({
            'engine': plan['engine'], 'where': store.db.where(), 'at': time.time(), 'by': by,
            'set': {r['name']: r['want'] for r in plan['rows'] if r['name'] in done + later},
            'undone': 0}))
    store.add_event('settings', 'the database server was tuned for its machine by %s: %s'
                    % (by, ', '.join(done + later) or 'nothing'), 'warn', who=by)
    plan2 = tune_plan_for(store, typed, probe=False)
    plan2.update({'done': done, 'later': later, 'failed': failed})
    return plan2


TUNE_RESTART_MARK = CONFIG_FILE.parent / 'may-restart-database'


def tune_restart_unit():
    """The postgresql service on this machine, as systemd knows it, or ''."""
    try:
        said = subprocess.run(['systemctl', 'list-units', '--type=service', '--all', '--plain',
                               '--no-legend', '--no-pager', 'postgresql*'],
                              capture_output=True, text=True, timeout=10)
    except (OSError, subprocess.SubprocessError):
        return ''
    found = []
    for line in said.stdout.splitlines():
        f = line.split()
        if len(f) >= 3 and f[2] == 'active' and \
                re.match(r'^postgresql(-\d+)?(@[\w.-]+)?\.service\Z', f[0]):
            found.append(f[0])
    return found[0] if len(found) == 1 else ''


def tune_restart_ready(store):
    db = store.db
    if db.engine != 'postgres':
        return {'may': False, 'unit': ''}
    host = str(CONFIG.get('db_host') or '').lower()
    if host not in ('', 'localhost', '127.0.0.1', '::1', socket.gethostname().lower()):
        return {'may': False, 'unit': 'postgresql',
                'why': 'PostgreSQL runs on another machine, which this program cannot restart'}
    unit = tune_restart_unit()
    if not unit:
        return {'may': False, 'unit': 'postgresql',
                'why': 'no single running postgresql service was found on this machine'}
    if not TUNE_RESTART_MARK.exists():
        return {'may': False, 'unit': unit,
                'why': 'install.sh has not let this program restart it (run install.sh --upgrade '
                       'without --no-db-restart)'}
    return {'may': True, 'unit': unit, 'why': ''}


def tune_restart(store, by):
    """PostgreSQL on this machine started again, for the settings that take
    only at a start - through systemd, where install.sh let this account do
    that - and waited for."""
    db = store.db
    ready = tune_restart_ready(store)
    if db.engine != 'postgres' or not ready['unit']:
        raise ValueError('no database server is running as a service on this machine')
    unit = ready['unit']
    if not TUNE_RESTART_MARK.exists():
        raise ValueError('this program may not restart %s: run  systemctl restart %s  as root'
                         % (unit, unit))
    waiting = tune_pending(db)
    if not waiting:
        raise ValueError('nothing waits for a restart')
    try:
        if str(db.value('SHOW huge_pages')).lower() == 'on':
            raise ValueError('huge_pages is on, and a start needs enough of them for the new '
                             'shared_buffers: check vm.nr_hugepages, then run  systemctl '
                             'restart %s  as root' % unit)
    except ValueError:
        raise
    except Exception:                                   # noqa: BLE001
        pass
    if 'shared_buffers' in waiting:
        try:
            want = int(db.value("SELECT pg_size_bytes(setting) FROM pg_file_settings WHERE "
                                "name = 'shared_buffers' AND applied = false ORDER BY seqno "
                                "DESC LIMIT 1") or 0)
        except Exception:                               # noqa: BLE001
            want = 0
        try:
            want = want or 0
            running = int(db.value("SELECT setting::bigint * 8192 FROM pg_settings WHERE "
                                   "name = 'shared_buffers'") or 0)
            avail = tune_machine({}, {}).get('avail') or 0
        except Exception:                               # noqa: BLE001
            running = avail = 0
        if want and avail and want - running > avail - 512 * 1048576:
            raise ValueError('the machine has %d MB free now, too little for shared_buffers of '
                             '%d MB - restarted now, PostgreSQL might not start. Free some '
                             'memory, or put back as it was' % (avail // 1048576,
                                                                 want // 1048576))
    began = time.time()
    try:
        said = subprocess.run(['systemctl', '--no-ask-password', '--no-block', 'restart', unit],
                              capture_output=True, text=True, timeout=15)
    except (OSError, subprocess.SubprocessError) as e:
        raise ValueError('systemctl: %s' % str(e)[:160])
    if said.returncode != 0:
        raise ValueError('%s was not restarted: %s - run  systemctl restart %s  as root'
                         % (unit, (said.stderr or said.stdout).strip()[:160], unit))
    store.add_event('settings', '%s restarted %s for the settings waiting for it: %s'
                    % (by, unit, ', '.join(waiting)), 'warn', who=by)
    time.sleep(2)
    back = False
    while time.time() < began + 62:
        try:
            state = subprocess.run(['systemctl', 'is-failed', unit], capture_output=True,
                                   text=True, timeout=5).stdout.strip()
        except (OSError, subprocess.SubprocessError):
            state = ''
        if state == 'failed':
            raise ValueError('%s did not start again - see  journalctl -u %s ; if it does not '
                             'start: as root, take the shared_buffers line out of '
                             'postgresql.auto.conf and run  systemctl start %s'
                             % (unit, unit, unit))
        try:
            started = float(db.value('SELECT extract(epoch from pg_postmaster_start_time())'))
            if started >= began - 1:
                back = True
                break
        except Exception:                               # noqa: BLE001
            pass
        time.sleep(1)
    if not back:
        raise ValueError('%s was asked to restart and has not answered yet - look again in a '
                         'minute' % unit)
    left = tune_pending(db)
    return {'unit': unit, 'waiting': waiting, 'still': left,
            'message': '%s started again%s' % (unit, '; still waiting: ' + ', '.join(left)
                                                if left else ': every setting is in effect')}


def tune_undo(store, admin_user, admin_password, by):
    before = json.loads(store.get_meta('tune_before:' + node_name()) or '{}')
    if not before:
        raise ValueError('nothing was changed here, so there is nothing to put back')
    db = tune_connect(store, admin_user, admin_password)
    done, failed = [], []
    try:
        for n, v in before.items():
            try:
                if store.db.engine == 'postgres':
                    db.run('ALTER SYSTEM RESET %s' % n)
                else:
                    db.run('SET GLOBAL %s = %s' % (n, v if str(v).isdigit() else "'%s'" % v))
                done.append(n)
            except Exception as e:
                failed.append('%s: %s' % (n, str(e).split('\n')[0][:160]))
        if store.db.engine == 'postgres':
            db.run('SELECT pg_reload_conf()')
    finally:
        if db is not store.db:
            db.close()
    store.set_meta('tune_before:' + node_name(), '')
    last = tune_last(store) or {}
    if last:
        last.update(undone=time.time(), undone_by=by)
        store.set_meta('tune_last:' + node_name(), json.dumps(last))
    store.add_event('settings', 'the database server’s settings were put back by %s: %s'
                    % (by, ', '.join(done)), 'warn', who=by)
    return {'done': done, 'failed': failed}

# ---------------------------------------------------------------------------
# The files kept beside the database, the disk under it, and putting one back
# ---------------------------------------------------------------------------
# As on isemon (1.10.160 on): two kinds of file are kept.
#
#   A *copy* is made by this program: every row of every table, written as a
#   portable file, which goes back into any of the three engines. That is
#   what carries an installation from the file to a server and back.
#
#   A *dump* is made by the engine's own program - pg_dump, mariadb-dump, or
#   for the file SQLite's own backup, which is the file. It is a fraction of
#   the size, the server's own tools read it, and it goes back into the
#   engine it came off.
#
# Every one of either kind has the key that opens the tokens beside it, in a
# file of its own, because one without the other is nothing.

DUMP_DIR = STATE_DIR / 'dumps'
DUMP_SUFFIX = {'sqlite': '.db', 'mariadb': '.sql.gz', 'postgres': '.pgc', 'copy': '.json.gz'}
DUMP_WORDS = {'sqlite': 'a copy of the file', 'mariadb': 'a MariaDB dump',
              'postgres': 'a PostgreSQL dump', 'copy': 'a portable copy'}
DUMP_TOOLS = {'sqlite': (),
              'mariadb': (('making one', ('mariadb-dump', 'mysqldump')),
                          ('putting one back', ('mariadb', 'mysql'))),
              'postgres': (('making one', ('pg_dump',)),
                           ('putting one back', ('pg_restore',)))}
DUMP_INSTALL = {'mariadb': 'dnf install mariadb (it is the client, not the server)',
                'postgres': 'dnf install postgresql (it is the client, not the server)'}
DRIVERS = {'mariadb': ('pymysql', 'python3-PyMySQL'),
           'postgres': ('psycopg2', 'python3-psycopg2')}
NAME_RE = re.compile(r'^o(?:tp|pt)-(sqlite|mariadb|postgres|copy)?-?(\d{8}-\d{6})(?:-([a-z-]+))?'
                     r'(\.db|\.sql\.gz|\.pgc|\.json\.gz)$')


def drivers_state():
    """Whether the driver for each server engine is installed - said before
    somebody types an address rather than after they press a button."""
    out = {}
    for engine, (module, package) in DRIVERS.items():
        try:
            __import__(module)
            out[engine] = {'ready': True, 'package': package}
        except Exception as e:                          # noqa: BLE001
            out[engine] = {'ready': False, 'package': package,
                           'says': 'the driver %s is not installed (%s)' % (module, e)}
    return out


def dump_info(engine):
    """Which program tonight's dump will be made with, and whether it is here."""
    out = {'engine': engine, 'words': DUMP_WORDS.get(engine, engine),
           'suffix': DUMP_SUFFIX.get(engine, ''), 'where': str(DUMP_DIR),
           'install': DUMP_INSTALL.get(engine, ''), 'ready': True, 'why': ''}
    for what, names in DUMP_TOOLS.get(engine, ()):
        if not any(shutil.which(n) for n in names):
            out.update(ready=False, why='%s is not on this machine, so a dump cannot be %s'
                       % (names[0], 'made' if what == 'making one' else 'put back'))
            break
    return out


def _tool(names):
    for one in names:
        got = shutil.which(one)
        if got:
            return got
    raise ValueError('%s is not on this machine' % names[0])


def _db_conf():
    return {k: CONFIG.get(k) for k in DB_KEYS}


def safe_db_name(c):
    """The database's name, as it may stand on a command line: never one
    that reads as an option (1.0.33)."""
    name = str(c.get('db_name') or '')
    if not re.match(r'^[A-Za-z_][A-Za-z0-9_]{0,62}\Z', name):
        raise DbError('the database name %r is not letters, digits and _' % name[:60])
    return name


def _my_cnf(c):
    """A defaults file holding the password and nothing else, 0600, gone the
    moment the program has finished with it: `--password=` on a command line
    is readable by everybody on the machine while it runs."""
    handle, name = tempfile.mkstemp(prefix='otp-my-', suffix='.cnf')
    os.close(handle)
    os.chmod(name, 0o600)
    with open(name, 'w') as f:
        said = str(c.get('db_password') or '')
        if any(ord(ch) < 32 for ch in said):
            raise DbError('the database password has a line break or another control '
                          'character in it')
        f.write('[client]\npassword="%s"\n' % said.replace('\\', '\\\\').replace('"', '\\"'))
    return name


def _my_args(c, cnf):
    out = ['--defaults-extra-file=%s' % cnf,
           '--host=%s' % (str(c.get('db_host') or '127.0.0.1').strip('[]')),
           '--port=%d' % int(c.get('db_port') or 3306),
           '--user=%s' % (c.get('db_user') or '')]
    # The dump and restore tools encrypted as the daemon's own connection is
    # (1.0.36).
    mode = str((c.get('db_tls') if 'db_tls' in c else CONFIG.get('db_tls')) or '')
    ca = str((c.get('db_tls_ca') if 'db_tls_ca' in c else CONFIG.get('db_tls_ca')) or '')
    if mode:
        out.append('--ssl')
        if mode in ('verify-ca', 'verify-full'):
            out.append('--ssl-verify-server-cert')
        if ca:
            out.append('--ssl-ca=%s' % ca)
    return out


def _pg_args(c):
    return ['--host=%s' % (str(c.get('db_host') or '127.0.0.1').strip('[]')),
            '--port=%d' % int(c.get('db_port') or 5432),
            '--username=%s' % (c.get('db_user') or ''), '--no-password']


def _pg_env(c):
    env = dict(os.environ)
    env['PGPASSWORD'] = str(c.get('db_password') or '')
    env['PGCONNECT_TIMEOUT'] = str(int(c.get('db_timeout_s') or 10))
    mode = str((c.get('db_tls') if 'db_tls' in c else CONFIG.get('db_tls')) or '')
    ca = str((c.get('db_tls_ca') if 'db_tls_ca' in c else CONFIG.get('db_tls_ca')) or '')
    if mode:
        env['PGSSLMODE'] = mode
        if ca:
            env['PGSSLROOTCERT'] = ca
    return env


def _run(args, words, stdin=None, stdout=None, env=None, seconds=3600):
    try:
        got = subprocess.run(args, stdin=stdin, stdout=stdout if stdout is not None
                             else subprocess.PIPE, stderr=subprocess.PIPE, env=env,
                             timeout=seconds)
    except subprocess.TimeoutExpired:
        raise ValueError('%s took longer than %d s and was stopped' % (words, seconds))
    if got.returncode != 0:
        said = (got.stderr or b'').decode('utf-8', 'replace').strip().split('\n')
        raise ValueError('%s failed: %s' % (words, (said[-1] if said else
                                                     'exit %d' % got.returncode)[:300]))
    return got.stdout


def _stamp():
    return datetime.now().strftime('%Y%m%d-%H%M%S')


def _key_beside(path):
    p = str(path)
    for suf in ('.json.gz', '.sql.gz', '.pgc', '.db'):
        if p.endswith(suf):
            return Path(p[:-len(suf)] + '.key')
    return Path(p + '.key')


def _write_key_beside(path):
    key = sealing_key()
    if key:
        write_replacing(_key_beside(path), key.hex() + '\n', 0o600)


def _kind_of_name(name):
    for kind, suf in (('copy', '.json.gz'), ('mariadb', '.sql.gz'), ('postgres', '.pgc'),
                      ('sqlite', '.db')):
        if name.endswith(suf):
            return kind
    return ''


def _prune(folder, pattern, keep):
    files = sorted((f for f in folder.glob(pattern) if NAME_RE.match(f.name)),
                   key=lambda f: f.stat().st_mtime)
    for old in files[:-keep] if keep > 0 and len(files) > keep else []:
        for f in (old, _key_beside(old)):
            try:
                f.unlink()
            except OSError:
                pass


def copy_engine(path):
    """Which engine a copy was taken off: its first line says."""
    import gzip
    try:
        with gzip.open(str(path), 'rt', encoding='utf-8') as f:
            return json.loads(f.readline() or '{}').get('engine') or ''
    except Exception:                                   # noqa: BLE001
        return ''


def kept_copies():
    """The copies this program made, newest first."""
    if not BACKUP_DIR.is_dir():
        return []
    out = []
    for f in sorted(list(BACKUP_DIR.glob('otp-*.json.gz')) + list(BACKUP_DIR.glob('opt-*.json.gz')),
                   key=lambda x: x.stat().st_mtime,
                    reverse=True):
        st = f.stat()
        out.append({'name': f.name, 'bytes': st.st_size, 'size': st.st_size, 'at': st.st_mtime,
                    'from': copy_engine(f), 'key': _key_beside(f).exists(), 'kind': 'copy'})
    return out


def kept_dumps(engine):
    """The dumps the engine made of itself, newest first."""
    if not DUMP_DIR.is_dir():
        return []
    out = []
    for f in sorted(DUMP_DIR.iterdir(), key=lambda x: x.stat().st_mtime, reverse=True):
        m = NAME_RE.match(f.name)
        if not m:
            continue
        kind = _kind_of_name(f.name)
        came = m.group(1) or ''
        if kind == 'copy':
            came = copy_engine(f) or came
        st = f.stat()
        out.append({'name': f.name, 'bytes': st.st_size, 'at': st.st_mtime, 'kind': kind,
                    'from': came if kind != 'copy' else came,
                    'mine': kind == 'copy' or kind == engine,
                    'key': _key_beside(f).exists()})
    return out


def make_dump(store, label='daily', folder=None):
    """A dump of the database in use by its own engine's program - or, where
    that program is not on this machine, a portable copy in its place."""
    engine = store.db.engine
    folder = Path(folder) if folder else DUMP_DIR
    folder.mkdir(parents=True, exist_ok=True)
    info = dump_info(engine)
    kind = engine if info['ready'] else 'copy'
    name = 'otp-%s-%s-%s%s' % (engine if kind != 'copy' else 'copy', _stamp(),
                              re.sub(r'[^a-z-]', '', label) or 'daily', DUMP_SUFFIX[kind])
    target = folder / name
    part = Path(str(target) + '.part')
    c = _db_conf()
    try:
        if kind == 'copy':
            dump_tables(store.db, part)
        elif engine == 'sqlite':
            # SQLite's own backup: a consistent copy of the file even while the
            # daemon writes to it.
            src = sqlite3.connect(str(store.db.path))
            dst = sqlite3.connect(str(part))
            try:
                src.backup(dst)
            finally:
                dst.close()
                src.close()
        elif engine == 'mariadb':
            import gzip
            tool = _tool(('mariadb-dump', 'mysqldump'))
            cnf = _my_cnf(c)
            try:
                raw = Path(str(part) + '.raw')
                with open(str(raw), 'wb') as out:
                    _run([tool] + _my_args(c, cnf) + [
                        '--single-transaction', '--quick', '--skip-lock-tables',
                        '--default-character-set=utf8mb4', '--no-tablespaces',
                        '--add-drop-table', '--skip-comments', safe_db_name(c)],
                        'mariadb-dump', stdout=out)
                with open(str(raw), 'rb') as src, gzip.open(str(part), 'wb', 6) as dst:
                    shutil.copyfileobj(src, dst, 1 << 20)
                raw.unlink()
            finally:
                os.unlink(cnf)
        else:
            tool = _tool(('pg_dump',))
            _run([tool] + _pg_args(c) + ['--format=custom', '--compress=6', '--no-owner',
                                         '--no-privileges', '--file=%s' % part,
                                         '--dbname=%s' % safe_db_name(c)],
                 'pg_dump', env=_pg_env(c))
        os.chmod(str(part), 0o640)
        part.replace(target)
    finally:
        for left in (part, Path(str(part) + '.raw')):
            if left.exists():
                try:
                    left.unlink()
                except OSError:
                    pass
    _write_key_beside(target)
    if folder == DUMP_DIR:
        _prune(DUMP_DIR, 'o[tp][tp]-*', int(CONFIG.get('backup_keep') or 14))
    store.add_event('backups', 'made %s (%s): %s' % (
        DUMP_WORDS[kind], {'daily': 'every night', 'by-hand': 'by hand',
                           'download': 'to be downloaded'}.get(label, label), target.name))
    return target


# ---- what is in a file, without putting any of it back ------------------------
def _magic(path):
    with open(str(path), 'rb') as f:
        return f.read(16)


def _peek_copy(path):
    import gzip
    counts, admins, tables, table = {}, 0, 0, None
    with gzip.open(str(path), 'rt', encoding='utf-8') as f:
        head = json.loads(f.readline() or '{}')
        if 'otp' not in head and 'opt' not in head:      # 'opt': before 1.0.37's new name
            return None, 'that is not a copy made by otp'
        for line in f:
            got = json.loads(line)
            if set(got.keys()) == {'table'}:
                table = got['table']
                tables += 1
                counts.setdefault(table, 0)
                continue
            if table:
                counts[table] += 1
                if table == 'accounts' and got.get('role') == 'fulladmin' \
                        and not got.get('disabled'):
                    admins += 1
    return {'kind': 'copy', 'from': head.get('engine') or '', 'version': head.get('otp') or head.get('opt'),
            'made': head.get('made'), 'counts': counts, 'admins': admins, 'tables': tables,
            'key': bool(head.get('key')), 'machine': head.get('machine')}, ''


def _peek_sqlite(path):
    try:
        con = sqlite3.connect('file:%s?mode=ro' % path, uri=True)
    except sqlite3.Error as e:
        return None, 'that file could not be opened: %s' % e
    try:
        names = [r[0] for r in con.execute(
            "SELECT name FROM sqlite_master WHERE type = 'table'")]
        if 'accounts' not in names or 'tokens' not in names:
            return None, 'that is not a database of otp: it has no tokens and no accounts'
        counts = {t: con.execute('SELECT COUNT(*) FROM %s' % t).fetchone()[0]
                  for t in TABLES if t in names}
        admins = con.execute("SELECT COUNT(*) FROM accounts WHERE role = 'fulladmin' AND "
                             "COALESCE(disabled, 0) = 0").fetchone()[0]
    except sqlite3.Error as e:
        return None, 'that database could not be read: %s' % e
    finally:
        con.close()
    return {'kind': 'sqlite', 'counts': counts, 'admins': admins,
            'tables': len([t for t in TABLES if t in names])}, ''


def _peek_mariadb(path):
    import gzip
    tables, admins, users, in_users = set(), 0, 0, False
    with gzip.open(str(path), 'rt', encoding='utf-8', errors='replace') as f:
        for line in f:
            if line.startswith('CREATE TABLE'):
                got = re.search(r'CREATE TABLE `([^`]+)`', line)
                if got:
                    tables.add(got.group(1))
                continue
            first = line.startswith('INSERT INTO `accounts`')
            if first:
                in_users = True
            elif in_users and not line.startswith('('):
                in_users = False
            if in_users:
                admins += line.count(",'fulladmin',")
                rest = line.split('VALUES', 1)[-1] if first else line
                users += rest.count('),(') + (1 if '(' in rest else 0)
                if line.rstrip().endswith(';'):
                    in_users = False
    if 'accounts' not in tables or 'tokens' not in tables:
        return None, 'that dump is not one of otp - it has no tokens and no accounts'
    return {'kind': 'mariadb', 'counts': {'accounts': users}, 'admins': admins,
            'tables': len(tables)}, ''


def _peek_postgres(path):
    tool = shutil.which('pg_restore')
    if not tool:
        return None, ('pg_restore is not on this machine, so what is in that dump cannot be '
                      'read: %s' % DUMP_INSTALL['postgres'])
    listed = _run([tool, '--list', str(path)], 'pg_restore --list', seconds=300)
    tables = set(re.findall(r'TABLE DATA\s+\S+\s+(\S+)', listed.decode('utf-8', 'replace')))
    if 'accounts' not in tables or 'tokens' not in tables:
        return None, 'that dump is not one of otp - it has no tokens and no accounts'
    rows = _run([tool, '--data-only', '--table=accounts', '--file=-', str(path)],
                'pg_restore', seconds=300).decode('utf-8', 'replace')
    users = admins = 0
    inside = False
    for line in rows.split('\n'):
        if line.startswith('COPY '):
            inside = True
            continue
        if inside:
            if line == '\\.':
                break
            users += 1
            if '\tfulladmin\t' in line:
                admins += 1
    return {'kind': 'postgres', 'counts': {'accounts': users}, 'admins': admins,
            'tables': len(tables)}, ''


def db_file_peek(path, engine, need_admin=True):
    """What is in a copy or a dump, and whether it may be put back here."""
    head = _magic(path)
    try:
        if head.startswith(b'SQLite format 3'):
            said, why = _peek_sqlite(path)
        elif head.startswith(b'PGDMP'):
            said, why = _peek_postgres(path)
        elif head[:2] == b'\x1f\x8b':
            import gzip
            with gzip.open(str(path), 'rb') as f:
                first = f.read(64)
            if first.startswith(b'{'):
                said, why = _peek_copy(path)
            else:
                said, why = _peek_mariadb(path)
        else:
            return None, 'that is neither a copy nor a dump made by otp'
    except Exception as e:                              # noqa: BLE001
        return None, 'that file could not be read: %s' % str(e).split('\n')[0][:200]
    if said is None:
        return None, why
    kind = said['kind']
    if kind not in ('copy', 'sqlite') and kind != engine:
        return None, ('that is %s, and this installation is on %s: a dump goes back only into '
                      'the engine it came off. Use a copy - a copy goes into any of the three.'
                      % (DUMP_WORDS[kind], ENGINE_WORDS.get(engine, engine)))
    if not said.get('admins'):
        # On the command line root makes one afterwards (1.0.62): a copy of
        # a server set up there alone was refused for good.
        if need_admin:
            return None, ('there is no full administrator who can sign in in that file: putting '
                          'it back would lock everybody out of these pages (on the command line '
                          'it can be put back, and an account made after it)')
        said['no_admin'] = True
    said['bytes'] = Path(path).stat().st_size
    return said, ''


def _sqlite_to_copy(path, out):
    """A SQLite file of ours, as a copy: so that it goes back into whatever
    engine is in use, by the same road as every copy."""
    src = Db('sqlite', path=path)
    try:
        dump_tables(src, out, [t for t in TABLES if t in src.tables()])
    finally:
        src.close()
    return out


def db_file_restore(store, path, by, key_file=None, from_name='', need_admin=True):
    """Put a copy or a dump back over everything. A copy of what is replaced
    is made first and kept with the others."""
    engine = store.db.engine
    said, why = db_file_peek(path, engine, need_admin)
    if said is None:
        raise ValueError(why)
    kind = said['kind']
    if CONFIG.get('ha_mode') == 'replicated' and kind in ('postgres', 'mariadb'):
        raise ValueError('a dump puts tables back by making them again, which replication '
                         'does not carry to the other node: put a copy back instead (it goes '
                         'over row by row)')
    # A kept copy is read from a copy of its own (1.0.44): the safety copy
    # below rotates the kept ones, and the oldest - the one being put back -
    # would be the one it took away.
    held = []
    try:
        if Path(path).resolve().parent == Path(BACKUP_DIR).resolve():
            ext = ''.join(Path(path).suffixes[-2:]) if str(path).endswith('.gz') else Path(path).suffix
            fd, tmpname = tempfile.mkstemp(prefix='otp-putback-', suffix=ext, dir=str(STATE_DIR))
            os.close(fd)
            shutil.copyfile(str(path), tmpname)
            os.chmod(tmpname, 0o600)
            held.append(Path(tmpname))
            kf = Path(key_file) if key_file else None
            if kf and kf.exists():
                fd, kname = tempfile.mkstemp(prefix='otp-putback-', suffix='.key', dir=str(STATE_DIR))
                os.close(fd)
                shutil.copyfile(str(kf), kname)
                os.chmod(kname, 0o600)
                held.append(Path(kname))
                key_file = kname
            path = tmpname
        return _db_file_restore(store, path, by, key_file, from_name, kind)
    finally:
        for x in held:
            try:
                x.unlink()
            except OSError:
                pass


def _db_file_restore(store, path, by, key_file, from_name, kind):
    # The key that opens the tokens in it: beside a kept file, or inside a copy
    # that was downloaded with it.
    key_hex = ''
    if key_file and Path(key_file).exists():
        key_hex = Path(key_file).read_text().strip()
    elif kind == 'copy':
        import gzip
        with gzip.open(str(path), 'rt', encoding='utf-8') as f:
            key_hex = str(json.loads(f.readline() or '{}').get('key') or '')
    # In a cluster the other node keeps its own key, and the rows going over
    # would be ones it cannot open (1.0.44): a copy sealed with another key
    # is refused there before anything is replaced.
    if CONFIG.get('ha_mode') == 'replicated' and re.match(r'^[0-9a-f]{64}\Z', key_hex):
        now = sealing_key()
        if now and now.hex() != key_hex:
            raise ValueError('this copy was sealed with another key than the one both nodes '
                             'use; in a cluster it cannot be put back - the other node could '
                             'not open its tokens')
    safety = make_backup(store, 'before putting %s back, by %s' % (from_name or 'a file', by))
    # The link between the databases describes the machines, not the data
    # (1.0.104): the authority and each node's steps as they are now stay;
    # a copy without them leaves them, one from before keeps no older ones.
    try:
        live_tls = store.db.rows("SELECT k, v FROM meta WHERE k LIKE 'hatls:%'")
    except Exception:                                   # noqa: BLE001
        live_tls = []
    c = _db_conf()
    if kind == 'copy':
        load_tables(store.db, path)
    elif kind == 'sqlite':
        tmp = Path(tempfile.mkstemp(prefix='otp-restore-', suffix='.json.gz',
                                    dir=str(STATE_DIR))[1])
        try:
            _sqlite_to_copy(path, tmp)
            load_tables(store.db, tmp)
        finally:
            tmp.unlink()
    elif kind == 'mariadb':
        import gzip
        tool = _tool(('mariadb', 'mysql'))
        with gzip.open(str(path), 'rb') as sent:
            for n, line in enumerate(sent):
                if line[:1] == b'\\' or line[:7].lower() == b'system ':
                    raise ValueError('line %d of the dump is a client command, not SQL. '
                                     'A dump this program made has none.' % (n + 1))
        cnf = _my_cnf(c)
        # The client is given the SQL itself: a gzip reader has no file
        # descriptor of its own to hand a program, so it is unpacked first.
        raw = Path(tempfile.mkstemp(prefix='otp-sql-', dir=str(STATE_DIR))[1])
        try:
            with gzip.open(str(path), 'rb') as src, open(str(raw), 'wb') as dst:
                shutil.copyfileobj(src, dst, 1 << 20)
            with open(str(raw), 'rb') as sent:
                _run([tool] + _my_args(c, cnf) + ['--default-character-set=utf8mb4',
                                                  '--local-infile=0', '--binary-mode',
                                                  safe_db_name(c)],
                     'the MariaDB client', stdin=sent)
        finally:
            os.unlink(cnf)
            try:
                raw.unlink()
            except OSError:
                pass
    else:
        tool = _tool(('pg_restore',))
        _run([tool] + _pg_args(c) + ['--single-transaction', '--clean', '--if-exists',
                                     '--no-owner', '--no-privileges',
                                     '--dbname=%s' % safe_db_name(c), str(path)],
             'pg_restore', env=_pg_env(c))
    store.db.make_tables()
    if CONFIG.get('ha_mode') == 'replicated' and store.db.engine == 'postgres':
        ha_sequences(store.db, int(CONFIG.get('ha_slot') or 1))
    for r in live_tls:
        try:
            store.set_meta(r['k'], r['v'])
        except Exception:                               # noqa: BLE001
            pass
    hatls_check_soon()      # and then looked at: what is in place against what is wanted
    key_said = 'the key that opens the tokens stays as it was'
    if re.match(r'^[0-9a-f]{64}\Z', key_hex):
        now = sealing_key()
        if not now or now.hex() != key_hex:
            write_replacing(sealing_key_path(), key_hex + '\n', 0o600)
            key_said = 'the key that opens the tokens came with it and is in use now'
    else:
        # No key came with it (1.0.59): whether the tokens put back open with
        # the key in use is looked at, and said loudly when they do not.
        try:
            rows = store.db.rows('SELECT name, secret FROM tokens WHERE secret IS NOT NULL '
                                 "AND secret <> '' ORDER BY id LIMIT 5")
            if rows and not any(unseal_secret(r['secret'], token_bind(r['name']))
                                for r in rows):
                key_said = ('NO KEY CAME WITH IT and its tokens do not open with the key in '
                            'use: put back the .key file that was beside the dump (or the '
                            'copy from the download) - until then every token is refused')
                store.add_event('backups', 'the database put back from %s came without its key '
                                'and its tokens cannot be opened' % (from_name or 'a file'),
                                'bad', who=by)
        except Exception as e:                          # noqa: BLE001
            log('the tokens put back could not be tried with the key: %s' % e, 'warn')
    bump(store)
    store.add_event('backups', '%s put the database back from %s (%s); what it replaced is in %s'
                    % (by, from_name or 'a file', DUMP_WORDS.get(kind, kind), safety.name),
                    'warn', who=by)
    return {'safety': safety.name, 'kind': kind, 'key': key_said}


# ---- the disk under it ----------------------------------------------------------
def note_size(store):
    """The size of the database, once a day, for how fast it grows."""
    try:
        sizes = json.loads(store.get_meta('db_sizes:' + node_name()) or '{}')
    except ValueError:
        sizes = {}
    today = datetime.now().strftime('%Y-%m-%d')
    if sizes.get('engine') != store.db.engine:
        sizes = {'engine': store.db.engine, 'days': {}}
    if today not in sizes['days']:
        sizes['days'][today] = int(store.db.size() or 0)
        for old in sorted(sizes['days'])[:-60]:
            del sizes['days'][old]
        store.set_meta('db_sizes:' + node_name(), json.dumps(sizes))
    return sizes


def db_growth(store):
    days = note_size(store).get('days', {})
    edge = (datetime.now().timestamp() - 15 * 86400)
    seen = sorted((d, b) for d, b in days.items()
                  if datetime.strptime(d, '%Y-%m-%d').timestamp() >= edge)
    if len(seen) < 2:
        return {'a_day': 0, 'over_days': 0}
    (d0, b0), (d1, b1) = seen[0], seen[-1]
    span = max(1, (datetime.strptime(d1, '%Y-%m-%d') - datetime.strptime(d0, '%Y-%m-%d')).days)
    return {'a_day': max(0, int((b1 - b0) / span)), 'over_days': span}


def _folder_bytes(folder):
    total = 0
    if Path(folder).is_dir():
        for f in Path(folder).iterdir():
            try:
                total += f.stat().st_size
            except OSError:
                pass
    return total


def db_disk(store):
    db = store.db
    where = db.path.parent if db.engine == 'sqlite' else STATE_DIR
    out = {'where': str(where), 'total': 0, 'free': 0, 'share': 0, 'days_left': None,
           'holds': 'the database itself, its copies and its dumps' if db.engine == 'sqlite'
           else 'the copies and the dumps - the database itself is on the server'}
    try:
        u = shutil.disk_usage(str(where))
        out.update(total=u.total, free=u.free,
                   share=round(100.0 * (u.total - u.free) / u.total) if u.total else 0)
    except OSError:
        pass
    grew = db_growth(store)
    if grew['a_day'] and out['free']:
        out['days_left'] = int(out['free'] / grew['a_day'])
    parts = []
    if db.engine == 'sqlite':
        for suffix, what in (('', 'the database'), ('-wal', 'what is written, not yet folded in'),
                             ('-shm', 'the index of that')):
            f = Path(str(db.path) + suffix)
            if f.exists():
                parts.append({'name': f.name, 'what': what, 'bytes': f.stat().st_size})
    else:
        parts.append({'name': db.where(), 'what': 'the database, on the server',
                      'bytes': int(db.size() or 0)})
    parts.append({'name': str(BACKUP_DIR), 'what': 'the copies', 'bytes':
                  _folder_bytes(BACKUP_DIR)})
    parts.append({'name': str(DUMP_DIR), 'what': 'the dumps', 'bytes': _folder_bytes(DUMP_DIR)})
    return out, grew, parts


def db_cache(store):
    """The server's own cache, where it is left as installed and the database
    has outgrown it."""
    db = store.db
    if db.engine == 'sqlite':
        return None
    try:
        if db.engine == 'postgres':
            setting = 'shared_buffers'
            cache = int(db.value("SELECT setting::bigint * 8192 FROM pg_settings "
                                 "WHERE name = 'shared_buffers'") or 0)
        else:
            setting = 'innodb_buffer_pool_size'
            r = db.row("SHOW GLOBAL VARIABLES LIKE 'innodb_buffer_pool_size'")
            cache = int(list(r.values())[1]) if r else 0
    except Exception:                                   # noqa: BLE001
        return None
    size = int(db.size() or 0)
    ram = 0
    try:
        with open('/proc/meminfo') as f:
            for line in f:
                if line.startswith('MemTotal:'):
                    ram = int(line.split()[1]) * 1024
    except OSError:
        pass
    return {'engine': ENGINE_WORDS.get(db.engine), 'setting': setting, 'cache': cache,
            'size': size, 'ram': ram, 'low': bool(cache and size > cache)}


# ---- erasing what was collected -----------------------------------------------
ERASABLE = [
    ('radius', 'radius_log', 'the RADIUS requests',
     'every request the VPN sent and what it was answered, with its steps. Nothing reads them '
     'back: they are the record of what happened.'),
    ('otp', 'otp_log', 'the checks of a code',
     'every code typed on the enrolment pages, in a test or through RADIUS, right or wrong. '
     'The tokens themselves are not touched: nobody has to enrol again.'),
    ('events', 'events', 'the event log',
     'what this program noted about itself: sign-ins, changes, copies, starts and stops.'),
]


def db_erasable(store):
    groups = []
    for key, table, name, says in ERASABLE:
        groups.append({'key': key, 'name': name, 'says': says,
                       'rows': int(store.db.value('SELECT COUNT(*) FROM %s' % table) or 0)})
    return {'groups': groups, 'bytes': int(store.db.size() or 0)}


def db_erase_job(store, groups, tidy, by):
    tables = [(t, n) for k, t, n, _ in ERASABLE if k in groups]
    if not tables:
        raise ValueError('nothing was ticked')

    def work(progress):
        progress(0, len(tables) + 2, 'making a copy first')
        copy = make_backup(store, 'before erasing, by %s' % by)
        gone = {}
        for i, (t, n) in enumerate(tables):
            progress(i + 1, len(tables) + 2, 'emptying %s' % n)
            gone[t] = store.db.run('DELETE FROM %s' % t)
        given = None
        if tidy:
            progress(len(tables) + 1, len(tables) + 2, 'giving the disk back')
            given = db_give_back(store, lambda *a: None)
        store.add_event('settings', '%s erased %s (a copy was made first: %s)'
                        % (by, ', '.join(n for _, n in tables), copy.name), 'warn', who=by)
        progress(len(tables) + 2, len(tables) + 2, 'done')
        return {'erased': gone, 'copy': copy.name, 'given': given}
    return db_job('erasing the collected data', work)


# ---- the server's settings: what was done, what waits for a start ---------------
def tune_state(store):
    db = store.db
    out = {'engine': db.engine, 'last': None, 'pending': [], 'lost': [],
           'restart': {'may': False, 'unit': {'postgres': 'postgresql',
                                              'mariadb': 'mariadb'}.get(db.engine, '')}}
    try:
        last = json.loads(store.get_meta('tune_last:' + node_name()) or 'null')
    except ValueError:
        last = None
    out['last'] = last
    if db.engine == 'postgres':
        try:
            out['pending'] = [r['name'] for r in db.rows(
                'SELECT name FROM pg_settings WHERE pending_restart')]
        except Exception:                               # noqa: BLE001
            pass
    elif db.engine == 'mariadb' and last and not last.get('undone') \
            and last.get('engine') == 'mariadb':
        now = tune_current(db, list((last.get('set') or {}).keys()))
        out['lost'] = [n for n, v in (last.get('set') or {}).items()
                       if not tune_same('mariadb', now.get(n, ''), v)]
    return out

# ---------------------------------------------------------------------------
# Sending mail (1.0.20)
# ---------------------------------------------------------------------------
# A token's QR code, and if wanted its recovery codes, sent to the person it
# is for. Two ways out: through a mail server (SMTP relay, with STARTTLS,
# SMTPS or nothing, signing in with PLAIN, LOGIN, CRAM-MD5, XOAUTH2 or not at
# all), or straight to the server of the recipient's domain - its MX record,
# looked up here - with no relay at all. A certificate signed by an authority
# of your own is trusted once that authority is added, as for a directory.

MAIL_CA_META = 'mail_ca'
MAIL_DIRECT_DEADLINE_S = 60     # every MX of one domain together (1.0.59)


def mail_ca_pem(store):
    try:
        return str(store.get_meta(MAIL_CA_META) or '')
    except Exception:
        return ''


def mail_ca_set(store, pem, mode='add', fingerprint=''):
    """The authorities trusted for the mail server, each added and taken out
    by itself - the same as a directory's."""
    pem = str(pem or '').strip()
    have = split_certificates(mail_ca_pem(store))
    if mode == 'add' and pem:
        new = split_certificates(pem)
        if not new or not all(describe_certificate(b) for b in new):
            raise ValueError('that is not a certificate this can read: a PEM certificate '
                             'starts -----BEGIN CERTIFICATE-----')
        seen = {c['fingerprint'] for c in describe_certificates('\n'.join(have))}
        have += [b for b, c in zip(new, describe_certificates('\n'.join(new)))
                 if c['fingerprint'] not in seen]
    elif mode == 'drop':
        keep = [b for b, c in zip(have, describe_certificates('\n'.join(have)))
                if c['fingerprint'] != fingerprint]
        if len(keep) == len(have):
            raise ValueError('that certificate is not among the ones kept')
        have = keep
    else:
        have = []
    store.set_meta(MAIL_CA_META, '\n'.join(have))
    return describe_certificates('\n'.join(have))


def mail_tls(store, verify=None):
    verify = bool(CONFIG.get('smtp_verify', 1)) if verify is None else verify
    ctx = ssl.create_default_context()
    pem = mail_ca_pem(store)
    if pem.strip():
        try:
            ctx.load_verify_locations(cadata=pem)
        except (ssl.SSLError, ValueError) as e:
            raise MailError('the certificate authorities kept for mail cannot be read: %s' % e)
    if not verify:
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
    return ctx


class MailError(RuntimeError):
    """`permanent` (1.0.95): the receiving side said no for good (a 5xx) -
    not tried again. Anything else - a 4xx (greylisting), a server away -
    is, from the outgoing mail."""
    def __init__(self, said, steps=None, permanent=False):
        super(MailError, self).__init__(said)
        self.steps = steps or []
        self.permanent = bool(permanent)
        self.queued = None


# ---- the recipients' servers, without a library to ask DNS with -----------------
def own_dns():
    """The DNS servers set for mail going direct (`mail_dns`), if any."""
    good = []
    for w in re.split(r'[\s,;]+', str(CONFIG.get('mail_dns') or '')):
        try:
            good.append(str(ipaddress.ip_address(w)))
        except ValueError:
            pass
    return good


def dns_servers():
    if own_dns():
        return own_dns()
    out = []
    try:
        with open('/etc/resolv.conf') as f:
            for line in f:
                bits = line.split()
                if len(bits) >= 2 and bits[0] == 'nameserver':
                    out.append(bits[1])
    except OSError:
        pass
    return out or ['127.0.0.1']


def _dns_name(data, at):
    labels, jumped, end = [], False, at
    for _ in range(64):
        n = data[at]
        if n == 0:
            at += 1
            break
        if n & 0xC0 == 0xC0:
            if not jumped:
                end = at + 2
            at = ((n & 0x3F) << 8) | data[at + 1]
            jumped = True
            continue
        labels.append(data[at + 1:at + 1 + n].decode('ascii', 'replace'))
        at += 1 + n
    return '.'.join(labels), (end if jumped else at)


def _dns_ask(server, name, qtype, timeout):
    """One question to one DNS server: the raw answer. EDNS0 asks for room
    for a long answer; one that is cut short anyway is asked again over TCP
    (1.0.22)."""
    ident = secrets.randbits(16)
    q = struct.pack('>HHHHHH', ident, 0x0100, 1, 0, 0, 1)
    for label in name.split('.'):
        if not label:
            continue
        raw = label.encode('idna') if any(ord(c) > 127 for c in label) else label.encode()
        q += bytes([len(raw)]) + raw
    q += b'\x00' + struct.pack('>HH', qtype, 1)
    q += b'\x00' + struct.pack('>HHIH', 41, 4096, 0, 0)          # OPT: 4096 bytes
    fam = socket.AF_INET6 if ':' in server else socket.AF_INET
    s = socket.socket(fam, socket.SOCK_DGRAM)
    deadline = time.time() + timeout
    question = q[12:-11]                    # the name, the type and the class asked
    try:
        # connect(): only answers from the server asked are read at all.
        s.connect((server, 53))
        s.send(q)
        while True:
            left = deadline - time.time()
            if left <= 0:
                raise socket.timeout('no answer from %s' % server)
            s.settimeout(left)
            data = s.recv(65535)
            # Its own answer: the same ID, and the same question (1.0.33) -
            # and no waiting past the deadline however many others come.
            if len(data) >= 12 + len(question) and struct.unpack('>H', data[:2])[0] == ident \
                    and data[12:12 + len(question)].lower() == question.lower():
                break
    finally:
        s.close()
    if struct.unpack('>H', data[2:4])[0] & 0x0200:                # TC: cut short
        t = socket.create_connection((server, 53), timeout=timeout)
        try:
            t.sendall(struct.pack('>H', len(q)) + q)
            want, got = None, b''
            while want is None or len(got) < want + 2:
                chunk = t.recv(65535)
                if not chunk:
                    break
                got += chunk
                if want is None and len(got) >= 2:
                    want = struct.unpack('>H', got[:2])[0]
            data = got[2:]
        finally:
            t.close()
    return data


def _dns_records(data):
    """(rcode, [(type, name, rdata-offset, size)]) of an answer."""
    flags, qd, an = struct.unpack('>HHH', data[2:8])
    at = 12
    for _ in range(qd):
        _, at = _dns_name(data, at)
        at += 4
    out = []
    for _ in range(an):
        rname, at = _dns_name(data, at)
        rtype, _cls, _ttl, size = struct.unpack('>HHIH', data[at:at + 10])
        at += 10
        out.append((rtype, rname, at, size))
        at += size
    return flags & 0x0F, out


DNS_RCODES = {1: 'could not read the question', 2: 'failed (SERVFAIL)', 4: 'does not do that',
              5: 'refused to answer'}


def dns_mx_full(domain, timeout=5.0):
    """The mail servers of a domain, best first, and how they were found:
    ([(preference, host)], words). A domain with no MX record is its own
    mail server (RFC 5321) - but only when a DNS server said so, never
    because one failed to answer (1.0.22: a failed answer was taken for
    "no MX" and the mail went to the domain's own address)."""
    domain = str(domain).strip().strip('.').lower()
    try:                                       # dnspython, where it is installed
        if own_dns():
            # The DNS servers set for mail are the ones asked (1.0.59):
            # dnspython reads the system's, and with a split horizon its
            # NXDOMAIN was taken for the last word.
            raise ImportError('mail_dns is set')
        import dns.resolver                     # type: ignore
        try:
            ans = dns.resolver.resolve(domain, 'MX', lifetime=timeout * 2)
            got = sorted((int(r.preference), str(r.exchange).rstrip('.')) for r in ans)
            got = [g for g in got if g[1]]
            if got:
                return got, 'MX records (dnspython)'
        except dns.resolver.NXDOMAIN:
            raise MailError('the domain %s does not exist' % domain)
        except dns.resolver.NoAnswer:
            return [(0, domain)], 'no MX record: the domain itself (dnspython)'
        except Exception:                       # noqa: BLE001 - our own below
            pass
    except ImportError:
        pass
    trouble = []
    name = domain
    for server in dns_servers():
        name = domain
        for _hop in range(6):                   # a CNAME, followed
            try:
                data = _dns_ask(server, name, 15, timeout)
                rcode, recs = _dns_records(data)
            except (OSError, struct.error, IndexError, ValueError) as e:
                trouble.append('%s: %s' % (server, e))
                break
            if rcode == 3:
                raise MailError('the domain %s does not exist (DNS %s)' % (name, server))
            if rcode:
                trouble.append('%s %s' % (server, DNS_RCODES.get(rcode, 'answered %d' % rcode)))
                break
            mx, cname, nullmx = [], None, False
            try:
                for rtype, _rname, at, _size in recs:
                    if rtype == 15:
                        pref = struct.unpack('>H', data[at:at + 2])[0]
                        host, _ = _dns_name(data, at + 2)
                        if host and host != '.':
                            mx.append((pref, host.rstrip('.').lower()))
                        else:
                            nullmx = True
                    elif rtype == 5:
                        cname, _ = _dns_name(data, at)
            except (struct.error, IndexError, ValueError) as e:
                trouble.append('%s: an answer that does not read: %s' % (server, e))
                break
            if mx:
                return sorted(mx), 'MX records from DNS %s' % server
            if nullmx:
                return [], 'a null MX (DNS %s): the domain takes no mail' % server
            if cname and cname.lower() != name:
                name = cname.rstrip('.').lower()
                continue
            # A null MX (RFC 7505) is "0 ." - the domain takes no mail.
            return [(0, name)], 'no MX record (DNS %s): the domain itself' % server
    raise MailError('no DNS server could say where mail for %s goes%s' % (
        domain, (': ' + '; '.join(trouble)) if trouble else ''))


def dns_mx(domain, timeout=5.0):
    return dns_mx_full(domain, timeout)[0]


def dns_addrs(host, timeout=5.0):
    """The IPv4 and IPv6 addresses of a host (A and AAAA, a CNAME followed),
    asked of the same DNS servers as the MX records (1.0.23) - not of the
    system's resolver, which may be the very one that will not answer."""
    host = str(host).strip().strip('.').lower()
    try:
        return [str(ipaddress.ip_address(host))]
    except ValueError:
        pass
    out, trouble = [], []
    for qtype in (1, 28):
        for server in dns_servers():
            name, done = host, False
            for _hop in range(6):
                try:
                    data = _dns_ask(server, name, qtype, timeout)
                    rcode, recs = _dns_records(data)
                except (OSError, struct.error, IndexError, ValueError) as e:
                    trouble.append('%s: %s' % (server, e))
                    break
                if rcode == 3:
                    done = True
                    break
                if rcode:
                    trouble.append('%s %s' % (server, DNS_RCODES.get(rcode, 'answered %d' % rcode)))
                    break
                cname, got = None, []
                try:
                    for rtype, _rname, at, size in recs:
                        if rtype == 1 and size == 4:
                            got.append(socket.inet_ntop(socket.AF_INET, data[at:at + 4]))
                        elif rtype == 28 and size == 16:
                            got.append(socket.inet_ntop(socket.AF_INET6, data[at:at + 16]))
                        elif rtype == 5:
                            cname, _ = _dns_name(data, at)
                except (struct.error, IndexError, ValueError, OSError) as e:
                    trouble.append('%s: an answer that does not read: %s' % (server, e))
                    break
                if got:
                    out += [g for g in got if g not in out]
                    done = True
                    break
                if cname and cname.rstrip('.').lower() != name:
                    name = cname.rstrip('.').lower()
                    continue
                done = True                     # no record of this type
                break
            if done:
                break
    if not out:
        raise MailError('no address found for %s%s' % (host, (': ' + '; '.join(trouble))
                                                       if trouble else ''))
    # IPv4 first: a machine with an IPv6 address and no IPv6 route waits out
    # the whole timeout on every server otherwise.
    return sorted(out, key=lambda a: ':' in a)


class _Deadline(object):
    """One conversation's whole time, not each read's (1.0.101): a server
    sending a byte every 19 s of a 20 s timeout held the thread - and a page
    waiting on it - for as long as it liked."""
    deadline = 0.0

    def _left(self):
        if not self.deadline:
            return None
        left = self.deadline - time.time()
        if left <= 0:
            raise smtplib.SMTPServerDisconnected('the mail server took longer than allowed')
        return left

    def _watch(self):
        """A watchman that ends the conversation at its deadline (1.0.103):
        the time of each read alone was set again line by line, so a server
        dripping its reply byte by byte held the thread past any deadline.
        Shut down, the socket ends whatever read waits on it."""
        if not self.deadline or getattr(self, '_watchman', None):
            return
        def expire():
            sock = getattr(self, 'sock', None)
            if sock is not None:
                try:
                    sock.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass
        t = threading.Timer(max(0.5, self.deadline - time.time()), expire)
        t.daemon = True
        t.start()
        self._watchman = t

    # The conversation into the log, with "Debug log" and "...every code sent"
    # on (1.0.113): what was said each way, never a password or the message.
    _SAFE = ('EHLO', 'HELO', 'MAIL', 'RCPT', 'DATA', 'QUIT', 'STARTTLS', 'RSET', 'NOOP')

    def _print_debug(self, *args):
        words = ' '.join(str(a) for a in args)
        m = re.match(r"^(send|reply):\s*(b?['\"])(.*)", words, re.S)
        if m and m.group(1) == 'send':
            body = m.group(3)
            head = body.split(' ', 1)[0].split('\\r')[0].upper()
            if head.startswith('AUTH'):
                words = 'send: AUTH %s <the credentials, not written>' % (
                    body.split(' ')[1] if ' ' in body else '')
            elif head not in self._SAFE:
                words = 'send: <%d characters - the message or the credentials, not written>' \
                    % len(body)
        log('mail %s: %s' % (getattr(self, '_host', '') or '?', words[:300]), 'debug')

    def close(self):
        t = getattr(self, '_watchman', None)
        if t is not None:
            t.cancel()
        return smtplib.SMTP.close(self)

    def getreply(self):
        self._watch()
        left = self._left()
        if left is not None and self.sock is not None:
            try:
                self.sock.settimeout(min(left, self.timeout or left))
            except OSError:
                pass
        return smtplib.SMTP.getreply(self)

    def send(self, s):
        left = self._left()
        if left is not None and self.sock is not None:
            try:
                self.sock.settimeout(min(left, self.timeout or left))
            except OSError:
                pass
        return smtplib.SMTP.send(self, s)


class _AddrSMTP(_Deadline, smtplib.SMTP):
    """smtplib, connecting to addresses already looked up; the host's name
    is still what the certificate is checked against. It keeps what the
    server answered to the message itself - "250 Ok: queued as 4Xy..." -
    which is what its own log is searched by (1.0.27)."""
    addrs = ()
    last_reply = None

    def data(self, msg):
        got = smtplib.SMTP.data(self, msg)
        self.last_reply = got
        return got

    def _get_socket(self, host, port, timeout):
        last = None
        for a in self.addrs or [host]:
            try:
                return socket.create_connection((a, port), timeout, self.source_address)
            except OSError as e:
                last = e
        raise last or OSError('no address to reach')


class _AddrSMTPS(_Deadline, smtplib.SMTP_SSL):
    addrs = ()
    last_reply = None

    def data(self, msg):
        got = smtplib.SMTP.data(self, msg)
        self.last_reply = got
        return got

    def _get_socket(self, host, port, timeout):
        sock = _AddrSMTP._get_socket(self, host, port, timeout)
        try:
            return self.context.wrap_socket(sock, server_hostname=self._host)
        except BaseException:
            sock.close()                # not left to the collector (1.0.59)
            raise


# ---- one conversation with one server ---------------------------------------------
def _xoauth2(user, token):
    return lambda challenge=None: 'user=%s\x01auth=Bearer %s\x01\x01' % (user, token)


def smtp_talk(store, host, port, security, auth, msg, to, steps, helo='', verify=None,
              timeout=None, direct=False):
    """Send one message through one server, writing down every step."""
    timeout = float(timeout or CONFIG.get('smtp_timeout_s') or 20)
    helo = str(helo or CONFIG.get('mail_helo') or socket.getfqdn() or 'localhost')
    ctx = mail_tls(store, verify)
    if direct and security == 'starttls-if':
        # TLS where offered, going straight to somebody's MX (1.0.59): their
        # certificate is not checked, as no mail server checks another's -
        # a self-signed one there failed every message to the domain, where
        # plain text would have gone. "required" still checks it.
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
    began = time.time()

    def step(what, ok=True, said=''):
        steps.append({'what': what, 'ok': ok, 'said': str(said or '')[:500]})
        if debugging('codes'):
            log('mail %s:%d: %s %s%s' % (host, port, 'ok' if ok else 'FAILED', what,
                                         (' - %s' % str(said)[:200]) if said else ''), 'debug')

    # Going direct, the recipients' servers are looked up by the same DNS
    # servers that gave their MX records - A, AAAA and CNAME (1.0.23).
    # Only here, and only for mail going straight to the recipients, are
    # the DNS servers of `mail_dns` asked; with none set it is the system's
    # own resolver (/etc/hosts, nsswitch), as for everything else. (1.0.23)
    addrs = ()
    if direct:
        try:
            if own_dns():
                addrs = tuple(dns_addrs(host))
                how = 'DNS ' + ', '.join(own_dns())
            else:
                addrs = tuple(sorted({a[4][0] for a in socket.getaddrinfo(
                    host, port, 0, socket.SOCK_STREAM)}, key=lambda a: ':' in a))
                how = 'the system resolver'
            step('looked up %s' % host, True, ', '.join(addrs) + ' · ' + how)
        except (MailError, OSError) as e:
            step('look up %s' % host, False, e)
            raise MailError('no address found for %s: %s' % (host, e), steps)
    try:
        if security == 'tls':
            conn = _AddrSMTPS(local_hostname=helo, timeout=timeout, context=ctx)
            if debugging('codes'):
                conn.set_debuglevel(1)
            conn.deadline = began + 4 * timeout
            conn.addrs = addrs
            conn._host = host           # the name its certificate is checked against
            code, said = conn.connect(host, port)
            if code != 220:
                conn.close()
                raise smtplib.SMTPConnectError(code, said)
            step('reached %s:%d over TLS' % (host, port), True,
                 '%d ms' % int((time.time() - began) * 1000))
        else:
            conn = _AddrSMTP(local_hostname=helo, timeout=timeout)
            if debugging('codes'):
                conn.set_debuglevel(1)
            conn.deadline = began + 4 * timeout
            conn.addrs = addrs
            # The name STARTTLS checks the certificate against (1.0.96):
            # smtplib keeps the one given when it is made - none here, the
            # address is connected to - and every server that offered
            # STARTTLS failed: "server_hostname cannot be an empty string".
            conn._host = host
            code, said = conn.connect(host, port)
            if code != 220:
                conn.close()
                raise smtplib.SMTPConnectError(code, said)
            step('reached %s:%d' % (host, port), True,
                 '%d ms' % int((time.time() - began) * 1000))
    except ssl.SSLCertVerificationError as e:
        step('reach the server %s:%d over TLS' % (host, port), False,
             'its certificate is not trusted: %s' % e.verify_message)
        raise MailError('the certificate of %s is not trusted - add the authority that '
                        'signed it, or switch the check off' % host, steps)
    except (OSError, smtplib.SMTPException) as e:
        step('reach the server %s:%d' % (host, port), False, e)
        raise MailError('%s:%d could not be reached: %s' % (host, port, e), steps)
    try:
        code, said = conn.ehlo()
        step('greeted it as %s' % helo, 200 <= code < 300, said.decode('utf-8', 'replace')
             .split('\n')[0] if isinstance(said, bytes) else said)
        if security in ('starttls', 'starttls-if'):
            if conn.has_extn('starttls'):
                try:
                    conn.starttls(context=ctx)
                except ssl.SSLCertVerificationError as e:
                    step('started TLS', False, 'its certificate is not trusted: %s'
                         % e.verify_message)
                    raise MailError('the certificate of %s is not trusted - add the authority '
                                    'that signed it, or switch the check off' % host, steps)
                conn.ehlo()
                cert = conn.sock.getpeercert() if hasattr(conn.sock, 'getpeercert') else None
                who = ''
                if cert:
                    who = ', '.join('%s=%s' % kv for part in cert.get('subject', ())
                                    for kv in part if kv[0] == 'commonName')
                step('started TLS', True, (conn.sock.version() if hasattr(conn.sock, 'version')
                                           else '') + ((' · ' + who) if who else ''))
            elif security == 'starttls':
                step('start TLS', False, 'the server does not offer STARTTLS')
                raise MailError('%s does not offer STARTTLS - choose TLS from the start, or '
                                'none' % host, steps)
            else:
                step('stayed in plain text', True, 'the server does not offer STARTTLS')
                if auth and auth != 'none' and not direct:
                    # Not the password in plain text (1.0.94): a STARTTLS taken
                    # out on the way would have had it read off the wire.
                    step('sign in', False, 'not without TLS: the password would go in plain text')
                    raise MailError('%s offered no STARTTLS, and the password is not sent in '
                                    'plain text - choose STARTTLS (required) or TLS from the '
                                    'start, or Security none if a plain connection is meant'
                                    % host, steps)
        if auth and auth != 'none' and not direct:
            user = str(CONFIG.get('smtp_user') or '')
            pw = unseal_secret(CONFIG.get('smtp_password') or '') or ''
            offered = (conn.esmtp_features.get('auth') or '').upper().split()
            try:
                if auth == 'auto':
                    conn.login(user, pw)
                elif auth == 'xoauth2':
                    conn.auth('XOAUTH2', _xoauth2(user, pw), initial_response_ok=True)
                else:
                    conn.user, conn.password = user, pw
                    mech = {'plain': 'PLAIN', 'login': 'LOGIN', 'cram-md5': 'CRAM-MD5'}[auth]
                    fn = {'PLAIN': conn.auth_plain, 'LOGIN': conn.auth_login,
                          'CRAM-MD5': conn.auth_cram_md5}[mech]
                    conn.auth(mech, fn, initial_response_ok=(mech != 'CRAM-MD5'))
                step('signed in as %s (%s)' % (user, auth.upper()), True,
                     'it offers: %s' % (' '.join(offered) or 'nothing'))
            except smtplib.SMTPAuthenticationError as e:
                step('sign in as %s (%s)' % (user, auth.upper()), False,
                     '%s %s' % (e.smtp_code, (e.smtp_error or b'').decode('utf-8', 'replace')))
                raise MailError('the mail server did not take the account or the password',
                                steps)
            except smtplib.SMTPException as e:
                step('sign in as %s (%s)' % (user, auth.upper()), False,
                     '%s · it offers: %s' % (e, ' '.join(offered) or 'nothing'))
                raise MailError('signing in failed: %s' % e, steps)
        if msg is not None:
            refused = conn.send_message(msg, to_addrs=list(to))
            if refused:
                step('handed the message over', False, '; '.join(
                    '%s: %s' % (k, v) for k, v in refused.items()))
                raise MailError('the server refused %s' % ', '.join(refused), steps,
                                permanent=all(int((v or (0,))[0] or 0) >= 500
                                              for v in refused.values()))
            reply = getattr(conn, 'last_reply', None)
            said = ''
            if reply:
                said = ' · %s %s' % (reply[0], (reply[1] or b'').decode('utf-8', 'replace')
                                     if isinstance(reply[1], bytes) else reply[1])
            step('handed the message over', True, 'for %s%s' % (', '.join(to), said))
    except smtplib.SMTPRecipientsRefused as e:
        step('handed the message over', False, '; '.join(
            '%s: %s %s' % (k, v[0], v[1].decode('utf-8', 'replace') if isinstance(v[1], bytes)
                           else v[1]) for k, v in e.recipients.items()))
        raise MailError('the server would not take mail for %s' % ', '.join(e.recipients), steps,
                        permanent=all(int((v or (0,))[0] or 0) >= 500
                                      for v in e.recipients.values()))
    except smtplib.SMTPSenderRefused as e:
        step('handed the message over', False, '%s %s' % (e.smtp_code, (
            e.smtp_error or b'').decode('utf-8', 'replace')))
        raise MailError('the server would not take mail from %s' % e.sender, steps,
                        permanent=int(e.smtp_code or 0) >= 500)
    except (smtplib.SMTPException, OSError) as e:
        if not isinstance(e, MailError):
            step('talking to it', False, e)
            raise MailError('the conversation with %s broke off: %s' % (host, e), steps,
                            permanent=int(getattr(e, 'smtp_code', 0) or 0) >= 500)
        raise
    finally:
        try:
            conn.quit()
        except Exception:
            pass
        try:
            conn.close()        # the watchman goes too (1.0.103)
        except Exception:
            pass
    return steps


def mail_send(store, msg, to, mode=None):
    """Send `msg` to `to` ([addresses]) the way the settings say. Returns the
    steps; raises MailError with them where it failed."""
    mode = mode or CONFIG.get('mail_mode') or 'off'
    steps = []
    if mode == 'off':
        raise MailError('sending mail is switched off - Settings → Mail', steps)
    if mode == 'smtp':
        host = str(CONFIG.get('smtp_host') or '').strip()
        if not host:
            raise MailError('no mail server is set - Settings → Mail', steps)
        security = CONFIG.get('smtp_security') or 'starttls'
        port = int(CONFIG.get('smtp_port') or 0) or {'tls': 465, 'none': 25}.get(security, 587)
        return smtp_talk(store, host, port, security, CONFIG.get('smtp_auth') or 'auto', msg,
                         to, steps)
    # Straight to each domain's own server: one conversation per domain.
    by_domain = collections.OrderedDict()
    for one in to:
        by_domain.setdefault(one.rsplit('@', 1)[-1].lower(), []).append(one)
    port = int(CONFIG.get('mail_direct_port') or 25)
    for domain, who in by_domain.items():
        try:
            mxs, how = dns_mx_full(domain)
            mxs = [m for m in mxs if m[1] not in ('', '.')]
            if not mxs:
                raise MailError('%s takes no mail (its MX record is a null MX)' % domain,
                                permanent=True)
        except MailError as e:
            steps.append({'what': 'look up the mail servers of %s' % domain, 'ok': False,
                          'said': str(e)})
            raise MailError(str(e), steps, permanent=e.permanent)
        steps.append({'what': 'looked up the mail servers of %s' % domain, 'ok': True,
                      'said': ', '.join('%s (%d)' % (h, p) for p, h in mxs) + ' · ' + how})
        last = None
        # One deadline over every MX of the domain (1.0.59): four servers of
        # two addresses each at 20 s outlasted the page asking.
        deadline = time.time() + MAIL_DIRECT_DEADLINE_S
        for _pref, host in mxs[:4]:
            left = deadline - time.time()
            if left < 3:
                last = last or MailError('no time left to try %s' % host, steps)
                break
            try:
                smtp_talk(store, host, port,
                          'starttls' if CONFIG.get('mail_direct_tls') == 'required'
                          else 'starttls-if', 'none', msg, who, steps, direct=True,
                          timeout=min(float(CONFIG.get('smtp_timeout_s') or 20), left / 2))
                last = None
                break
            except MailError as e:
                last = e
        if last:
            raise MailError('no mail server of %s took it: %s' % (domain, last), steps,
                            permanent=getattr(last, 'permanent', False))
    return steps


# ---- the QR code as a picture every mail program shows ----------------------------
def qr_png(text, scale=8, border=4):
    """A PNG of the QR code: mail programs do not show SVG."""
    q = QrCode(text, 'M')
    size = q.size + border * 2
    width = size * scale
    rows = []
    for y in range(-border, q.size + border):
        line = bytearray()
        for x in range(-border, q.size + border):
            dark = 0 <= x < q.size and 0 <= y < q.size and q.modules[y][x]
            line += (b'\x00' if dark else b'\xff') * scale
        rows.extend([b'\x00' + bytes(line)] * scale)
    raw = b''.join(rows)

    def chunk(kind, data):
        body = kind + data
        return struct.pack('>I', len(data)) + body + struct.pack('>I', zlib.crc32(body)
                                                                & 0xffffffff)
    return (b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', width, width, 8, 0,
                                                            0, 0, 0))
            + chunk(b'IDAT', zlib.compress(raw, 9)) + chunk(b'IEND', b''))


